window.POEM_DB=window.POEM_DB||{};POEM_DB["song_030"]={"n":"楼钥","dyn":"宋","poems":[{"t":"刘寺即事 其一","f":"词","c":["不到兹山二十年，岂知重见旧山川。","烟深虽不见湖水，且看长空万里天。"]},{"t":"八月十四日携家泛月次韵 其三","f":"词","c":["稍先一日我中秋，行遍芙蓉与菊洲。","作意安排却非适，不如乘兴径行舟。"]},{"t":"八月十四日携家泛月次韵 其五","f":"词","c":["草草真成一段奇，比邻非不借馀辉。","板舆何敢侵风露，略望檐间且劝归。"]},{"t":"八月十四日携家泛月次韵 其一","f":"词","c":["月到平湖金作波，一城惟此占秋多。","水晶宫里清无比，何用重登汉馺娑。"]},{"t":"八月十四日携家泛月次韵 其四","f":"词","c":["犹记年时看水嬉，不如此夜月相宜。","仙翁一醉非尘世，为问姮娥知未知。"]},{"t":"八月四日晚霹雳碎大柳木","f":"词","c":["秋分雷自合收声，白露明朝忽震霆。","怪得坐中惊欲倒，邻墙老柳碎中庭。"]},{"t":"十月十七日夜","f":"词","c":["蛰虫坯户六经旬，掣电惊雷若莫春。","震起昆虫千百亿，不知何处更容身。"]},{"t":"又次郑性之悬尉韵 其一","f":"词","c":["槁项疲农病夏畦，喜闻烟雨四天垂。","旋寻粳稻供糜粥，惊见新香玉满匙。"]},{"t":"又次郑性之悬尉韵 其二","f":"词","c":["闵雨才宽又畏风，从朝愁到夕阳舂。","谁教官到二千石，不学当年邴曼容。"]},{"t":"又次郑性之悬尉韵 其三","f":"词","c":["几番好雨应先占，欣见阶庭绿草纤。","秋后阴晴犹未定，更看新月卧磨镰。"]},{"t":"又次郑性之悬尉韵 其四","f":"词","c":["爰居集鲁要先知，飞雪侵春久已疑。","惭愧风师幸安静，敢将虎口斗龙痴。"]},{"t":"上史太傅 其一","f":"词","c":["一坡烟水绿湾环，竹树楼台缥缈间。","但说一丘藏曲折，谁知更有四明山。"]},{"t":"上史太傅 其三","f":"词","c":["衮绣堂中语夜分，几将经史细评论。","不知世上三公贵，祇是东湖八行孙。"]},{"t":"上史太傅 其二","f":"词","c":["二十里云随步生，潺湲洞里访青棂。","山中要识无穷趣，看取南雷问答经。"]},{"t":"大雪赵振文寄诗言乘月泛舟清甚次韵 其一","f":"词","c":["老我心知笔力衰，颇欣腊雪瑞清时。","三茅奇观亦难遇，白玉峰头灯万枝。"]},{"t":"大雪赵振文寄诗言乘月泛舟清甚次韵 其三","f":"词","c":["雪光绝胜水银银，未觉仙家隔一尘。","真境宜君著佳句，赏心乐事更良辰。"]},{"t":"大雪赵振文寄诗言乘月泛舟清甚次韵 其二","f":"词","c":["万玉真妃摇佩琚，梁园授简属相如。","莫嫌一水限吴越，两岸交辉合太虚。"]},{"t":"大雪赵振文寄诗言乘月泛舟清甚次韵 其五","f":"词","c":["旧闻老具擅诗声，夜泛钱塘向凤城。","今日清游更豪逸，雪花和月带潮生。"]},{"t":"大雪赵振文寄诗言乘月泛舟清甚次韵 其四","f":"词","c":["见说中宵泛綵舟，何人同赏大江流。","阳冰伯雪应为伴，更约禅人白道猷。"]},{"t":"子成兄年八十六史子久八十二舅氏八十一会于适斋次韵二绝 其一","f":"词","c":["堂中三寿喜同时，黄发相逢齿更儿。","参坐共谈宣政旧，风流不许后生知。"]},{"t":"子成兄年八十六史子久八十二舅氏八十一会于适斋次韵二绝 其二","f":"词","c":["闾里旧游能几人，适斋犹有笔如神。","莫言二老升沈异，各现宰官居士身。"]},{"t":"小雨","f":"词","c":["好风先雨到危栏，却送残云过别山。","不用开襟强披拂，自然凉意满人间。"]},{"t":"小酌元卫弟听雨","f":"词","c":["小阁临流暑气清，藕花的的照人明。","移床更近栏边坐，要听棋声杂雨声。"]},{"t":"小溪道中 其二","f":"词","c":["后衕环村尽溯游，凤山寺下换轻舟。","舟人努力双篙急，引得清溪逆岸流。"]},{"t":"小溪道中 其一","f":"词","c":["簇簇苍山隐夕晖，遥看野雁著行归。","久之不动方知是，一搭碎云寒不飞。"]},{"t":"山阴道中 其一","f":"词","c":["昨望山阴古道中，蕺山直上最高峰。","今朝更踏山阴道，却向云间认八松。"]},{"t":"广轩夜望","f":"词","c":["点点万家灯，风清醉复醒。","广轩高绝处，俯瞰一天星。"]},{"t":"丹桂","f":"词","c":["碧云步障紫金蕤，风静秋高千万枝。","娇额涂黄元自好，是谁深传蜜烟脂。"]},{"t":"乌戍道中","f":"词","c":["田在港西家港东，断桥春水步难通。","束芦挟瓮稳来去，不碍小船分钓筒。"]},{"t":"从子沨送梅枝戏作","f":"词","c":["向来地暖见东嘉，带叶江梅殿岁华。","不似青春三月暮，南枝梅子北枝花。"]},{"t":"从子涤濯寒纳凉","f":"词","c":["杨柳阴阴映粉墙，密云藏雨晚来凉。","高荷欲出栏干上，笑挹红英吸净香。"]},{"t":"以十月桃杂松竹置瓶中照以镜屏用潚韵","f":"词","c":["中有桃源天地宽，杳然溪照武陵寒。","莫言洞府无由入，试向桃花背后看。"]},{"t":"以玉兰赠王习父 其二","f":"词","c":["华屋翚飞庆事绵，芝兰玉树喜庭前。","似闻楚畹芽初茁，便看蓝田生晚烟。"]},{"t":"以玉兰赠王习父 其一","f":"词","c":["一种香兰玉色新，仙家分得蕊宫春。","调高韵胜谁能称，付与能言解语人。"]},{"t":"元日","f":"词","c":["岁当庚午旦庚寅，最喜明朝遇上辛。","五福来临吴越分，更欣三日即攽春。"]},{"t":"午暑","f":"词","c":["炎官火伞罩中区，病老低垂气不苏。","难学孙儿频饮冷，时将冰水洗霜须。"]},{"t":"午睡戏作","f":"词","c":["早起三朝当一工，老来贪睡不相同。","偶然一次五更起，却用重眠到日中。"]},{"t":"午睡听雨","f":"词","c":["老年乐事莫如闲，午睡醒来梦已阑。","枕上欠伸犹懒起，更听檐外雨珊珊。"]},{"t":"双峰二偈 其二","f":"词","c":["道非身外亦非中，左右逢原作么逢。","绕寺寻山无好处，不知门外有双峰。"]},{"t":"双峰二偈 其一","f":"词","c":["莫把资深两处寻，此心心外更无心。","道人欲问资深话，自得元无古与今。"]},{"t":"天台道中口占","f":"词","c":["路上人家短竹篱，缫蚕刈麦自熙熙。","可怜日对千寻瀑，不解閒吟半字书。"]},{"t":"天姥岭","f":"词","c":["剡水迂回彻底清，滥觞从此一泓澄。","晓来蜡屐冲寒上，踏碎山头十里冰。"]},{"t":"太湖响石","f":"词","c":["何处飞来一段云，太湖风急到江城。","云中疑有群仙过，时听丁东环佩声。"]},{"t":"支茂先烟蓑亭","f":"词","c":["人生逆旅困风波，大似寄居鹦鹉螺。","月白江空无一事，不须更作钓鱼蓑。"]},{"t":"水蕉","f":"词","c":["猎猎水芭蕉，如将隐士招。","清风来处远，袢暑坐中消。"]},{"t":"王原庆诉盘餐萧然走笔次韵 其二","f":"词","c":["莫嗜鳆鱼如老曹，但应菜饭学参寥。","坡翁晚节更清苦，玉糁新羹手自调。"]},{"t":"王原庆诉盘餐萧然走笔次韵 其一","f":"词","c":["愁绝诗人太瘦生，也无北食与南烹。","君看俚语亦堪笑，何日能填鼻下横。"]},{"t":"长女淯归夫家寄以小诗","f":"词","c":["胡笳未了遽成归，妇职如何敢失期。","弹到佳声重入塞，伯喈未免念文姬。"]},{"t":"东阳遇雨","f":"词","c":["万壑千岩已饱看，更寻佳处为开颜。","无端早上一番雨，遮尽东阳县里山。"]},{"t":"写照叶处士求僧","f":"词","c":["几年依样画葫芦，自作葫芦学佛徒。","一笔从今勾断了，一瓶一钵任江湖。"]},{"t":"冯公岭","f":"词","c":["百级山田带雨耕，驱牛扶耒半空行。","不如身倚市门者，饱食丰衣过一生。"]},{"t":"半月轩","f":"词","c":["莫要作圆月，才圆却又亏。","不如作一半，犹有向圆时。"]},{"t":"古梅遗张时可","f":"词","c":["枝封苍藓澹花疏，一种风流高更孤。","试问约斋三百树，林中还有此枝无。"]},{"t":"叶处士画貂蝉喜神见惠","f":"词","c":["重烦妙手费丹铅，貌出衰容信宛然。","君看头颅已如许，岂堪头上著貂蝉。"]},{"t":"它山 其一","f":"词","c":["素蜺横卧作雷吼，日射细鳞银雪光。","安得此身如白鹭，修然终日在梅梁。"]},{"t":"它山 其二","f":"词","c":["过尽水禽并野凫，风标惟许一舂锄。","可怜久立梅梁上，不为溪光祇为鱼。"]},{"t":"正月庚申朔","f":"词","c":["春来节物一番新，今岁仍逢腊里春。","莫讶连宵清不寐，祇缘守岁守庚申。"]},{"t":"永嘉试院谢曾使君送酒 其一","f":"词","c":["一帘疏雨洗尘埃，满架酴醾自在开。","正恨烹茶杀风景，忽惊门外白衣来。"]},{"t":"示从子","f":"词","c":["东院敲棋西院琴，固知犹胜别劳心。","少年不比老痴叔，且向书窗惜寸阴。"]},{"t":"龙潭方丈","f":"词","c":["又因寒食此中来，窗户虚明绝点埃。","山里春风无閒断，海棠开过地棠开。"]},{"t":"再送潘恭叔","f":"词","c":["我似冥鸿弋犹慕，君如放鹤去还归。","秋空今日真成去，好伴闲云自在飞。"]},{"t":"刘寺即事 其二","f":"词","c":["飞泉何事仰空流，无数明珠散不收。","注辇昔时曾撒殿，至今抛掷未曾休。"]},{"t":"吊仅老塔","f":"词","c":["仅老相从五十期，来瞻遗塔我心悲。","当时旧话无人说，空有门前洗钵池。"]},{"t":"后圃","f":"词","c":["春雨才晴气已和，暖风吹动百花窠。","绝怜玉屑如吾发，绿者全稀白者多。"]},{"t":"戏作","f":"词","c":["二子为丞分越邑，女儿随婿过江南。","莫言屋里成岑寂，匹似当初只住庵。"]},{"t":"戏和三绝 其三 傀儡","f":"词","c":["假合阴阳有此身，使形全在气和神。","王家幻戏犹坚固，线索休时尚木人。"]},{"t":"戏和三绝 其一 脱索","f":"词","c":["缠缚千遭趁酒巡，环观巧手竞称神。","莫言名利如缰锁，猛烈抽身亦在人。"]},{"t":"戏和三绝 其二 藏擪","f":"词","c":["尽教逞技尽多般，毕竟甘心受面谩。","解把人间等嬉戏，不妨笑与大家看。"]},{"t":"戏题龙眠马性图","f":"词","c":["狗子已知无佛性，马又何曾有性来。","伯乐若来休著眼，任它骐骥混驽骀。"]},{"t":"戏赠张汉卿","f":"词","c":["张侯理窟妙无穷，雅谑于人亦有功。","渺渺江湖千万顷，未闻饿死信天公。"]},{"t":"早起戏作","f":"词","c":["枕稳衾温梦乍回，閒居不怕漏声催。","天明更欲从容睡，长被孙儿恼觉来。"]},{"t":"次仲舅韵寄拙庵 其二","f":"词","c":["明月堂前玉几山，倦游双径却来还。","舅甥相与成三隐，城郭山林等是闲。"]},{"t":"次仲舅韵寄拙庵 其三","f":"词","c":["公居山外我城中，不见成疏见亦空。","要是归来当一见，待携藜杖访支公。"]},{"t":"次仲舅韵寄拙庵 其一","f":"词","c":["涵秋古涧落珠旒，几欲相将作胜游。","芒屩未穿心已懒，不如莫莫且休休。"]},{"t":"次仲舅韵寄拙庵 其四","f":"词","c":["莫把坐忘成坐驰，归来须是识真归。","壶筹投尽无人拾，澹坐藤床风掩扉。"]},{"t":"次曾子固韵","f":"词","c":["惊见银河空外翻，奔湍千丈有馀寒。","下流不用长劳望，祇向悬崖顶上看。"]},{"t":"次韵十绝 其三 见客","f":"词","c":["客至何妨送与迎，门前罗爵亦人情。","可怜寒士犹相望，时有饥来柳絮轻。"]},{"t":"次韵十绝 其四 出谒","f":"词","c":["杜门却扫寖多时，间傍人门亦漫为。","茶灶笔床烟浪去，自疑身是老天随。"]},{"t":"次韵十绝 其二 发书","f":"词","c":["故人惟赖几行书，今日谁能更访吾。","旧日热心今就冷，向来已自得揶揄。"]},{"t":"次韵十绝 其一 休官","f":"词","c":["人生宁问草堂资，乞得闲身且径归。","惭愧舅甥俱就隐，澹然相对两忘机。"]},{"t":"次韵十绝 其七 安心","f":"词","c":["但使心如水在槃，坐令四体自然胖。","有人来问安心法，将汝心来与汝安。"]},{"t":"次韵十绝 其十 修养","f":"词","c":["闻道壶中别有天，能将俄顷比千年。","千年俄顷俱成梦，只任天真却晏然。"]},{"t":"次韵十绝 其九 染须","f":"词","c":["染须欲学少年时，笑杀当年荣启期。","公道世间惟此耳，年来犹幸不相欺。"]},{"t":"次韵十绝 其五 赴会","f":"词","c":["幸身未老已先闲，到处时时尽醉还。","更欲相邀莲社客，共寻精舍上孱颜。"]},{"t":"次韵四绝 其四 山亭纳凉","f":"词","c":["不嫌西照与朝曦，城郭谁知住翠微。","天幸外门才咫尺，欲陪杖屦夜忘归。"]},{"t":"次韵四绝 其三 从子澡涤筑屋荷池上","f":"词","c":["楼台墙宇家家月，杨柳荷花处处风。","最喜两涯相映带，一时倒影入池中。"]},{"t":"次韵四绝 其二 末莉花","f":"词","c":["江南创见喜孤芳，见说闽花遍海乡。","安得一居香盛处，帐中巧作宝毬妆。"]},{"t":"次韵四绝 其一 初得曾孙女","f":"词","c":["外子惟知愧可攻，羡公八十未衰癃。","曾孙喜见亲文褓，尚想当年掷镜翁。"]},{"t":"次韵蒋德言游太白玉几两山 其二","f":"词","c":["少日游山不要归，老来腰脚不相宜。","羡君胜具了无倦，踏雪寻幽更一奇。"]},{"t":"次韵蒋德言游太白玉几两山 其五","f":"词","c":["谁能饶舌强参禅，何用谈因更说缘。","生死本来无大事，晨朝须起夜须眠。"]},{"t":"次韵蒋德言游太白玉几两山 其三","f":"词","c":["剩欲扶筇随意行，要令心迹得双清。","何时同入翠微去，丈室先参老净名。"]},{"t":"次韵蒋德言游太白玉几两山 其四","f":"词","c":["落花影里步春阑，飞鸟翩翩相与还。","若得把茅成小隐，等閒来往两山间。"]},{"t":"次韵蒋德言壁间旧题","f":"词","c":["一铃檐角自吟风，两面松篁翠扫空。","山卉更藏无尽意，枝头未作去年红。"]},{"t":"次潘安叔寄新溪诗韵","f":"词","c":["曾游明月旧双溪，老去情怀百不宜。","梦绕新溪身不到，更休重和寄来诗。"]},{"t":"汪耐翁以最首座十玄谈见示","f":"词","c":["十首玄谈已赘疣，劳君头上更安头。","若还又有九百汉，葛藤相缠几时休。"]},{"t":"竹","f":"词","c":["蛰宫惊起两龙角，蛟室未呈双水犀。","同本君为分鲁卫，清风应不愧夷齐。"]},{"t":"红梅","f":"词","c":["南枝零落北枝残，失喜新蕤苦耐寒。","莫道北人浑不识，南人几作杏花看。"]},{"t":"行香闻杜鹃","f":"词","c":["墙西绿树杜鹃声，老我何堪侧耳听。","我自赋归归不得，不须苦语更丁宁。"]},{"t":"观云寄简讲师","f":"词","c":["苍狗俄然又白衣，来从何处去何归。","无心出岫还归去，莫向秋风说是非。"]},{"t":"观冷泉亭放水","f":"词","c":["冷泉浅浊使人愁，开板黄波去不休。","岸侧细泉穿乱石，始知别是一清流。"]},{"t":"访留昭文于范村山閒不得见","f":"词","c":["黄扉处士掩松关，小立松风去住难。","可叹山中真宰相，未容神武挂衣冠。"]},{"t":"过上虞怀谢驿喜雨","f":"词","c":["梦回檐溜作惊湍，净洗炎歊百虑宽。","咫尺东山见膏泽，令人更忆谢家安。"]},{"t":"过从子泽家","f":"词","c":["楚楚初篁脱绿苞，城居约略似荒郊。","土膏更得春风力，直引蔷薇上竹梢。"]},{"t":"过苍岭 其二","f":"词","c":["崇朝辛苦上孱颜，泥径初平意暂閒。","苍岭东头移野步，眼前便得处州山。"]},{"t":"过苍岭 其一","f":"词","c":["黄云满坞沙田稻，白雪漫山荠菜花。","路人缙云频借问，碧香酒好是谁家。"]},{"t":"过故家","f":"词","c":["团团桂树拥檐牙，旧日轻黄满树花。","惆怅秋清无一叶，空馀枯蘖缒寒瓜。"]},{"t":"佛日山","f":"词","c":["晓出都城暮入山，杖藜萧散易开颜。","松风五里未行尽，隐隐疏钟紫翠间。"]},{"t":"即事","f":"词","c":["十日阴寒雪不成，腊残春近更霜晴。","深山高卧如春暖，绕鬓飞蚊自在鸣。"]},{"t":"即事","f":"词","c":["壮志摧颓貌亦衰，岂知官舍傍岩隈。","此身不是京尘里，饭了沿山看腊梅。"]},{"t":"即事","f":"词","c":["芸芸物态见天机，静里工夫得细微。","阶下秋红千万点，游蜂一一采香归。"]},{"t":"启霞冰壶亭","f":"词","c":["拍拍新漪彻底清，两山写照翠光凝。","笑看风动縠纹起，坐我玉壶春夜冰。"]},{"t":"妙峰亭","f":"词","c":["一峰高出白云端，俯瞰天涯千万山。","试向冈头转圆石，不知何日到人间。"]},{"t":"忘归亭","f":"词","c":["一峰凛凛插烟霏，谁筑新亭占石矶。","标榜未应专一壑，此山何处不忘归。"]},{"t":"杨花 其一","f":"词","c":["雨压轻寒春较迟，春深不见柳绵飞。","忽然飞入閒庭院，疑是故人何处归。"]},{"t":"杨花","f":"词","c":["杜门无绪看芳菲，见说杨花满路飞。","谢汝不随人冷暖，因风翻舞到柴扉。"]},{"t":"杨花 其四","f":"词","c":["野芳庭草是生涯，老去祇宜闲在家。","几日惜春留不住，小鬟为我拾杨花。"]},{"t":"杨花 其二","f":"词","c":["柳绵无数糁枝头，日暖随风扑画楼。","万象可观惟有雪，喜看晴昼满空游。"]},{"t":"杨花 其三","f":"词","c":["为我轻攀绿柳枝，带花低护笑携归。","日长深院微风动，要看松绵当面飞。"]},{"t":"灵光","f":"词","c":["鲁邦宫殿久芜荒，惟有灵光最久长。","身似灵光终变灭，岿然别有一灵光。"]},{"t":"陈留柏","f":"词","c":["驿门深闭柏参天，月可中庭夜影圆。","人静好风喧客枕，坐令归梦到林泉。"]},{"t":"京仲远尚书为澹然子作二大字","f":"词","c":["浓墨新题付澹然，松坡为子老谈天。","凭君推我行年看，何日归耕绵上田。"]},{"t":"夜读王承家县丞诗编 其一","f":"词","c":["向来深夜快挥犀，不听清谈又许时。","净洗昏眸急呼烛，为君读尽一编诗。"]},{"t":"夜读王承家县丞诗编 其二","f":"词","c":["鍊句工深兴味长，固知家学富青箱。","莫言一脔能尝鼎，更欲为余倾锦囊。"]},{"t":"枕上","f":"词","c":["不守庚申不坐禅，老来触事总悠然。","天明门外无来客，尽好萧萧听雨眠。"]},{"t":"范牛","f":"词","c":["人问吾何爱一牛，范仙真笔倍风流。","绳牵虽未如自放，犹胜更著金笼头。"]},{"t":"试俞珣长头笔","f":"词","c":["倦游俞老又中州，霜兔抽豪饱盛秋。","平日相亲管城子，结交今得贾长头。"]},{"t":"金蹄","f":"词","c":["金蹄垂耳小韩卢，饰以重镮驯可呼。","谁击冬青碧阴下，恍然如见击梧图。"]},{"t":"客省听燕乐","f":"词","c":["晓入金门拜紫宸，门前错立士如云。","未容密侍君王宴，祇许钧天隔殿闻。"]},{"t":"庭前一莲著花","f":"词","c":["门外荷莲浥露华，绿云平地拥秋霞。","病夫不能出门去，且看庭前第一花。"]},{"t":"括苍烟雨楼","f":"词","c":["莫为看山只凭栏，远怀犹恨两山间。","坐深却得无穷趣，祇看平川一半山。"]},{"t":"春雨 其一","f":"词","c":["石斗微微覆浅沙，兰丛短短茁青芽。","春花著眼未云久，花事于人渐有涯。"]},{"t":"春雨 其二","f":"词","c":["漫漫平湖接远天，濛濛细雨湿轻烟。","野桥横著草深外，何处渡头人上船。"]},{"t":"昼寝","f":"词","c":["弹彻悲风更广陵，沧浪一为濯尘缨。","邯郸枕上梦初觉，喜听檐閒秋雨声。"]},{"t":"洛社老僧听琴 其一","f":"词","c":["宴坐萧斋不作劳，谓予何事走蓬蒿。","从容试问今年几，手植黄杨三丈高。"]},{"t":"洛社老僧听琴 其二","f":"词","c":["自言几载不闻琴，屡听清弹苦契心。","少待庭柯蝉噪静，为师更作醉翁吟。"]},{"t":"省宿","f":"词","c":["树满茅山绿正肥，昏鸦日日向南归。","如今身在三茅外，却看归鸦正北飞。"]},{"t":"贺监湖上 其二","f":"词","c":["狂客归来终好夸，越王城下占烟霞。","此中信美非吾土，不似西湖是我家。"]},{"t":"贺监湖上 其一","f":"词","c":["万顷平湖一苇杭，此归喜似贺知章。","上恩赐与西湖曲，遂老吾家归照堂。"]},{"t":"送一老住庐山归宗 其四","f":"词","c":["归宗法窟寖湮微，拭眼馀风靡孑遗。","法鼓一声精彩变，要如光弼用军时。"]},{"t":"送一老住庐山归宗 其五","f":"词","c":["庐山面目非难识，横岭侧峰皆是真。","若待出来方识破，不知何用个中人。"]},{"t":"送一老住庐山归宗 其三","f":"词","c":["千古名山大道场，止因赋重遂荒凉。","后之君子谁能弛，试向山前问老苍。"]},{"t":"送一老住庐山归宗 其二","f":"词","c":["啐啄同时不偶然，史君提起正当年。","向来闹市难行道，今日人天听说禅。"]},{"t":"送一老住庐山归宗 其一","f":"词","c":["久向东山捲藏经，鬼神推出举军惊。","从来要去庐山住，好就山中过此生。"]},{"t":"送卫清叔著作提举淮东 其一","f":"词","c":["汉庭早已冠群仙，阔步登瀛最少年。","窃叹岂惟年叵及，人门才业总翘然。"]},{"t":"送卫清叔著作提举淮东 其二","f":"词","c":["通泰牢盆亘海滨，宅家专欲用儒臣。","淮南草木生颜色，又见龙头第一人。"]},{"t":"送卫清叔著作提举淮东 其四","f":"词","c":["羡君持节拜庭闱，未老双亲看綵衣。","若过盖公烦问信，坐曹日念旧游稀。"]},{"t":"送卫清叔著作提举淮东 其五","f":"词","c":["屡从樽酒接从容，叔宝风姿照座中。","他日相逢年益老，棋坛尚可角雌雄。"]},{"t":"送卫清叔著作提举淮东 其三","f":"词","c":["虎榜先登到凤池，前良多以十年期。","虽知勇退急流去，壮岁功名会及时。"]},{"t":"送朱叔止守南剑 其四","f":"词","c":["下水上山腰带州，人家无数起危楼。","遨头不用喧箫鼓，祇把清诗纪胜游。"]},{"t":"送朱叔止守南剑 其二","f":"词","c":["槜李曾蜚剸剧声，贰车仍赞虎头城。","朱轓小试承流手，要继桐乡循吏名。"]},{"t":"送朱叔止守南剑 其三","f":"词","c":["万竹蟠山喉不乾，两龙潜水气犹寒。","郡斋见说真图画，公退何妨一倚栏。"]},{"t":"送朱叔止守南剑 其五","f":"词","c":["同盟东下或西征，老我惟知管送迎。","祇恐政成登省户，未容归骑向西城。"]},{"t":"送朱叔止守南剑 其六","f":"词","c":["名画法书知几编，俸馀宁复计求田。","麻沙剩买新文字，归满米家书画船。"]},{"t":"送朱叔止守南剑 其一","f":"词","c":["舍人簪笔旧甘泉，家学相传子姓贤。","未羡夹河为太守，阿连剖竹向封川。"]},{"t":"送朱季公守封川 其一","f":"词","c":["韶阳生长十馀年，城郭重经固宛然。","叹息紫微仙去久，尚馀遗墨照山川。"]},{"t":"送朱季公守封川 其五","f":"词","c":["妙舞清歌有二姝，后堂曾见绣罗襦。","岭南太守风流胜，不用归舟载绿珠。"]},{"t":"送朱季公守封川 其四","f":"词","c":["吾乡棋社寖凋零，赖有朱家好弟兄。","举酒看看故人少，阳关莫唱断肠声。"]},{"t":"送朱季公守封川 其二","f":"词","c":["桐乡汉有大司农，封守今推陈秀公。","君向邦人著遗爱，近追相业远家风。"]},{"t":"送朱季公守封川 其三","f":"词","c":["乡评久说雁行贤，剖竹封川与剑川。","不用对床风雨约，政成同取旧青毡。"]},{"t":"送林子方吏部将漕江东 其四","f":"词","c":["殿庐官烛对风帘，郎舍修篁共一檐。","别日苦多良晤少，掺袪不耐雨纤纤。"]},{"t":"送林子方吏部将漕江东 其二","f":"词","c":["望郎三度到长安，垂上青云作好官。","暂向江东一澄按，却归径著侍臣冠。"]},{"t":"送林子方吏部将漕江东 其一","f":"词","c":["光尧三纪焕文章，宝阁岧峣谨秘藏。","寓直到君才第四，皇华礼乐远增光。"]},{"t":"送林子方吏部将漕江东 其三","f":"词","c":["自说嵇康七不堪，上教持节向江南。","江南父老应相贺，见说清明似晦庵。"]},{"t":"送赵晦之丞彭泽 其三","f":"词","c":["陶令居官八十日，始为督邮方赋归。","君家门户要兴起，未用飘然咏式微。"]},{"t":"送赵晦之丞彭泽 其一","f":"词","c":["淮甸归来涉学深，孤云又出亦何心。","公馀岩下读书去，远继风流石橘林。"]},{"t":"送赵晦之丞彭泽 其二","f":"词","c":["渊明事晋肯臣刘，仁杰忠良不附周。","见说三贤参羽士，盍将吴簿配蘋羞。"]},{"t":"送赵清臣宰姚江 其四","f":"词","c":["才刃恢恢妙拨烦，邻封抚字尚何难。","更能触事加长虑，自有甘棠向后看。"]},{"t":"送赵清臣宰姚江 其五","f":"词","c":["妇家故步懒重寻，藏拙年来恐不深。","短棹有时乘兴去，径登竹所听鸣琴。"]},{"t":"送赵清臣宰姚江 其一","f":"词","c":["玉立君家好弟兄，蓝田风采照花城。","版舆寿母人间盛，千里何曾去送迎。"]},{"t":"送赵清臣宰姚江 其三","f":"词","c":["长江东去跨虹桥，千丈横堤捍海潮。","更向烛溪图永利，坐令百里沸歌谣。"]},{"t":"送赵清臣宰姚江 其二","f":"词","c":["鄞江水与舜江通，久矣威名满一同。","试问何时到封部，数声柔橹一帆风。"]},{"t":"送雪窦璧老住雪峰","f":"词","c":["雪窦移将住雪峰，两山雪色本皆同。","莫言此去人千里，明月往来含太空。"]},{"t":"送黄真护道人住茅山赠以小黑玉虎","f":"词","c":["少从黑虎谷中行，晚得于菟玉琢成。","辍以赠君俱隐处，大茅峰顶看风生。"]},{"t":"送黄景声秘丞提举浙西 其四","f":"词","c":["论诗才了便谈禅，鄙吝冰消更豁然。","稽首心空先及第，敢将癸未论同年。"]},{"t":"送黄景声秘丞提举浙西 其五","f":"词","c":["玉节光华照日曦，扬清激浊正当时。","阿连幸出百僚底，正恐翁归不受私。"]},{"t":"送黄景声秘丞提举浙西 其二","f":"词","c":["宅家亲擢得真才，柏府兰堂更外台。","未问遄驱向沟壑，半途应有诏书催。"]},{"t":"送黄景声秘丞提举浙西 其三","f":"词","c":["从来轩冕一毫轻，朝迹初收去玉京。","打破画瓶无个事，不妨游戏绣衣行。"]},{"t":"闾丘医视脉曰老人之脉如小春有感","f":"词","c":["老去光阴似小春，如何比得少年人。","君看桃李秋风后，纵有花开不是真。"]},{"t":"唤仙阁 其一","f":"词","c":["上到危层莫唤仙，祇凭横槛挹江天。","江天如许来借眼，何用征侨更偓佺。"]},{"t":"唤仙阁 其二","f":"词","c":["多少寻仙更不还，渺茫竟堕有无閒。","使其真有毋庸唤，仙自曾城我自山。"]},{"t":"晓雾","f":"词","c":["晓雾冥濛水拍堤，棱嶒乱石与云齐。","扁舟不用兼程去，到得稽城日已西。"]},{"t":"海棠 其二","f":"词","c":["海棠初发为题诗，倏见轻红万点吹。","已惜落英铺满地，更怜几片罥蛛丝。"]},{"t":"海棠 其一","f":"词","c":["海棠昨日始萌芽，一夜惊雷发万葩。","老眼恍然何所得，凌云庵外见桃花。"]},{"t":"病后戏作","f":"词","c":["河鱼腹疾未全除，一饭充饥不愿馀。","纵有珍羞难下箸，真成顿顿食黄鱼。"]},{"t":"病告","f":"词","c":["闭户垂帘尽自如，兀然终日拥红炉。","得归足可优游老，此地何堪养病躯。"]},{"t":"酒边戏作","f":"词","c":["未年六十已言归，七十重来自觉痴。","未报君恩归未许，樽前羞听摸鱼儿。"]},{"t":"宿仙居民家","f":"词","c":["投暝人家欲睡时，雨声不断水平池。","回头已过三江渡，醉看车中总不知。"]},{"t":"常禅师塔 其二","f":"词","c":["从来猛虎性坚刚，据石依林死不僵。","何待寒林班侍者，千年陪葬祖师傍。"]},{"t":"常禅师塔 其一","f":"词","c":["当时道价极光华，鸷兽相随共一家。","象去虎亡师亦老，不须百鸟更衔花。"]},{"t":"晚步少微阁","f":"词","c":["落日谢虚阁，横琴相对閒。","片云将急雨，一笑失前山。"]},{"t":"梅仙岩","f":"词","c":["梅山遗迹若为寻，怪石崚嶒一径深。","未必当时真隐处，清风自觉袭衣襟。"]},{"t":"淯月下鼓琴用淳韵","f":"词","c":["老稚团栾鲤在庭，文姬为鼓玉琴声。","起来同作悲风曲，倍觉先秋月影清。"]},{"t":"菁江迓客","f":"词","c":["菁江十里路逶迟，两岸平畴接翠微。","赢得闲中乘画舫，随潮西上趁潮归。"]},{"t":"鹿伯可郎中园池杂咏 三友径","f":"词","c":["公是端人友必端，世情冷暖不相干。","虽云门外可罗雀，三益还能耐岁寒。"]},{"t":"鹿伯可郎中园池杂咏 小东山","f":"词","c":["安石东山志不渝，归来寻得静工夫。","从教更为苍生起，携妓何妨且自娱。"]},{"t":"鹿伯可郎中园池杂咏 云龛","f":"词","c":["浮云舒卷原无定，此意谁能为饱参。","出岫无心归亦尔，不妨今日与同龛。"]},{"t":"鹿伯可郎中园池杂咏 月沼","f":"词","c":["玉洁冰清一壑专，箨龙何处引涓涓。","深知月满还亏缺，祇学蟾光一半圆。"]},{"t":"鹿伯可郎中园池杂咏 止室","f":"词","c":["流行坎止事无多，举世营营自网罗。","珍重主人真止矣，直如古井更无波。"]},{"t":"鹿伯可郎中园池杂咏 见一堂","f":"词","c":["灵澈清诗千载传，始闻林下有斯贤。","傍人只道休官早，见一名堂已十年。"]},{"t":"鹿伯可郎中园池杂咏 松岭","f":"词","c":["翠云深处曳枯筇，插碧堂堂十八公。","全似华阳隐君子，挂冠归去听松风。"]},{"t":"鹿伯可郎中园池杂咏 星潭","f":"词","c":["山头分下一泓清，石甃团团瞰小亭。","身在赤城名绛阙，至今潭影照郎星。"]},{"t":"鹿伯可郎中园池杂咏 柑隅","f":"词","c":["霜著芳苞翠作围，数椽潇洒映斜晖。","木奴何必须千树，乞得閒身径且归。"]},{"t":"鹿伯可郎中园池杂咏 桂堂","f":"词","c":["芳树丛生庭砌间，高枝更许后来攀。","主人勿恋山中桂，招隐还应看小山。"]},{"t":"鹿伯可郎中园池杂咏 桃蹊","f":"词","c":["几树桃花相映开，主人归路入天台。","凭谁寄语玄都观，前度刘郎不更来。"]},{"t":"鹿伯可郎中园池杂咏 梅坡","f":"词","c":["江梅留待主人还，见说归时得饱看。","回首残花飞作雪，一峰当户正高寒。"]},{"t":"渡扬子","f":"词","c":["江豚吹浪雨飕飗，望断天涯人白头。","一舸乘风渡扬子，数鸥导我过瓜州。"]},{"t":"游大梅山护圣寺 其二","f":"词","c":["寒云片日忽吹开，历井扪参得得来。","行尽高山天欲半，不知平地有楼台。"]},{"t":"游大梅山护圣寺 其一","f":"词","c":["江东东畔更东山，又过东山数里间。","试问招提在何处，万山深处白云环。"]},{"t":"游金焦两山以雨而辍","f":"词","c":["金山寺裹山，焦山山裹寺。","风雨劝我归，也省两头事。"]},{"t":"登马鞍岭","f":"词","c":["轧轧轻舆上马鞍，半天岚翠逼人寒。","从教宿霭迷清嶂，明日晴空取意看。"]},{"t":"答东山一老二偈 其二","f":"词","c":["闭门深坐日知味，无限好山都懒游。","城里山中俱是隐，江湖不若两忘休。"]},{"t":"答东山一老二偈 其一","f":"词","c":["即心是佛本无难，挫却丝毫隔万山。","知有毗卢五千卷，谁能分寸费跻攀。"]},{"t":"答杖锡平老","f":"词","c":["老我平生不愿馀，归来但欲赋闲居。","灌园自足供朝膳，且奉夫人御版舆。"]},{"t":"谢少微兄惠牡丹 其一","f":"词","c":["乍观泉石分新种，想为黟山忆旧葩。","病后不妨风韵在，此花之外更无花。"]},{"t":"谢少微兄惠牡丹 其二","f":"词","c":["方剪栏干第四花，玉人联袂过吾家。","捻红玉翼皆名品，醉眼相看到日斜。"]},{"t":"谢少微兄惠牡丹 其三","f":"词","c":["箫鼓声中醉九旬，落红万点正愁人。","眼明忽见倾城色，更向尊前作好春。"]},{"t":"谢林景思和韵","f":"词","c":["黄昏门外六花飞，困倚胡床醉不知。","冻合玉楼犹强项，拥衾方咏雪巢诗。"]},{"t":"谢袁起岩侍郎送盆栀奉老母","f":"词","c":["翠绡飞盖拥生香，冰雪精神试晚妆。","鹤发慈亲俄一笑，玉人何事晚升堂。"]},{"t":"谢舒景叔写照见赠","f":"词","c":["谁写衰容入画图，本来面目旧形模。","几年老瘦鬓如雪，不道今吾非故吾。"]},{"t":"谢潘端叔惠红梅 其二十","f":"词","c":["自昔梅花雪作团，红梅晚出可人看。","江梅不解追时好，祇守冰姿度岁寒。"]},{"t":"谢潘端叔惠红梅 其十八","f":"词","c":["只说梅花似雪飞，朱颜谁信暗香随。","不须添上徐熙画，付与西湖别赋诗。"]},{"t":"谢潘端叔惠红梅 其四","f":"词","c":["前身施粉忌太白，今日施朱恐太红。","说似旁人刚不信，清香万斛在花中。"]},{"t":"谢潘端叔惠红梅 其五","f":"词","c":["殿后鞓红色漫秾，绛桃空自笑春风。","何人击碎珊瑚树，恼得瑶姬面发红。"]},{"t":"谢潘端叔惠红梅 其十二","f":"词","c":["坡翁著意赋三诗，谩说秾香已透肌。","若见此花应绝倒，惜君生晚不逢时。"]},{"t":"谢潘端叔惠红梅 其十七","f":"词","c":["诗老为花空自忙，想应未识此奇芳。","青枝绿叶何须辨，桃杏安能如许香。"]},{"t":"谢潘端叔惠红梅 其十三","f":"词","c":["花品无庸定等差，国香国色属吾家。","海棠正自惭粗俗，莫问漫山桃李花。"]},{"t":"谢潘端叔惠红梅 其十五","f":"词","c":["客来试与倚栏干，拂拂清香触鼻端。","尽做北人浑不识，不应敢作杏花看。"]},{"t":"谢潘端叔惠红梅 其三","f":"词","c":["为君手种向南堂，误认昌州移海棠。","元是玉妃生酒晕，帐中仍带返魂香。"]},{"t":"谢潘端叔惠红梅 其九","f":"词","c":["初移湘水一枝春，剩馥还欣为我分。","梦入山房三十树，何时醉倒看红云。"]},{"t":"谢潘端叔惠红梅 其十九","f":"词","c":["缟裙练帨玉为肌，谁点微赪向北枝。","若使罗虬见颜色，定须将此比红儿。"]},{"t":"谢潘端叔惠红梅 其十四","f":"词","c":["不学江头玉树寒，寿阳红粉旧妆残。","婵娟可是惭随俗，莫作金沙锁骨看。"]},{"t":"谢潘端叔惠红梅 其二","f":"词","c":["黄姑曾为点冰肌，亦有缁尘染素衣。","何似烟脂天赐与，暗香犹在是耶非。"]},{"t":"谢潘端叔惠红梅 其一","f":"词","c":["旧家桃李种河阳，今日红梅自楚湘。","根垡送春君意重，为移绝艳到吾乡。"]},{"t":"谢潘端叔惠红梅 其六","f":"词","c":["旧见寒花蜡蒂红，宁知沁入雪肤中。","绝怜金谷佳人坠，到地馀香散晓风。"]},{"t":"谢潘端叔惠红梅 其七","f":"词","c":["梅花几种尽相闻，老矣才欣见此君。","相与对花文字饮，绝胜歌舞醉红裙。"]},{"t":"谢潘端叔惠红梅 其十六","f":"词","c":["全体江梅腊里芳，紫绵新拂汉宫妆。","临川借得江梅句，倾国天教抵死香。"]},{"t":"谢潘端叔惠红梅 其八","f":"词","c":["人閒丹桂亦微黄，未见红葩解有香。","惟喜此花兼众美，麝脐薰彻绛纱囊。"]},{"t":"谢潘端叔惠红梅 其十一","f":"词","c":["少陵年后咏花开，未见烟脂一抹腮。","可惜当时诗兴动，止因东阁看官梅。"]},{"t":"慈溪道中","f":"词","c":["双橹真成鹅鹳鸣，客愁厌苦梦魂惊。","须臾寖觉耳根熟，一觉醒来天已明。"]},{"t":"殿上侍立寒甚","f":"词","c":["小雪以来霜气清，今朝寒色倍严凝。","榻前侍立无遮障，吹得半身真是冰。"]},{"t":"殿上闻杜鹃","f":"词","c":["衰晚三年侍玉墀，高梧又擢凤凰枝。","封章屡上未容去，更向殿头闻子规。"]},{"t":"蕉庵清坐","f":"词","c":["薄晚归来烟已苍，蛮蕉一叶障斜阳。","不须久住潭潭府，始觉山林兴味长。"]},{"t":"蕉庵暮归","f":"词","c":["绿蕉阴下绕斑衣，饭了从容到夕晖。","老子才携筇杖去，孙儿各捧竹团归。"]},{"t":"题从子浃娱亲","f":"词","c":["阿戎筑屋为娱亲，野草闲花日日新。","我奉版舆来举酒，祈君亲寿似夫人。"]},{"t":"题龙眠画西域圣僧","f":"词","c":["放两不借叠双足，自在在心机在目。","默然深入不二门，不知师唱谁家曲。"]},{"t":"题孙谷桥墦间图 其一","f":"词","c":["墦间不足又之他，犹自施施骄室家。","齐国一人如许尔，宁知后日事如麻。"]},{"t":"题孙谷桥墦间图 其二","f":"词","c":["因知义利本殊途，莫笑墦间乞祭徒。","正使往来多显者，此中尤要著工夫。"]},{"t":"题老融归牛图","f":"词","c":["薄宦六年辞故山，故山祇在梦魂间。","簪绅何苦自缠缚，却羡归牛自在閒。"]},{"t":"题宏老空谷","f":"词","c":["君看空谷自然空，声有洪纤应则同。","正为中虚声自应，莫将应处做神通。"]},{"t":"题汪宏甫三马图","f":"词","c":["玉花流云照夜白，开元尚想行天街。","韩李郑君俱已矣，健笔谁能如顺斋。"]},{"t":"题汪季路太傅所藏龙眠阳关图 其一","f":"词","c":["离觞别泪为君倾，行李匆匆欲问程。","不用阳关寻旧曲，图中端有断肠声。"]},{"t":"题汪季路太傅所藏龙眠阳关图 其二","f":"词","c":["画出阳关古别离，萧疏柳质不胜悲。","行人顾叹离人泣，柳下渔翁总不知。"]},{"t":"题汪季路尚书所藏米元晖湖山瑞雪图","f":"词","c":["笔力谁能似虎儿，思陵亲为御珍题。","小臣不识湖山好，但欲扁舟泛剡溪。"]},{"t":"题汪季路尚书所藏米元晖蒋山出云","f":"词","c":["龙盘往昔名钟山，云起从龙意自闲。","肤寸须臾成戴帽，坐看膏雨满人间。"]},{"t":"题陈简斋寄夫人书","f":"词","c":["行书满纸遗君文，可见闺门敬若宾。","应与少文能协趣，定因元亮遂忘贫。"]},{"t":"题林宗鲁校书所藏宣和御画","f":"词","c":["周公多艺孔多能，徽庙才高更倍增。","除却万机都不会，至今遗老话昭陵。"]},{"t":"题贺监李谪仙二像 其二","f":"词","c":["斗酒浇诗动百篇，鉴湖牛渚两俱仙。","早知今日犹相对，不向稽山回酒船。"]},{"t":"题贺监李谪仙二像 其一","f":"词","c":["不有风流贺季真，更谁能识谪仙人。","金龟换酒今何在，相对画图如有神。"]},{"t":"题施武子所藏老融二牛图 其一","f":"词","c":["佳哉淡墨扫人牛，一笛横风各自由。","平日深知焉用稼，如今但欲老西畴。"]},{"t":"题施武子所藏老融二牛图 其二","f":"词","c":["乌犍离立意逶迟，鞭策俱忘取次归。","騃犊跳风仍却顾，老融于此露天机。"]},{"t":"题赵睎远二画 其二 墨梅","f":"词","c":["窗前惊见一枝斜，照眼英英十数花。","千载简斋仙去后，何人更著好诗誇。"]},{"t":"题赵睎远二画 其一 鱼扇","f":"词","c":["藻翻数尾已如生，妙绝鱼儿作队行。","不是深知濠上趣，未应笔底得纵横。"]},{"t":"题徐圣可知县所藏杨补之二画 其二","f":"词","c":["梅花屡见笔如神，松竹宁知更逼真。","百卉千华皆面友，岁寒祇见此三人。"]},{"t":"题徐圣可知县所藏杨补之二画 其一","f":"词","c":["谁种疏梅古岸头，推蓬瞥见倍清幽。","君看竹外一枝好，真有江南万斛愁。"]},{"t":"题萝月上人送鸿小楼","f":"词","c":["雨洗春山空翠新，登楼不见送鸿人。","薜萝清夜月依旧，无复新诗泣鬼神。"]},{"t":"潚自剡川寄水晶蒲萄","f":"词","c":["马乳从他堆满盘，未如清嚼水晶寒。","固知一县蒲萄熟，不用劳人数问安。"]},{"t":"赠丁相士","f":"词","c":["相形何似且论心，眼力工夫见浅深。","古怪清奇任君说，灵台一片若为寻。"]},{"t":"赠于湖刘相士","f":"词","c":["自笑今年卦气阑，壮心销尽鬓毛残。","明知七十无多子，只问何时可挂冠。"]},{"t":"赠龙游术士胡杲","f":"词","c":["方笑刘郎问大钧，从来祸福本无门。","世閒生老病死苦，时至即行何足论。"]},{"t":"赠别章茂献尚书","f":"词","c":["我辈重来鬓已皤，贞元朝士苦无多。","才堪柱石犹归去，柰此摧颓一老何。"]},{"t":"赠陈居靖道人","f":"词","c":["沩汭道人身御风，弃家求静慕仙踪。","仙都有石立天半，特立要当如此峰。"]},{"t":"赠画梅吕生","f":"词","c":["西湖处士赋疏影，未似希真好乐章。","岂是无情甘澹泊，受它风月几凄凉。"]},{"t":"赠郑相士","f":"词","c":["知君冰鉴照人寒，我相儒酸未足观。","东甬从来多俊秀，为烦著眼细寻看。"]},{"t":"赠凌一源道人","f":"词","c":["知君曾住武当山，更解寻幽灊皖閒。","老矣无缘穷胜处，但思归去卧乡关。"]},{"t":"赠徐松","f":"词","c":["我为浮名愧引年，老馀八十尚飘然。","不如合却谈天口，归向白云深处眠。"]},{"t":"丁寺丞挽词 其一","f":"词","c":["家世传经术，胶庠蔼隽声。","上方思旧学，公乃擅专城。","滁上功尤著，潮阳政愈明。","哀哉锷流水，犹解不平鸣。"]},{"t":"丁寺丞挽词 其二","f":"词","c":["严冷不可向，其中实旷然。","行藏睽素志，燕乐了馀年。","鹤化人何处，鸾孤影自怜。","才高不尽用，流庆尚绵绵。"]},{"t":"九月十一日杓孙得男","f":"词","c":["郡斋弧矢记垂门，今日衰翁更觉尊。","生晚不能瞻大父，年高却幸见曾孙。","从今镜镊知无用，但喜芝兰近愈繁。","愿汝孳孳守家法，为传衣钵到仍昆。"]},{"t":"入雁山过双峰","f":"词","c":["眼前未见古龙湫，望望前山景自幽。","红日一门千嶂晓，翠峰双耸半空秋。","风高落木无边下，气劲閒云逐处收。","要识雁山真面目，直须霜后一来游。"]},{"t":"又示从子澶","f":"词","c":["壮县人歌第一奇，过庭为有宁馨儿。","亲旁色养宜加谨，户外分豪勿预知。","寓意杯觞须自节，读书松竹有馀师。","它时刮目相期待，连桂家风望一夔。"]},{"t":"又次丁端叔韵","f":"词","c":["好风凉月湛中秋，自笑何为作远游。","不有诸君故人恋，未应连日贾胡留。","三千银界俱呈色，十二珠帘总上钩。","饮罢客归清不寐，谁知心折大刀头。"]},{"t":"又次王瑞安韵","f":"词","c":["云锁千峰碧，泉飞百尺湫。","山蹊惊险绝，洞府足深幽。","谷静摇虚箔，岩高卧老虬。","贾胡还似我，到处辄迟留。"]},{"t":"又次徐仲宗通判韵","f":"词","c":["老龙破蛰斩幽关，乱滴天飘不复悭。","可但甘霖驱旱魃，自然凉气满人寰。","民心徒切焦熬甚，神力毋劳指顾间。","遥想清都应表贺，紫宸轩陛晓催班。"]},{"t":"又次蒋甥仲愚韵","f":"词","c":["山色空濛雪更奇，满空击碎吠琉璃。","寒侵茅屋春无寐，冻合梅花夜不知。","泛泛轻舟胜路滑，洋洋流水乐人饥。","兴来但觉酒肠阔，江海安能实漏卮。"]},{"t":"又谢申之示诗卷","f":"词","c":["不见贤甥十一年，新诗示我百馀篇。","古风已喜能行意，近体尤欣细属联。","宅相真成珠在侧，冷官休叹坐无毡。","作诗勿谓今馀事，更下工夫继玉川。"]},{"t":"三月七日上赐牡丹并蔷薇露劝酒","f":"词","c":["几见牡丹东海涯，暮年敢谓到京华。","休论千品洛中谱，惊看百枝天上花。","况有八珍来禁苑，更加双榼赐流霞。","阖门饱暖聊同醉，稽首将何报宅家。"]},{"t":"三月九日从驾","f":"词","c":["昨日为亲寿，今朝从驾行。","君亲俱有喜，家国共增荣。","淑气浮黄屋，欢声动玉京。","人心真易感，翻手作升平。"]},{"t":"上魏丞相","f":"词","c":["梦庵深坐宴朝曛，祇有梅花对此君。","今日衣冠有巢许，向来元凯佐华勋。","入山谁解访弘景，载酒时应问子云。","童讽写成心未懒，可因贪佛赞论文。"]},{"t":"下元日暖甚夜风雨大作早微雪从子潗以酴醾来","f":"词","c":["眼明喜见早酴醾，窗外风号集霰时。","梅蕊已惭前腊破，芳心休用怨春迟。","纳凉除夜昨几似，见雪芭蕉今不疑。","若使洛人真得此，应须更诧百宜枝。"]},{"t":"乞出过传法闻伯齐归姚江","f":"词","c":["扶病还朝一秃翁，重来宁免笑何公。","梦魂长是寻云北，归路何时向浙东。","深愿耸身随画鹢，空劳举目送飞鸿。","主人竹所终须到，最忆东轩一枕风。"]},{"t":"千佛阁","f":"词","c":["平横云栋塞空虚，倒影仍临碧玉壶。","千佛威光归宝所，九霄宸藻粲河图。","人天共叹未曾有，燕雀相惊不敢踰。","试问南询童子看，化城曾见此楼无。"]},{"t":"士颖弟作真率会次韵","f":"词","c":["何羡祖希情好隆，朱陈累世意交通。","舅甥巾屦频相接，兄弟樽罍喜更同。","参坐幸容攻愧子，主盟全赖适斋翁。","日来愈得清闲趣，斗酒不妨时一中。"]},{"t":"子方移守四明见于浙江亭","f":"词","c":["春初送别欠诗篇，岁晚还欣受一廛。","都骑始闻临浙水，先声久已詟鄞川。","里人见说俱延颈，海峤从今定息肩。","夜夜故山频入梦，为君端欲买归船。"]},{"t":"山中怀仲兄","f":"词","c":["雁山曾御九秋风，更喜春深到此中。","芳草绝怜随意绿，野花真是映山红。","未知方丈景何似，直恐桃源路已通。","起听朝鸡无恙否，兹游恨不与君同。"]},{"t":"山行","f":"词","c":["行入春山紫翠中，入山深处更桃红。","一百五日麦秋冷，二十四番花信风。","千顷摇青几蔽地，四山耸翠欲浮空。","野桥横跨溪如练，待买轻舟下钓筒。"]},{"t":"山阴道中 其二","f":"词","c":["捲上疏帘莫放垂，迎眸景色自淋漓。","有云更觉千山秀，不雨争知万壑奇。","古道经行尽遗迹，群贤风度想当时。","奚囊莫怪新篇少，应接山川不暇诗。"]},{"t":"巾山曲肱斋","f":"词","c":["山立青冥外，人行紫翠间。","小窗开木末，孤塔映江湾。","平楚一何远，白云相与閒。","我来不暇寝，冷坐对前山。"]},{"t":"中秋","f":"词","c":["岁岁当秋半，人人待月明。","绝怜今夜赏，更胜去年晴。","光彩澄高露，氛埃廓太清。","众心方闵雨，却望暮云生。"]},{"t":"中秋无月","f":"词","c":["凉意秋将半，深期月影清。","昨宵云点缀，今夜雨纵横。","睡久何曾著，更阑喜暂晴。","起来聊旷望，终欠十分明。"]},{"t":"中秋次从子涔韵","f":"词","c":["雨馀不见日西沈，将谓中秋又作阴。","佳月忽开千里影，骚人满慰一年心。","扫除宿翳风虽动，滓秽太清云尚深。","坐待寒光谁会此，阿咸为我发微吟。"]},{"t":"为倪正父尚书题壮怀堂扁以诗来谢次韵","f":"词","c":["久矣君宜任弼谐，果随召驲上天阶。","几年不作相逢梦，一日俄倾积别怀。","情厚夫君几鲍叔，愚如老我类高柴。","它时户册高悬后，直欲扁舟访水涯。"]},{"t":"书吴梦予古乐府后","f":"词","c":["古来乐府近来无，笔力如君却有馀。","日恐遗音亡正始，喜闻新作过黄初。","不誇艺苑徒工瑟，应免侯门久曳裾。","更向江西诗窟去，他年时寄一行书。"]},{"t":"书葛氏诗卷","f":"词","c":["未年六十蚤休官，海角投闲尽自安。","一纪时容奉香火，七旬遂许挂衣冠。","重来深愧妨贤路，此去终期保岁寒。","三上封章归未得，葛家诗卷却羞看。"]},{"t":"五月望月蚀历家又言六月朔日蚀","f":"词","c":["闾巷夜争呼，相传救望舒。","偶因云暂破，真似月之初。","孰谓蟆能瞎，端知历不疏。","太阳交蚀近，试看更何如。"]},{"t":"从子淮过省寄伯中弟","f":"词","c":["我家伯父德馀辉，吾弟风标具体微。","七叶欣闻五争奋，四人先喜一雄飞。","忍贫老尚甘箪食，教子今方擢省闱。","他日双椿临六桂，麻衣俱换绿衣归。"]},{"t":"从姑太令人挽词","f":"词","c":["伯祖八贤女，惟姑寿且康。","又闻歌薤露，谁复是灵光。","采藻空南涧，生萱怆北堂。","平生好心地，持以遗诸郎。"]},{"t":"以六经左氏传庄子遗伯中弟有诗来谢次韵 其一","f":"词","c":["手披欲究百家编，奴婢年来识郑玄。","顾我幸多千卷富，念君未有一经全。","诗书心醉不容醒，父子笔耕期有年。","此但古人糟粕耳，更须从此悟真筌。"]},{"t":"以六经左氏传庄子遗伯中弟有诗来谢次韵 其二","f":"词","c":["书种传来直到今，读书几似孝标淫。","欲君终就九经库，与子平分一片心。","更向漆园穷妙旨，何殊清庙奏遗音。","中郎书籍付王粲，想得知余此意深。"]},{"t":"元珍弟酌别赋此赠之","f":"词","c":["归来十暑又三霜，衰病那知谒帝傍。","采菊初期老陶令，种桃应是笑刘郎。","不辞白首登鳌禁，正欲青衫及雁行。","今夕团栾同醉后，未知何日驾归航。"]},{"t":"劝农","f":"词","c":["一番好雨润桑麻，和气欢声十万家。","太守劝农才出郭，老农含哺竞随车。","土膏泽泽地宜稻，云物阴阴天养花。","愿得四方无旱潦，尽教乐岁似东嘉。"]},{"t":"厅事落成老母置酒喜而成诗","f":"词","c":["数椽增葺苟全时，我爱吾庐喜得归。","儿辈粗能勤父蛊，老夫元不费心机。","年来每愧踰初望，病里尤知悟昨非。","从此萧然无一事，但当日舞老莱衣。"]},{"t":"天竺祷晴","f":"词","c":["早奉天香祷白衣，迟明宿雾故凄迷。","忽惊红日穿林薄，无数碧山明涧溪。","上竺寺连中竺寺，苏公堤映白公堤。","湖光一碧几千顷，剩捲荷香送马蹄。"]},{"t":"天童玲珑岩","f":"词","c":["扪萝历栈上层峰，寖觉芒鞋踏半空。","七窍几时开浑沌，八窗无处不玲珑。","已欣古洞容身过，直恐丹丘有路通。","俯视人间懒归去，拂衣径欲御天风。"]},{"t":"太上皇帝圣体清康老母进封信安郡太夫人适斋除敷文阁学士有诗为贺次韵 其一","f":"词","c":["清朝孝治古无伦，通籍推恩总及亲。","八秩升班惟二老，九龄拜命更何人。","春初庆席欢犹在，岁晚宸纶喜共新。","须信长年多富贵，祇因同见会昌春。"]},{"t":"太上皇帝圣体清康老母进封信安郡太夫人适斋除敷文阁学士有诗为贺次韵 其二","f":"词","c":["吾母年高绝等伦，痴儿何幸得荣亲。","九重锡类真千载，八座承恩只一人。","共仰外门流庆远，喜同介弟宠光新。","两家盛事人争贺，和气薰为腊里春。"]},{"t":"太令人轩氏挽词 其一","f":"词","c":["缘断身先隐，年侵鬓未华。","死生犹晓梦，富贵更空花。","佛祖亲提印，儿孙竞起家。","无因拜灵几，一奠赵州茶。"]},{"t":"太令人轩氏挽词 其二","f":"词","c":["旧说苏无著，夫人亦正宗。","毒蛇横在路，栗棘更无踪。","萧散超尘界，扶持礼绀容。","觉庵谁嗣法，别去德云峰。"]},{"t":"太令人赵氏挽词 其三","f":"词","c":["姻娅托三槐，同朝得往来。","迎春烦设席，举寿荷携杯。","京尹俄遭难，都人亦助哀。","琅琅垂绝语，烈妇信高哉。"]},{"t":"太令人赵氏挽词 其一","f":"词","c":["令德比鸤鸠，芳年誓柏舟。","承平犹有态，旷达了无忧。","方奉平反笑，俄成汗漫游。","哀荣谁得似，同穴乐哉丘。"]},{"t":"太令人赵氏挽词 其二","f":"词","c":["节悯名惊代，浮光孝绝人。","宜生克家子，赖有断机亲。","勉使方张虏，终能不帝秦。","一杯扶上马，孰不为沾巾。"]},{"t":"太恭人刘氏挽词 其一","f":"词","c":["籍甚成天助，薰然蔼妇容。","家肥身愈约，福备礼弥恭。","上寿九开秩，湛恩四受封。","何人纪遗德，女婿正乘龙。"]},{"t":"太恭人刘氏挽词 其二","f":"词","c":["卫氏一儿足，他人总不如。","一麾欣义檄，千骑拥潘舆。","台岳伤归旐，青山满送车。","佳城流庆远，旁可万家居。"]},{"t":"太淑人叶氏挽词 其一","f":"词","c":["妇职躬蘋涧，芳年誓柏舟。","壸彝全肃睦，梵行极清修。","贝叶开空性，神篦豁病眸。","飘然指归路，净观日西流。"]},{"t":"太淑人叶氏挽词 其二","f":"词","c":["为国生贤子，三迁备母慈。","版舆崇色养，从櫜勉论思。","戏舞老莱子，平反隽不疑。","孝心天罔极，肠断蓼莪诗。"]},{"t":"太淑人管氏挽词","f":"词","c":["彤史久不作，谁能有妇功。","宁知贵家子，乃有昔人风。","钿轴恩何渥，芝庭泽不穷。","死生无可憾，况已悟真空。"]},{"t":"太硕人潘氏挽词","f":"词","c":["玉映清心著壸彝，闺房宾敬到齐眉。","岂惟山水协高趣，更为国家生好儿。","万口共推诸福备，八旬犹负一年期。","伯仁冬日应肠断，不见堂前举酒时。"]},{"t":"太孺人蒋氏挽词 其二","f":"词","c":["润屋惟纯俭，居然法度循。","松楸先垄下，风月旧湖滨。","子妇皆知孝，孙曾亦可人。","浦江如可赎，真欲百其身。"]},{"t":"太孺人蒋氏挽词 其一","f":"词","c":["之死靡他志，天乎不谅人。","嫠孤蓬在首，艰苦棘成薪。","晚福容千指，心空灭六尘。","平生贞烈意，终作坐忘身。"]},{"t":"夫人携家泛湖","f":"词","c":["三分春色二分休，始见鱼轩泛綵舟。","诸子侍行欢尽日，一翁独坐淡于秋。","满斟美酒应同醉，是处名园为少留。","阴霭在前雷雨后，特晴此日称君游。"]},{"t":"少保李公挽词","f":"词","c":["戚闬疏恩厚，勋门积庆馀。","弓弯飞将臂，架插邺侯书。","六纛秦官重，三槐汉相如。","惜哉终半百，闻者为欷歔。"]},{"t":"少潜兄再立昼锦坊伯中弟有诗次韵","f":"词","c":["东楼旧日史君家，盛德于今说孟嘉。","昼锦门墙再兴起，乌衣巷陌倍辉华。","虽无崔氏联三戟，肯学杨家簇五花。","尤喜桂枝香不断，藏书满屋是生涯。"]},{"t":"尺五亭","f":"词","c":["旧说城南社，今登山外亭。","宫墙步可到，御柳望中青。","引啸千岩响，哦诗过鸟听。","曲栏频徙倚，归思渺东溟。"]},{"t":"方兴化挽词 其二","f":"词","c":["雁塔深论契，鹓班试著行。","参亡闻易箦，越吊后除丧。","支郡难留邓，佳城久梦方。","吁嗟德浮位，回施与诸郎。"]},{"t":"方兴化挽词 其一","f":"词","c":["庙乏著靴鬼，梦中言更明。","起家尤感励，为吏极廉平。","荐口声名重，朝行去就轻。","奏篇真确论，何日遂施行。"]},{"t":"方运使挽词","f":"词","c":["圣主一见决，孤忠自致身。","筹边满躯胆，处事掇皮真。","气直老弥壮，言高用未伸。","留屯十二事，公论付淮民。"]},{"t":"木蕴之国博迁居 其二","f":"词","c":["名大人称屈，心閒我自馀。","言诗今子贡，作赋古玄虚。","凤沼定平进，鸥盟殊未疏。","潭潭府中去，只作寄斋居。"]},{"t":"水月园","f":"词","c":["具美杯残意未休，相将重上望湖楼。","楼台忽已居平地，风月何曾识旧游。","更挈酒樽过水月，坐增诗兴满沧洲。","春风共约新桥畔，遥拜双龙万斛舟。"]},{"t":"水涨乘小舟","f":"词","c":["一番冻雨洗郊丘，冷逼征衫四月秋。","只喜青山泻悬瀑，不知黄潦涨平畴。","登途已厌频舆轿，得意何妨且榜舟。","处顺安贫聊自适，未应坎止愧乘流。"]},{"t":"王大卿挽词 其五","f":"词","c":["上世总儒先，犹传梦雪篇。","惟应佳婿选，可配老姑贤。","父行偏知我，交情不问年。","槁梧谁共语，愁断伯牙弦。"]},{"t":"王大卿挽词 其二","f":"词","c":["麾节东南半，澄清冠一时。","权舆周翰传，顶踵阜陵知。","自谓二宜去，人称三不欺。","卷怀终未尽，流庆称家儿。"]},{"t":"王大卿挽词 其一","f":"词","c":["少壮节先著，年侵气不衰。","忠虽由父教，清亦畏人知。","处世无求合，安时竟数奇。","甘泉人物会，一老汉空遗。"]},{"t":"王大卿挽词 其四","f":"词","c":["老去王摩诘，归来道更全。","剩添天美禄，真得地行仙。","日欲增三径，君胡欠百年。","桃源不无路，重上惨风烟。"]},{"t":"王大卿挽词 其三","f":"词","c":["图史但环堵，江湖几问津。","虽多暮年乐，谁忍半生贫。","海内清名满，毫端秀句新。","风流嗟顿尽，晋韵更何人。"]},{"t":"王夫人挽词","f":"词","c":["淑质依名士，身期百不忧。","藁砧家万里，蓬首日三秋。","随母传遗业，嵇孤托旧游。","幽原诵诗传，无愧柏为舟。"]},{"t":"王夫人挽词","f":"词","c":["妇德胜贤士，嫠居成大家。","阴功宜有后，馀庆尚无涯。","杨恽出司马，陶潜传孟嘉。","文昌纪遗范，外氏倍增华。"]},{"t":"王夫人挽词 其一","f":"词","c":["阃内谁无助，夫人事特明。","倾囊资色养，勉学就清名。","遁世期高节，辞风叹落英。","丁宁犹在耳，伉俪若为情。"]},{"t":"王观国挽词","f":"词","c":["晚识三珠树，方知独笑翁。","旧游亏半面，遗恨想高风。","小楷墨犹湿，残膏泽未穷。","梅花缟寒夜，埋璧众香中。"]},{"t":"王伯齐染髭","f":"词","c":["垂髫相见舜江滨，荏苒俄惊过五旬。","顾我颓龄真似叶，讶君长鬣亦如银。","万金安得神仙药，一笑重回旧日春。","纵使星星还复出，不妨时作少年人。"]},{"t":"王县尉挽词 其二","f":"词","c":["润屋公馀事，能为人所难。","蓼莪遗恨在，夜雨旧盟寒。","家有书堪读，囊无钱为看。","情亲悲不那，望绝旐飞丹。"]},{"t":"王县尉挽词 其一","f":"词","c":["干蛊恢才刃，谁能货殖私。","人皆竞毫发，我独破藩篱。","风雨空残梦，池台怆昔时。","板舆临穴处，行道亦兴悲。"]},{"t":"王忠文公挽词 其二","f":"词","c":["梁木今其壤，谁能问大钧。","恩深两宫赙，哀动四州民。","已矣天人策，伤哉社稷臣。","吾生良可耻，不及见斯人。"]},{"t":"王武陵挽词","f":"词","c":["胡虏久未殄，功名谁与同。","惟公负才气，遇事等英雄。","井井清边琐，骎骎有父风。","惜哉天不慭，遗恨渺无穷。"]},{"t":"王修撰挽词 其一","f":"词","c":["十载频褰刺史帷，名卿风裁映绅緌。","庆门共仰联三凤，禁路咸嗟欠一夔。","神武衣冠终遂志，平泉花木总成诗。","伤心积翠楼前月，斜入栏干欲向谁。"]},{"t":"王修撰挽词 其二","f":"词","c":["贱子何能直一钱，夫君于我独知怜。","樽罍谈笑几侵夜，琴剑周旋不计年。","此去空悬徐孺榻，重来无复孝廉船。","百身愿赎嗟何及，衰涕满襟如迸泉。"]},{"t":"王给事挽词 其三","f":"词","c":["自忝年家好，居惭雌甲辰。","宾兴蒙异奖，客授喜同寅。","别去时无几，年来意益亲。","囿山觞咏地，回首重沾巾。"]},{"t":"王给事挽词 其二","f":"词","c":["宦学素称豪，仍闻吏事高。","精神虽腹满，抚字亦心劳。","藩辅连三组，沉痾见二毛。","胡床庾楼在，残月堕江皋。"]},{"t":"王给事挽词 其一","f":"词","c":["主眷逢千载，宠光倾一时。","铨曹著官簿，禁掖粲英辞。","论议推东省，威声憺北夷。","平生经世意，怀卷竟何之。"]},{"t":"王通判挽词 其一","f":"词","c":["世笃青箱学，骅骝更著鞭。","半山分近派，岩壑诵新篇。","竹马迎双舄，棠阴忆二天。","黄扉伸谠论，风节尚翘然。"]},{"t":"王通判挽词 其二","f":"词","c":["才具盍时用，拂衣俄去之。","善藏经世手，回施称家儿。","嬴博延陵恨，人琴子敬悲。","连年事如许，天道杳难知。"]},{"t":"王敏肃公挽词 其二","f":"词","c":["贱子惭生晚，龙门莫问津。","词场沾剩腹，政地仰洪钧。","古栝杏坛旧，东嘉棠荫新。","九京无馥作，知己更何人。"]},{"t":"王检正挽词 其一","f":"词","c":["到处称循吏，星轺复郡侯。","威名致降虏，恩信感亡牛。","省闼主公议，祠庭寻旧游。","善人天不慭，愁绝岘湖秋。"]},{"t":"王检正挽词 其二","f":"词","c":["客授蒙倾盖，朝参喜缀班。","开藩才一水，去国遂千山。","晚遇名方重，言归鬓未斑。","功名付诸子，含笑谢尘寰。"]},{"t":"王提刑挽词 其一","f":"词","c":["廉白真家法，原由金紫贤。","兄辞岭南赙，弟却澧阳钱。","筑屋吾将老，藏书手自编。","老成俄已矣，闻者为潸然。"]},{"t":"王提刑挽词 其三","f":"词","c":["二广外台首，威棱著一门。","志期诸郡肃，忍见匹夫冤。","奋系犹鹰鸷，兴谗有兔爰。","投閒了无恨，此意与谁论。"]},{"t":"王提刑挽词 其四","f":"词","c":["伯仲三珠树，优为一世才。","人琴先起恨，金玉遂俱摧。","南阮方深痛，阿连尤可哀。","桃花源上路，老眼更堪开。"]},{"t":"王提刑挽词 其二","f":"词","c":["籍甚青箱学，醇乎赤子心。","片言皆可复，一伪不容侵。","处事几游刃，论交欲断金。","诸郎传素业，桂子看成林。"]},{"t":"王遂安挽词 其一","f":"词","c":["淮水占王氏，生平熟义方。","三珠欣竞秀，两桂蚤联芳。","才大用何啬，源深流自长。","青毡传令子，一箭取双鸧。"]},{"t":"长生草","f":"词","c":["玻璃擢叶玉蟠根，千里提携寄海滨。","雨泽不沾仍自润，土膏无著自长春。","岁寒秀色镇依旧，日暖素英能一新。","我欲饵之求久视，恐君灵己不灵人。"]},{"t":"丘文定公挽词 其五","f":"词","c":["同与隆兴第，嘉禾见两轓。","瀛壖迂使节，蜀道送行轩。","预草前须诏，惊传易箦言。","不堪鸾镜舞，双旐怆丘原。"]},{"t":"丘文定公挽词 其一","f":"词","c":["谋国规模阔，绝人才具高。","三朝千载遇，四海一身劳。","儒将通鸳序，枢庭握豹韬。","皇家资柱石，天遽夺伊皋。"]},{"t":"丘文定公挽词 其二","f":"词","c":["初拟文翁化，谁知怀远图。","庙谟专制阃，世将易兵符。","养虎竟遗患，断蛇由不殊。","宁同死诸葛，空恨失吞吴。"]},{"t":"丘文定公挽词 其三","f":"词","c":["十载庞居士，一朝裴晋公。","宣威先抗虏，决策竟和戎。","宥密行谁尼，规恢事已空。","灰心更霜鬓，千载泣英雄。"]},{"t":"丘文定公挽词 其四","f":"词","c":["处事拘挛外，锄奸谈笑中。","几年亡主将，全蜀赖明公。","畏爱盾衰日，清和夷惠风。","屡书终不尽，诗意亦何穷。"]},{"t":"东谷","f":"词","c":["旧说东柯谷，兹来到此山。","树深烟冉冉，花落雨潺潺。","有客礼师塔，何人叩祖关。","天连秋水远，此意尚人间。"]},{"t":"令人王氏挽词 其二","f":"词","c":["宦达方资助，家肥忽悼亡。","一区终异室，千载尚高冈。","奉倩神犹惨，安仁鬓欲苍。","黄昏愁绝处，谁伴紫微郎。"]},{"t":"令人王氏挽词 其一","f":"词","c":["嫁早仍知孝，夫贤自不贫。","事姑如事母，忧物胜忧身。","凤诰恩荣渥，鸠桑德意均。","孺哀声不绝，泪柏不成春。"]},{"t":"兰亭别丁杲卿","f":"词","c":["山阴岩壑妙人寰，十载扁舟空往还。","赞府端能慰牢落，连朝相与上孱颜。","龙盘凤翥无奇画，霞蔚云蒸有旧山。","吊古凄凉更离别，满怀秋思到眉间。"]},{"t":"北行雪中渡淮","f":"词","c":["风捲清淮夜不休，晓惊急雪遍郊丘。","坐令和气三边满，便觉胡尘万里收。","瑟瑟江头辉玉节，萧萧马上点貂裘。","归来风物浑相似，二月杨花绕御沟。"]},{"t":"史清翁谈诗走笔次韵","f":"词","c":["公退门庭静，轻风辊絮毬。","故人惊一见，小酌散千忧。","西上不容久，东归又别愁。","何当附舟尾，从此遂归休。"]},{"t":"史敷文挽词 其二","f":"词","c":["学问源流远，乐哉贤父兄。","人琴亡旧曲，风木怆寒声。","深痛几成毁，沉痾汔丧生。","孝恭无可憾，犹得傍佳城。"]},{"t":"史敷文挽词 其一","f":"词","c":["八行诸孙盛，三公嗣子贤。","连收四鹗荐，祇欠一青毡。","郎省刑章肃，侯邦政誉传。","平生忧国意，赍志入重泉。"]},{"t":"宁海刘君挽词","f":"词","c":["不识紫芝眉，空传有道碑。","义方真可法，闇室肯容欺。","未觉山川改，深明昼夜知。","薤歌惭不称，冢子素能诗。"]},{"t":"宁海骆君挽词","f":"词","c":["古易人皆学，惟君志益坚。","研朱滴秋露，读简断韦编。","空谷甘无用，佳儿尚有传。","清风谁得似，竹满卧床前。"]},{"t":"永嘉天庆观","f":"词","c":["斗口横安华盖山，茂林修竹路湾环。","琳宫迥出沧瀛表，羽士如游昆阆间。","东挹江山穷望眼，西临阛阓笑尘寰。","自知去此无多日，著意来寻一饷閒。"]},{"t":"永嘉试院谢曾使君送酒 其二","f":"词","c":["脱身场屋几春秋，故步重寻我自羞。","闭置有如三日妇，画成应遣一生愁。","与钱谁是老司业，送酒更无贤郡侯。","掩卷出门花下坐，真成一酌散千忧。"]},{"t":"玉堂早起","f":"词","c":["早起多奔走，旬休亦往还。","偶因二士试，始得一朝閒。","灵鹊花枝上，金鱼荇蒂间。","素餐终有愧，只忆旧家山。"]},{"t":"石南康挽词 其三","f":"词","c":["伊昔为君御，儒流赖主盟。","执经容后进，倾盖若平生。","坐见埋黄壤，空劳望赤城。","友朋相与泣，反袂不胜情。"]},{"t":"石南康挽词 其一","f":"词","c":["挺挺石可转，恂恂衣不胜。","平生忧国志，长夜读书灯。","大易窥三古，中庸进百能。","惜哉天不慭，无复见川增。"]},{"t":"石南康挽词 其二","f":"词","c":["家有春秋学，渊源更得师。","风高盖公舍，泪落蔡邕碑。","官早终难进，才全竟弗施。","遗编属贤子，孝谨不应衰。"]},{"t":"石通直挽词","f":"词","c":["籍甚新昌族，真成万石家。","源流端有自，悃愊更无华。","奉职冰同洁，持身璧不瑕。","庆门传未艾，兰玉茁新芽。"]},{"t":"龙湫","f":"词","c":["地耸峰峦秀，天开气象宽。","九霄银汉落，千古玉龙寒。","壮观供尊者，幽居称冷官。","何时遂肥遁，不厌白头看。"]},{"t":"仲观有诗来谢次韵","f":"词","c":["危机屡见剑头炊，喜及挂冠神武时。","从此含藏三寸舌，算来插得几张匙。","读书窗下病勤旧，攻愧庵中老住持。","速办小舟频往反，及今精力未全衰。"]},{"t":"仲舅敷文阁学士汪公挽词 其一","f":"词","c":["籍甚牢之舅，难追宅相风。","惟公能爱我，独我最知公。","潭府书无继，西州事已空。","形容尽心力，庶或慰幽宫。"]},{"t":"仲舅敷文阁学士汪公挽词 其二","f":"词","c":["外氏桂成丛，诸甥长养中。","名称无酷似，宦达偶相同。","澹室既长往，适斋俄考终。","绝怜三学士，只剩一衰翁。"]},{"t":"伍主簿挽词 其三","f":"词","c":["晚年朋旧益彫零，叹绝斯人奠两楹。","不忍衔悲读佳传，可堪回首念平生。","交情君独全终始，人物谁能继老成。","清些楚魂招不得，朔风凄切泪纵横。"]},{"t":"伍主簿挽词 其一","f":"词","c":["好贤元不减缁衣，客到公家如所归。","二浙声名三鹗荐，四山风物一翚飞。","桑榆冉冉身先蜕，兰玉森森家正肥。","人有百身宁可赎，发棠谁复济齐饥。"]},{"t":"伍主簿挽词 其二","f":"词","c":["由来风谊独穹然，坐享家肥不计年。","堕帻何妨分百万，指囷宁复问三千。","灵椿老去仁宜寿，玉树种成身已仙。","衮衮公侯殊未已，正应含笑入重泉。"]},{"t":"再过鹿伯可","f":"词","c":["又上先生见一堂，澹然宾主两相忘。","不知海内清风满，但觉山中白昼长。","小雨络林妨蜡屐，靓妆环坐快瑶觞。","曲终扶杖欲归去，即咏白驹三四章。"]},{"t":"刘吏部挽词 其一","f":"词","c":["总角异群儿，庭趋蚤学诗。","一鸣登桂籍，百里静潢池。","所至清民瘼，平生号吏师。","郎闱方进用，何乃弃明时。"]},{"t":"刘吏部挽词 其四","f":"词","c":["兄长与慈恩，相亲色笑温。","公方持使节，余忝代王言。","共约游三径，俄悲作九原。","佳城隔风浪，丹旐怆飞翻。"]},{"t":"刘吏部挽词 其三","f":"词","c":["谁扰奚山众，焚林兽已穷。","徙薪能远虑，下濑得深攻。","南峤肩随息，中朝论愈公。","但知分谤喜，宁肯自论功。"]},{"t":"刘吏部挽词 其二","f":"词","c":["剸剧最云间，题舆上越山。","洞庭王泽远，庾岭使星还。","中道趋台治，名曹切近班。","阴功多及物，阳报看循环。"]},{"t":"刘德修右史去国示所和从父东溪及杨子直诗走笔次韵 其三","f":"词","c":["阁下相期久，山中把酒稀。","未能容我去，又复送君归。","柱史宁终隐，威颜暂咫违。","壮心谁与语，看剑一灯微。"]},{"t":"刘德修右史去国示所和从父东溪及杨子直诗走笔次韵 其二","f":"词","c":["东溪诗似老弥明，倾盖论诗绝点尘。","笔墨为供无尽藏，江湖乞得自由身。","出门远送成惆怅，无计相留更主臣。","但愿皇天开老眼，不应空谷滞斯人。"]},{"t":"刘德修右史去国示所和从父东溪及杨子直诗走笔次韵 其一","f":"词","c":["无人为辨乐羊书，却向空山问草庐。","世上荣枯无定在，眼前毁誉竟何如。","寸心未彻九重上，百口仍行万里馀。","只恐君王思旧学，便看飞诏促严徐。"]},{"t":"刘德脩赴遂宁示和篇改除荆南复寄之","f":"词","c":["老矣思归铗屡弹，七旬望八合抛官。","我将东去计安出，君欲西还事亦难。","好向渚宫寻故迹，更从雄楚纵遐观。","上游正倚公为重，莫向蓬溪更上滩。"]},{"t":"吊王卿之丧次韵","f":"词","c":["去岁同登百尺楼，相期春晚更重游。","舟藏大壑夜俄去，桥跨清溪花自流。","五纪情亲真是梦，四山风物总成愁。","一朝千古尚何及，空使文皇叹薛收。"]},{"t":"吊陈卫道墓","f":"词","c":["平生学博更加详，和会三家尽较量。","一觉可怜成梦蝶，多岐终是易亡羊。","门前修竹连岩桂，道上芙蓉间海棠。","何似刬除闲草木，青松一色荫高冈。"]},{"t":"同王原庆知道游天童","f":"词","c":["旧游曾记梦中身，一日重来白发新。","行尽杉松三十里，看来楼阁几由旬。","狎鸥亭外波澜阔，宿鹭池边草木春。","自笑赋归如许久，始来此地作闲人。"]},{"t":"同年翁处度招游北山次韵","f":"词","c":["不嫌屐齿碎莓苔，祇要吾人得得来。","见说飞泉高落涧，待寻曲水作流杯。","竹林素约群贤集，鸡黍相过一笑开。","政恐清游自忘返，不应空棹酒船回。"]},{"t":"吕崇德挽词 其二","f":"词","c":["回首情亲处，相过濑水阳。","十年能几见，一疾痛云亡。","县郭山空秀，家园橘自霜。","主人今已矣，鸥鹭亦凄凉。"]},{"t":"吕崇德挽词 其一","f":"词","c":["剸剧推才刃，临机妙斲轮。","传家得清白，满腹是精神。","未上金闺籍，空留花县春。","善人阳报在，兰玉正诜诜。"]},{"t":"孙子才挽词","f":"词","c":["身后名何用，人亡意愈深。","盖棺悲昨梦，挂剑答初心。","潜德仍能发，遗言尚可寻。","悼元情更切，接陇柏森森。"]},{"t":"安人郑氏挽词","f":"词","c":["勤俭佐家肥，犹齐举案眉。","锦封俱被宠，鸾鉴可胜悲。","谢砌森群玉，郤林先一枝。","木华文隽丽，铭德粲堂碑。"]},{"t":"安行表兄除华文阁直学士奉祠次韵为贺","f":"词","c":["屡报银台给事中，忽闻唤渡浙江东。","长安幸免手遮日，圆峤莫嗟船引风。","廪继真祠身暂逸，班联内阁眷方隆。","且归同伴适斋老，便看锋车召此翁。"]},{"t":"安恭皇后挽词 其三","f":"词","c":["玉胜标祥兆，祎衣配至尊。","柔仪高马邓，盛德迈娀嫄。","鸾掖空陈迹，霓轩服厚恩。","伤心临七夕，素柰已花繁。"]},{"t":"安恭皇后挽词 其一","f":"词","c":["天作周文合，祎褕礼可观。","屡陪金辇幸，几奉玉卮欢。","吴女簪新柰，梁房掩旧兰。","春深蚕事起，谁复上桑坛。"]},{"t":"安恭皇后挽词 其二","f":"词","c":["郁郁南山路，伤心凤翣红。","哀歌凄薤露，秘殿掩椒风。","故剑恩虽厚，中珰事已空。","但馀彤史笔，内传纪阴功。"]},{"t":"安恭皇后挽词 其四","f":"词","c":["图史怀规鉴，篇章妙剪裁。","承欢方秘殿，委化已泉台。","幽壤湖滨秀，清笳日暮哀。","未央当月望，不见翟车来。"]},{"t":"寻春次韵 其二","f":"词","c":["晓来陌上雨斑斑，同社相将便出关。","席地亦堪寻酒所，得园径与坐花间。","从教多病须行乐，任是清贫也破悭。","门外红尘深几许，谁人能得此身闲。"]},{"t":"寻春次韵 其一","f":"词","c":["一自东皇天上来，坐看芽檗起枯荄。","化工潜有洪钧转，春事何劳叠鼓催。","晚景鬓凋宁再绿，去年花谢又重开。","赏花携酒那容缓，走遍郊原莫便回。"]},{"t":"戏咏戎葵簇成芍药","f":"词","c":["回首向来婪尾春，横风吹尽已成尘。","戎葵簇就谁尝巧，红药当前太逼真。","观洧赠人迷冶子，翻阶得句误词臣。","园丁妙手有如许，犹胜隋园剪綵人。"]},{"t":"戏和淳诗卷 其二","f":"词","c":["山色蓝初染，湖光镜始磨。","竹梢轻坠雨，花片乱随波。","麈尾挥东晋，龙舟吊汨罗。","莫愁春易老，畅饮一春多。"]},{"t":"戏和淳诗卷 其一","f":"词","c":["琴弈心偏好，丹铅手自磨。","衰翁会同社，吾子揖馀波。","歌动玉条脱，酒倾金叵罗。","好为文字饮，行乐未宜多。"]},{"t":"戏和淳诗卷 其四","f":"词","c":["暮年甘散诞，壮志久消磨。","自愧今摩诘，谁怜老伏波。","清新惭庾信，敏慧谢甘罗。","惟有诗情在，犹能益办多。"]},{"t":"戏和淳诗卷 其三","f":"词","c":["澄江如练净，新月似镰磨。","老柳飘轻絮，良苗飐细波。","歌声追古郢，诗价怯新罗。","到处还成醉，芳醪旨且多。"]},{"t":"戏题十四弦","f":"词","c":["十四朱弦欲动时，泛商流羽看瑶姬。","弦疏不隔如花面，声急还同堕马儿。","溪蟹霜馀萦密网，檐蛛雨后理轻丝。","曲终劝客杯无算，一吐空喉醉不知。"]},{"t":"戏题胆瓶蕉","f":"词","c":["垂胆新瓷出汝窑，满中几荚浸云苗。","瓶非贮水无由罄，叶解流根自不凋。","露缀疑储陶令粟，风摇欲响许由瓢。","相携同到绿天下，别是闽山一种蕉。"]},{"t":"早行","f":"词","c":["水馀枯蘖尚栖苴，催促征夫趁晓鸦。","细路缭山穿乱石，轻舆掠树得飞花。","柔桑弥望两三里，修竹深藏四五家。","径处不容行客恋，可怜一步一天涯。"]},{"t":"曲竹","f":"词","c":["放出一头地，出墙梢更新。","傍人为称屈，素志肯求伸。","苦节变甘节，曲身成直身。","青霄看直上，莫忘手援人。"]},{"t":"朱坡史居士挽词 其一","f":"词","c":["岩邑富人物，才惟史氏多。","流传有丹桂，遗逸叹朱坡。","学饱终难售，诗成祇自哦。","空馀著书在，令子挹馀波。"]},{"t":"朱坡史居士挽词 其二","f":"词","c":["交友俱名士，仪曹礼意周。","使华临夏口，诗兴共南楼。","喜得江山助，还同汗漫游。","更烦贤宅相，相与发潜幽。"]},{"t":"朱南剑挽词 其三","f":"词","c":["棋战久不对，诗盟亦寖寒。","方期会真率，乃尔变悲欢。","岁晚本无憾，情深那忍看。","佳城何处是，东望涕汍澜。"]},{"t":"朱南剑挽词 其二","f":"词","c":["朔望第一客，巡寮意更亲。","有诗欣和韵，不饮喜娱宾。","名帖藏中古，珍茶试早春。","据鞍犹矍铄，何遽迹成陈。"]},{"t":"朱南剑挽词 其一","f":"词","c":["再世文章伯，三朝侍从臣。","传家推笃学，游宦肯谋身。","别驾歌章水，甘棠想剑津。","虚堂两遗像，谁不倍伤神。"]},{"t":"朱婺州挽词","f":"词","c":["治行古循吏，风棱真谏官。","锄奸清远徼，持重息群欢。","久弄赵尧印，重弹贡禹冠。","去天才尺五，惜不见长安。"]},{"t":"次许深甫寄陈颐刚韵 其一","f":"词","c":["博物曾经辨实沈，论兵更觉用功深。","九阍未进六奇计，万卷空催一寸心。","流水高山谁复会，寒松春柳解相寻。","如君岂是长贫者，作计无令岁月侵。"]},{"t":"次伯舅汪运干所寄韵","f":"词","c":["遥忆牢之舅，功名志欲成。","离思满方寸，望眼费双明。","揽笔四愁咏，登楼千里情。","贤劳休自叹，幢下本书生。"]},{"t":"次李季章监簿韵","f":"词","c":["跪履巽岩今几年，见君风度喜跫然。","长编固已翻青简，老墨犹能宝漆烟。","游宦自欣天影近，思家犹在夕阳边。","时从甥馆追清赏，剩写新诗继谪仙。"]},{"t":"次周益公韵 其二","f":"词","c":["六一先生葛稚川，两孙俱并相君年。","词场鏖战今成梦，潭府齐盟望若仙。","政路三公旧同甲，洛阳四老信差肩。","坊名丙午真奇事，写入诗编盍并传。"]},{"t":"次周益公韵 其三","f":"词","c":["顷尝假守向中川，公在黄扉已数年。","每念夔龙容接武，自期鸡犬亦登仙。","入朝终叹一交臂，问道几思偏祖肩。","数仞宫墙天样远，此心何日遂亲传。"]},{"t":"次周益公韵 其五","f":"词","c":["舅甥相与老鄞川，况值慈亲九十年。","画舫时追唐贺监，笋舆联访汉梅仙。","官名自愧偶同辙，才望如何敢并肩。","误辱品题称酷似，此声梁楚更堪传。"]},{"t":"次周益公韵 其四","f":"词","c":["别驾归来自赣川，相迎方叹别经年。","为言相国珠玑语，寄问祠庭山泽仙。","妙句耸观亲盥手，满城争玩日骈肩。","退怜母子方偕隐，却恐虚名似此传。"]},{"t":"次周益公韵 其一","f":"词","c":["天将间气孕山川，名世还当五百年。","已是有官居鼎鼐，不妨平地作神仙。","书林尚欲校三豕，笔力犹能驱两肩。","前日勋名身既退，斯文留与后人传。"]},{"t":"次南真宫龚道士壁间韵","f":"词","c":["幽舍足留客，疏篁不用林。","相过几樽酒，清坐一瑶琴。","野鹤伴仙隐，閒云寄此心。","黄冠如有许，来者为低簪。"]},{"t":"次病足韵","f":"词","c":["定数无过偶与奇，达人处顺更安时。","不于椿菌量长短，岂为彭殇较疾迟。","虽是一时身有疾，行开九秩寿无期。","外生六十头先白，杖屦相从最得宜。"]},{"t":"次韵十诗 其五","f":"词","c":["甥舅相寻向酒边，相忘情话更怡然。","人言难遇双延阁，自愧叨联两大天。","只觉光阴诗里过，何妨枕簟醉时眠。","此中别有真消息，莫为人间醒者传。"]},{"t":"次韵十诗 其六","f":"词","c":["从来忧道不忧贫，晚向闲中得此身。","直把宦途如梦过，任他世事似棋新。","坐间可说旧时话，眼底幸多同社人。","赓唱本求闲燕乐，莫夸末路费精神。"]},{"t":"次韵十诗 其十","f":"词","c":["秋到先生旧草堂，凉飙林叶已飘黄。","渐看天宇清霜肃，更觉人家白昼长。","历世既经三折臂，坐愁何必九回肠。","世间万事消磨尽，祇有诗情未遽忘。"]},{"t":"次韵十诗 其四","f":"词","c":["幸堪击壤乐清时，衰病情怀百不宜。","祇好灌畦陪汉叟，更欣学圃慕樊迟。","逢人草草须倾酒，得韵匆匆且和诗。","琴意高低尤自适，高山流水久心知。"]},{"t":"次韵十诗 其二","f":"词","c":["秋来病体费支吾，深闭柴门卧草庐。","药裹多寻医者问，酒樽寖与故人疏。","时须勉强陪来客，未免辛勤答远书。","此外儒生真气习，简编犹欲趁三馀。"]},{"t":"次韵十诗 其三","f":"词","c":["大率舟行岸自移，机缄何必更深思。","雨馀坐见水三尺，云净喜看天四垂。","荷沼已残霜后盖，桂林初绽月边枝。","闲中气味深长甚，问却西风总不知。"]},{"t":"次韵十诗 其七","f":"词","c":["自怜鹤发奉慈亲，家舅还欣托宝邻。","已向云间收倦翼，甘从波底作潜鳞。","幸然松菊连三径，谁谓神仙隔一尘。","野服相从成二叟，不须更现宰官身。"]},{"t":"次韵十诗 其一","f":"词","c":["懒学仙家炼大还，但欣晚节在林间。","鸳行免奏三千牍，驽驾难参十二闲。","短艇有时浮渌水，轻舆到处赏佳山。","莫言冷淡为生活，冷淡终然无后艰。"]},{"t":"次韵十诗 其九","f":"词","c":["秋宵坐到玉绳低，历历明蟾数桂枝。","重露半翻蕉叶径，好风时飐豆花篱。","不妨起舞弄清影，何用撞钟夸小诗。","浊酒困人垂欲睡，更揩病眼一扬眉。"]},{"t":"次韵十诗 见客","f":"词","c":["车辙长多长者临，相过肯笑席门深。","寒暄固有三分话，臭味还倾一寸心。","客至自应闲不厌，年来寖觉老难禁。","应酬既了无馀事，面壁何妨学少林。"]},{"t":"次韵十诗 老态","f":"词","c":["舅甥身退不为迟，肥遁犹当未老时。","东晋虽惭古元亮，晚唐知慕老天随。","公开九秩身方健，我甫六旬心已疲。","不敢自言成酷似，腹心惟喜两相知。"]},{"t":"次韵十诗 西山","f":"词","c":["两岸杉松翠荫长，轻舆连日得彷徉。","绝怜林下朝还莫，不问人间炎与凉。","睡起闲情方自乐，斋馀归路未须忙。","何时更向月溪去，愿著青鞋走侍旁。"]},{"t":"次韵十诗 即事","f":"词","c":["旋插杉枝蔽晓曦，缓摇轻箑自融怡。","调琴不用求成曲，得句何须凑作诗。","无复趋炎同褦襶，但能寻睡学希夷。","太仓日食五升米，老矣不嫌人更嗤。"]},{"t":"次韵十诗 昼寝","f":"词","c":["才尽甘为世所捐，不如高卧了馀年。","时逢毁誉心无诤，间有诗文手自编。","老去已知身是梦，闲来更得酒中天。","帘深午寂浑无念，只与白鸥相对眠。"]},{"t":"次韵十诗 读香山诗","f":"词","c":["诗到香山不计篇，想逢佳处辄欣然。","明知无子可传业，每遇为文自入编。","举世慕名多讽诵，惟公著句得纯全。","胸中相似诗方似，一等不为名利牵。"]},{"t":"次韵十诗 晨朝懒起","f":"词","c":["坐见一翁双鬓皤，只赢晓梦到无何。","窗凉风透真成适，日出事生还更多。","足弱已难堪蜡屐，齿摇初不为邻梭。","回思螭陛班心处，日日奔趋向馺娑。"]},{"t":"次韵十诗 其二 喜闲","f":"词","c":["杜陵郑老共襟期，门外红尘弗与知。","近日颇荒攻愧课，多时不见适斋诗。","竹深荷净相留处，月白风清偶会时。","地僻衣裳俱自懒，黄冠野服澹相宜。"]},{"t":"次韵十诗 其一 喜闲","f":"词","c":["投闲时以醉为乡，人既相忘我亦忘。","雨足已期南亩熟，风清更爱北窗凉。","昼观碧落云千叠，夜看中庭月一方。","时援素琴聊自遣，谁能更作凤求皇。"]},{"t":"次韵十诗 棋会","f":"词","c":["归来乡曲大家闲，同社仍欣取友端。","无事衔杯何不可，有时会面亦良难。","少曾环坐坐长满，赖有主盟盟未寒。","琴弈相寻诗间作，笑谈终日有馀欢。"]},{"t":"次韵五诗 其一 山行野老问年","f":"词","c":["田夫笑把褐衣牵，争问壶中别有天。","齿发虽衰浑未觉，精神愈胜果何缘。","公言已老偶能尔，我本无心只自然。","再祷百分才及一，定应椿寿八千年。"]},{"t":"次韵五诗 其二 坚郑贵温棋社","f":"词","c":["二公休致我来归，尽可同裁隐士衣。","此已屡谋登竹所，君其无吝造城扉。","人间厌见手翻覆，乐处但当颐指挥。","凉气一新宜近酒，盍簪莫似向来稀。"]},{"t":"次韵五诗 其三 秋凉有感","f":"词","c":["公看鱼跃与鸢飞，鹤胫虽长断则悲。","世事不容人苦较，秋风自有叶先知。","青奴难免交新绝，素扇宁须手自持。","宋玉赋篇终未达，不如老子笑成诗。"]},{"t":"次韵五诗 其四 谕悲秋者","f":"词","c":["黄云万顷一时收，喜见高空风露秋。","岁事及今将告毕，人生到老盍归休。","固知景物能兴感，亦有痴人苦过忧。","胸次果然无一累，岂容秋月使人愁。"]},{"t":"次韵五诗 其五 舅甥赓酬之乐","f":"词","c":["神明未觉晋公衰，老母尤欣兄弟怡。","范宁王枕无许寿，牢之无忌不闻诗。","秋风对酒劝酬处，夜月乘桥来往时。","但要两家同此适，不须更遣外间知。"]},{"t":"次韵伯父与心闻偈","f":"词","c":["法器何妨待晚成，一朝点铁便成金。","拽开鼻孔力无限，坐断舌头功更深。","扬子江头言在耳，灵山会上笑传心。","自怜钝置无香气，四十年来只似今。"]},{"t":"次韵李孟达使君与林雪巢子季武诗","f":"词","c":["古梅巨石瞰清池，觞咏曾陪老启期。","别我遂成千古恨，传家空有一编诗。","使君尚尔悲陈迹，处士惜非同此时。","若使南楼与清赏，胡床应奉庾元规。"]},{"t":"次题晓上人闲静轩韵","f":"词","c":["我居城郭子居山，两地相望数里间。","我已得闲犹未静，子虽处静少曾闲。","莫将花与梦相似，之用心如石样顽。","要识个中真信息，孤云僧事两相关。"]},{"t":"次赠少微兄韵","f":"词","c":["汪楼比屋古城隅，彼此清贫不愿馀。","南阮诸贤今有几，东床佳婿竟谁如。","归乡年亦非全老，对酒情犹未觉疏。","来往两家无倦色，此身端合老犁锄。"]},{"t":"百四从妹挽词 其二","f":"词","c":["孝养全终始，真成乳阿姑。","衾裯几年共，甘毳四时须。","众子俱传业，诸孙足自娱。","吾家女兄弟，似此亦几无。"]},{"t":"百四从妹挽词 其三","f":"词","c":["去岁桐川弟，新从姊处归。","备言家庆事，犹著嫁时衣。","尚欲寻松社，宁堪哭素帏。","人生真一梦，回首事皆非。"]},{"t":"百四从妹挽词 其一","f":"词","c":["姊妹二十四，凋零馀二人。","他乡忽传讣，老子倍伤神。","已叹嫠居久，何堪逆境频。","佳城千里外，西望泪沾巾。"]},{"t":"约访王卿已而中辍次韵","f":"词","c":["归来亲戚话通情，准拟流花得再行。","已荷适斋容接武，敢从酌古遽渝盟。","乌衣门巷人非远，绿野樽罍计未成。","官已得闲身未暇，因仍恐或过清明。"]},{"t":"老来","f":"词","c":["老来何以度光阴，祇有围棋与鼓琴。","棋为心劳疏对局，琴因臂弱倦调音。","曲肱时复同尼父，面壁何妨学少林。","气习未除祇自笑，又还弄笔动微吟。"]},{"t":"自柯山归再过苍岭","f":"词","c":["雨后过苍岭，平生行路难。","危层惊步滑，绝涧觉心寒。","就岭山逾险，趋平谷更盘。","年来轻世故，不作险涂看。"]},{"t":"行荆坑道中","f":"词","c":["古涧随山转，征人趁水行。","悬崖当步险，空翠逼人清。","石路无寻直，沙田不亩平。","千岩得一二，亦足慰平生。"]},{"t":"观文殿学士陈公挽词 其二","f":"词","c":["几见衣冠伟，终闻羽翼成。","先皇崇旧学，大政任名卿。","神器亲传授，崇朝再太平。","功成身自退，宠利一豪轻。"]},{"t":"观文殿学士陈公挽词 其一","f":"词","c":["台岳钟神秀，居然社稷臣。","海涵书万卷，魁冠数千人。","南服频怀绶，西垣屡演纶。","惜哉真汉相，不遂秉洪钧。"]},{"t":"观文殿学士陈公挽词 其三","f":"词","c":["朝著登门久，词林辱眷深。","代言称据古，议礼许同心。","去国临归路，还家寄好音。","病中闻赴告，老泪动盈襟。"]},{"t":"观文殿学士赵公挽词 其三","f":"词","c":["麾节称循吏，三朝蔼政声。","治如黄霸最，心慕伯夷清。","诸道俱遗爱，两川尤著名。","起家临制阃，更羡锦衣荣。"]},{"t":"观文殿学士赵公挽词 其二","f":"词","c":["授受唐虞际，从容平勃閒。","宗英谁柄用，人望属槔閒。","晚侍经闱读，寖登规殿班。","帝乡留不住，归去老湖山。"]},{"t":"观文殿学士赵公挽词 其四","f":"词","c":["皇上初更化，追锋诏语温。","同看三老起，今叹一身存。","别久劳魂梦，人亡溅泪痕。","从兹归故隐，旧事与谁论。"]},{"t":"观文殿学士赵公挽词 其六","f":"词","c":["听履领簪缨，忠言彻帝庭。","公方扶日月，我亦寄雷霆。","忧世形词色，卧家存典刑。","灵光更陈迹，楚些不堪听。"]},{"t":"观文殿学士赵公挽词 其五","f":"词","c":["殄瘁人俱骇，伊余独永叹。","十年交义重，五日旧盟寒。","求去重维絷，欲归无羽翰。","佳城何处是，东盼涕汍澜。"]},{"t":"观文殿学士赵公挽词 其一","f":"词","c":["千古盛周宗，皇朝实比隆。","位多穷贵爵，谁见立王功。","一语国先定，寸心天与通。","龙飞稽事实，信史诏无穷。"]},{"t":"许待制挽词 其二","f":"词","c":["蚤擅文章价，名公屡品题。","碑铭摹谏省，丘壑访愚溪。","得句追飞兔，摛毫走怒猊。","遗编闻好在，后学仰筌蹄。"]},{"t":"许待制挽词 其三","f":"词","c":["十载更麾节，阳春万里同。","时时逢蜀士，一一话文翁。","到处留遗爱，诸郎守教忠。","庆源知未艾，往日有阴功。"]},{"t":"许待制挽词 其一","f":"词","c":["吏事缘儒术，人材第一流。","宦游几五纪，遗爱满诸州。","叱驭无长阪，筹边有旧楼。","遗安阴德在，衮衮见公侯。"]},{"t":"许深父饷酒覆于舟中","f":"词","c":["千里贻书慰寂寥，更将尊酒饷今朝。","先生忽已成乌有，用事何因见白超。","醉里谩思鲸吸海，梦回谁悟鹿藏蕉。","何时痛饮论心曲，云满江东望眼遥。"]},{"t":"过西兴","f":"词","c":["几载京尘涴客裘，江村乍入倍清幽。","柔桑稚麦寒犹在，流水落花春又休。","苍狗浮空惊易失，白驹过隙若为留。","细思谁似垂纶者，寘酒烹鱼百不忧。"]},{"t":"过苏溪","f":"词","c":["处处溪环舍，家家石累墙。","有时逢老稚，无事只耕桑。","野色撩诗思，村醪引醉乡。","山川已如许，急雨更斜阳。"]},{"t":"齐安郡夫人金氏挽词 其一","f":"词","c":["避地供汤饼，当筵接缟衣。","仓皇奉神版，岩险逊征騑。","遇事智尤敏，相夫家寖肥。","考终无可憾，蝶梦绕芳菲。"]},{"t":"齐安郡夫人金氏挽词 其二","f":"词","c":["五子俱英发，尤知仲氏贤。","勤明真世济，廉俭信家传。","别乘径为郡，高城欲捍边。","版舆俄弃养，事业待他年。"]},{"t":"齐国夫人曹氏挽词 其二","f":"词","c":["宗子今曾子，夫人古敬姜。","邛郲承孝养，浯水刻恩章。","汤沐封逾宠，芝兰晚更芳。","九龄天报远，馀庆尚流光。"]},{"t":"伯中弟可休堂","f":"词","c":["夫妇老相对，闺门贫甚安。","六儿俱力学，一子幸先官。","香火祠初奉，勋名镜屡看。","更当联五桂，纳禄尚何难。"]},{"t":"何内翰挽词","f":"词","c":["豪夺锦标天下闻，慨然有志整乾坤。","谏坡论事言皆合，帝幄谈经道益尊。","千古高文在鳌禁，一时名士上龙门。","经纶未究身先死，痛惜谁能作九原。"]},{"t":"何司业挽词 其一","f":"词","c":["顷岁游孤屿，名门说二何。","胡为终璧水，自合上銮坡。","器重连城价，心澄古井波。","传家衣钵在，衮衮并儒科。"]},{"t":"何司业挽词 其二","f":"词","c":["肮脏阳司业，作州如理家。","源流知有自，悃愊信无华。","方喜亨途远，俄惊暮景斜。","伤心倾盖旧，何处望东嘉。"]},{"t":"余丐郡得婺以诗相迎次韵","f":"词","c":["风际端宜鹢退飞，青云高处有危机。","屡遮西日成何事，几向东风咏式微。","塞马云何真是福，鲈鱼正不为知几。","休论五马人生贵，且奉潘舆得赋归。"]},{"t":"余初除西掖适斋惠诗以二甥相继演纶为喜安行表兄贻书喜溢于辞谨次二篇为谢末章以属安行 其一","f":"词","c":["漕台生处寝之床，丛桂还分一叶芳。","红药阶边怀老谢，桃花观里忆刘郎。","首烦贤舅书增喜，想见慈亲色更康。","无忌安能真酷似，愿从外氏借馀光。"]},{"t":"余初除西掖适斋惠诗以二甥相继演纶为喜安行表兄贻书喜溢于辞谨次二篇为谢末章以属安行 其二","f":"词","c":["敢谓封伦据此床，幸从科级绍馀芳。","紫薇继直中书省，丛桂犹为同舍郎。","太史书传得杨恽，渭阳情厚为秦康。","外家宅相君馀事，鱼目何堪比夜光。"]},{"t":"余给事挽词 其一","f":"词","c":["乌府仍螭陛，银台更掖垣。","事几无弗论，外似不能言。","厚德镇浮薄，平心剸剧烦。","用才殊未尽，无地可招魂。"]},{"t":"余给事挽词 其二","f":"词","c":["桂籍兄联弟，兰阶子克家。","上恩嘉踵武，京秩为增华。","朝著蒙倾盖，纶闱睹判花。","遽成千古别，南望想悲笳。"]},{"t":"初出燕山","f":"词","c":["去国三千里，还家第一程。","都缘人意乐，便觉马蹄轻。","落日催心速，飞云逐望生。","莫嫌归去晚，犹得趁清明。"]},{"t":"别王恭叔","f":"词","c":["两儿虽近隔江潮，赖有王郎慰寂寥。","远侍双亲官道院，为同尽室饯西桥。","脑脂遮眼最关念，客路寻仙勿惮遥。","别后飞缄问安否，数来谷口访山樵。"]},{"t":"别长女淯","f":"词","c":["老我年来百念轻，文姬助我以琴鸣。","等闲相对成三弄，游戏俱弹似一声。","举酒不堪千里别，登途知用几程行。","郡斋自是神仙窟，会有阶庭玉树生。"]},{"t":"即事","f":"词","c":["雨外山光淡，烟中草色鲜。","断桥依古岸，流水自斜川。","紫椹馀桑表，青藤绕树颠。","人情兼物态，只合付天然。"]},{"t":"即事","f":"词","c":["行尽穷边岁亦殚，倚门应是念衣单。","宁知今日幕南地，不似去年江上寒。","乘马惟欣日可爱，逢人长说雪初乾。","三衾四袄半无用，何必重歌行路难。"]},{"t":"即事","f":"词","c":["睡重不知晓，山高意得秋。","风来已落叶，潦去忽中洲。","幽阒素所愿，登临尽自由。","濒溪千万壑，何日上扁舟。"]},{"t":"吴大监挽词 其一","f":"词","c":["庠校声名早，朝廷誉望尊。","忠言如日皎，笑语若春温。","四拥皇华节，屡登金马门。","用才终不尽，流庆在仍昆。"]},{"t":"吴大监挽词 其二","f":"词","c":["旷典将行日，南宫得舍人。","铨衡轻易地，造化漫劳神。","旧事谁能记，交情我独亲。","吁嗟三昧手，不见掌丝纶。"]},{"t":"吴待制挽词 其三","f":"词","c":["东甬与宾兴，文闱赖主盟。","菲葑无下体，衣钵有门生。","剑佩今何处，樽罍空复情。","自惭无报所，老泪为君倾。"]},{"t":"吴待制挽词 其二","f":"词","c":["三仕入储闱，堂堂夹日飞。","初同四皓起，终作二疏归。","冰玉清班近，衣冠盛事稀。","间居忽仙去，西望是邪非。"]},{"t":"吴待制挽词 其一","f":"词","c":["御史再乘骢，忠言沃帝聪。","处心平似水，疾恶迅如风。","遇合嗟何晚，论思信有功。","惜哉辛佐治，竟不到三公。"]},{"t":"吴通判挽词","f":"词","c":["一死交情见，乡评重此翁。","素车奔夕梦，绣被落天风。","身任朋僚责，心忘尺寸功。","毋书卓行传，非介亦非通。"]},{"t":"宋南雄挽词","f":"词","c":["二宋久云远，遗风君庶几。","才华试文战，政誉蔼王畿。","梅岭方腾最，雪溪俄赋归。","情亲今已矣，老泪不胜挥。"]},{"t":"张工部挽词 其二","f":"词","c":["壮岁登郎省，旌麾历五州。","仁声号循吏，治行最诸侯。","忧国言多切，筹边虑更周。","积薪无恨望，终老得夷犹。"]},{"t":"张工部挽词 其三","f":"词","c":["敕局同寅旧，雌堂屡肯过。","故人今有几，朝士更无多。","问信书犹湿，相望鬓已皤。","忽闻埋璧痛，薤露不成歌。"]},{"t":"张工部挽词 其一","f":"词","c":["忠简传清白，家声属弟昆。","惟公殿诸老，积善见多孙。","两桂昌书种，双椿蔼庆门。","寿终无可憾，况有典刑存。"]},{"t":"张夫人挽词","f":"词","c":["妇德天然备，肥家五十年。","平生勤内则，晚岁识真诠。","倒廪非徼福，翻经亦应缘。","于门有孙子，佳气蔼新阡。"]},{"t":"张运使挽词","f":"词","c":["惠周剑外与淮南，归卧空山且避谗。","宴坐几年期不死，临行一著信非凡。","不应杜乂束高阁，真使谢鲲居石岩。","欲向西陵寻宿草，秋风何日送归帆。"]},{"t":"张钦州挽词 其二","f":"词","c":["游宦二毛侵，钦山继郁林。","精神虽满腹，抚字亦劳心。","肤使章交上，雌堂疾遽深。","护丧嗟季子，又复丧清浔。"]},{"t":"张钦州挽词 其三","f":"词","c":["姻好自诸冯，东床取阿戎。","平时深念我，晚岁忍铭公。","书字今犹湿，心期谁与同。","回头三十载，洒涕向西风。"]},{"t":"张泰州挽词","f":"词","c":["燕赵多奇士，如公名不虚。","胸中九域志，笔底百家书。","报国心尤壮，筹边智有馀。","功名竟赍恨，西望倍欷歔。"]},{"t":"扶风马君挽词 其二","f":"词","c":["豁野真连璧，一斋宁遗金。","齐家平日学，忧世百年心。","折券无难色，倾囷想义襟。","月评何处见，名士列碑阴。"]},{"t":"扶风马君挽词 其一","f":"词","c":["闾里久湛浮，真成马少游。","有才堪办剧，无命盍归休。","鸡唱言何达，鸿冥逝不留。","佳城送君处，风撼白杨秋。"]},{"t":"李才翁贺除天官次韵 其二","f":"词","c":["我居铨部闹簪裾，终羡寒窗只蠹鱼。","每念故交今有几，况如盛德岂容疏。","京尘共叹催人老，市道谁知有隐居。","久苦笔端枯渴甚，楚波正欲借君馀。"]},{"t":"李才翁贺除天官次韵 其一","f":"词","c":["九年奔走祇思闲，归梦时时堕故山。","已愧演纶词禁上，更堪曳履侍臣閒。","官曹顾我空无补，世事惟君了不关。","但欲相从游物外，不应久此玷清班。"]},{"t":"李公执挽词 其二","f":"词","c":["未甘辛苦去朝天，故作逍遥陆地仙。","老子平生万事足，人间五福一身全。","厌看日月同奔骥，摆脱尘烦等蜕蝉。","重到江头人不见，晓风吹泪忽潸然。"]},{"t":"李公执挽词 其一","f":"词","c":["乃翁志欲卧烟霞，宅枕清江欲泛槎。","心地共知容渤澥，梦魂曾不到京华。","伯鱼久已闻贤训，魏子端能起外家。","瀰望三江梁下水，陇西德泽信无涯。"]},{"t":"李删定挽词 其一","f":"词","c":["积善务增厚，求名惟恐多。","白圭宁有玷，古井竟无波。","议法资修定，监州极抚摩。","佳儿传素业，留眼看巍科。"]},{"t":"李删定挽词 其二","f":"词","c":["冰玉心相照，谁云内举私。","深居无浪出，清节畏人知。","尚忆紫芝宇，无惭有道碑。","填空雨黄叶，西望不胜悲。"]},{"t":"李抚州挽词 其二","f":"词","c":["李下真无径，门前可设罗。","诗如翰林逸，书似邺侯多。","奇字今谁问，遗编尚不磨。","从来好哀挽，薤露忍兴歌。"]},{"t":"李抚州挽词 其三","f":"词","c":["蚤岁文声振，长沙见贾生。","积薪看晚辈，推毂致名卿。","子舍真连璧，生涯付短檠。","风流今李汉，极口赞冰清。"]},{"t":"李抚州挽词 其一","f":"词","c":["与物初无忤，台评反谓倾。","麾符成漫仕，林壑寄平生。","跪履嗟何晚，挥犀空复情。","天台隔风浪，无地拜佳城。"]},{"t":"李度支挽词 其二","f":"词","c":["孰匪同升素，君于我最亲。","词章传自旧，翰墨恍犹新。","别去情逾笃，归来迹遽陈。","无从效经纪，悲结泪沾巾。"]},{"t":"李度支挽词 其一","f":"词","c":["忽作堂堂去，门前爵已罗。","梦随弹指断，事向盖棺多。","心系六州铁，身倾千丈坡。","喑喑昼夜哭，柰此敬姜何。"]},{"t":"李起宗舍人悠然亭","f":"词","c":["远游蜀道历艰难，径上甘泉豹尾间。","荷橐忽思辞北省，拂衣自喜见南山。","当时旁舍基犹在，回首垂髫鬓已斑。","先友碑阴尽陈迹，寒空依旧湿烟鬟。"]},{"t":"杨圣可棋集余方归自桃源不及预次韵","f":"词","c":["屏处尤便野性慵，故人何幸总相逢。","赋归敢慕陶彭泽，自免犹睎邴曼容。","棋酒交欢情正洽，江山得助景方浓。","嗟余误入桃源去，归路满城闻晚钟。"]},{"t":"扬州琼花","f":"词","c":["回忆灵根六十年，秋深恨不见芳鲜。","兹从淮上来千里，非比人间聚八仙。","曾有画图称小异，谅应后土爱孤妍。","或言天杖诚虚语，荣悴中分亦偶然。"]},{"t":"杨武恭王挽词 其四","f":"词","c":["王爵报元勋，临危更致身。","鲸波飞战舰，狼子叹江神。","木落淮南暮，尘清塞外春。","功臣谁第一，图画在麒麟。"]},{"t":"杨武恭王挽词 其三","f":"词","c":["父祖成完节，丹心激懦夫。","枕戈枭逆虏，抚剑志伊吾。","忠孝公何愧，哀荣世所无。","从今紫荷橐，接武上亨衢。"]},{"t":"杨武恭王挽词 其二","f":"词","c":["勇气真虓虎，仁心剧放麑。","推锋多折馘，解缚屡招携。","细柳门坚闭，长杨马不嘶。","夜深星忽堕，何处问撑犁。"]},{"t":"杨武恭王挽词 其一","f":"词","c":["历数中兴将，谁为第一功。","两朝忠卫上，四海雅推公。","富贵无危溢，哀荣有始终。","吾知尚遗恨，不见朔庭空。"]},{"t":"杨待制挽词 其四","f":"词","c":["事契因同荐，交情晚益亲。","半生文会少，万里宦游频。","别后书犹湿，归来迹遽陈。","何能发潜德，空有泪沾巾。"]},{"t":"杨待制挽词 其一","f":"词","c":["望重威无怒，仁深勇有馀。","百年忧国志，满箧荐贤书。","德政不胜载，才猷未尽摅。","佳儿人物似，真可大门闾。"]},{"t":"杨待制挽词 其三","f":"词","c":["蜀用东南彦，皇家属意深。","贰卿频报政，上相最知心。","泛宅俱杭苇，同朝拟断金。","庙廊期引类，疾病两侵寻。"]},{"t":"杨待制挽词 其二","f":"词","c":["蜀道名天险，驰驱敢惮劳。","剑头悬六印，梦里益三刀。","汉殿联簪橐，燕山拥节旄。","惜哉觇国意，不得试龙韬。"]},{"t":"求参议挽词 其二","f":"词","c":["玉立期清贵，厖眉望寿龄。","父兄嗟奄忽，姑姊亦凋零。","厚德今谁在，佳城惨欲扃。","孙曾闻竞爽，兰玉在阶庭。"]},{"t":"求参议挽词 其一","f":"词","c":["累世朱陈旧，宦游多向鄞。","飞凫观政美，展骥愈情亲。","久草归田赋，欣迎入幕宾。","斯人忽千古，望断剡溪滨。"]},{"t":"汪达可招游臧园次韵 其二","f":"词","c":["满架酴醾惬雅怀，更添林下紫徘徊。","平湖不怕重门阻，胜赏何妨后日来。","酒兴已随斜照远，诗情无待片云催。","黄昏鼓棹欲归去，望望烟林首重回。"]},{"t":"汪达可招游臧园次韵 其一","f":"词","c":["城下名园称老怀，乳莺飞燕共低徊。","寒梅送腊曾先到，嫩绿留春喜再来。","眼底芳时能几许，楼头衙鼓谩相催。","主人好事不嫌客，素壁挥毫又一回。"]},{"t":"沈宪敏公挽词 其一","f":"词","c":["天使魁乡荐，上令卿改官。","蚤峨乌府豸，终著侍臣冠。","持节威行惠，专城猛济宽。","绍熙多旧学，胡不相宫端。"]},{"t":"沈宪敏公挽词 其三","f":"词","c":["徐邈今非介，申枨焉得刚。","立朝无附丽，受谪更芬香。","戏綵衣冠盛，围棋日月长。","典刑今已矣，无复岿灵光。"]},{"t":"沈宪敏公挽词 其五","f":"词","c":["晚出荷公知，登门未觉迟。","通班依汉橐，试郡守萧规。","藻翰犹频寄，宫墙不再窥。","新阡何处是，西望不胜悲。"]},{"t":"沈宪敏公挽词 其四","f":"词","c":["持论真遗直，操心本至公。","赢赀宁市宠，平寇不言功。","光禄文阶峻，嘉兴色养丰。","谁能死生际，犹得教之忠。"]},{"t":"沈宪敏公挽词 其二","f":"词","c":["仕宦接王杨，诸公叹老苍。","门生多紫禁，子舍屡黄堂。","自得垂车乐，谁传却老方。","桃花千树满，空忆旧刘郎。"]},{"t":"沈朝奉挽词","f":"词","c":["相业富青箱，丁年稔义方。","生儿有如此，与世遂相忘。","终老三牲养，凌晨一炷香。","浮休了无恨，流庆尚深长。"]},{"t":"灵芝寺","f":"词","c":["送客灵芝寺，恁阑山有无。","自从朝北阙，始得见西湖。","烟外移轻桨，波间浴野凫。","清寒不可驻，回首又神都。"]},{"t":"灵峰","f":"词","c":["老筇扶我转林丘，直到僧房最上头。","地拥双峰遮胜境，天分半石閟灵湫。","空中大士澹相对，山罅清泉空自流。","人谓石崖宜置我，不知来此有缘不。"]},{"t":"灵壁道中","f":"词","c":["古汴微流绝，馀民尚孑遗。","高丘祠汉祖，荒草葬虞姬。","垓下空陈迹，鸿沟怆近时。","膏腴满荆棘，伤甚黍离离。"]},{"t":"苏江阴挽词 其二","f":"词","c":["伊昔初倾盖，摛文已甚工。","亲闻南涧语，谓有魏公风。","既往言多验，归来道更穷。","诲言非教佞，后裔报宜丰。"]},{"t":"苏江阴挽词 其一","f":"词","c":["万卷蟠胸次，千篇秀笔端。","朝行期奋迅，贤路竟艰难。","虽号循良守，欠为文字官。","遗编幸无恙，留与后人看。"]},{"t":"贡闱对砚盘发叹","f":"词","c":["老去未忘黄与朱，琢成三砚乐閒居。","岂能更作诸生业，但欲频看后世书。","视草北门才已尽，持衡南省计尤疏。","便须再挂衣冠去，约汝同归故草庐。"]},{"t":"陆参议挽词 其二","f":"词","c":["饰吏先儒雅，低徊五十霜。","萑蒲扫韶石，桑柘满黄冈。","知己平津老，传家删定郎。","八龙无半在，风雨夜侵床。"]},{"t":"陆参议挽词 其一","f":"词","c":["中外衣冠盛，流传识后凋。","声名三语掾，身世半僧寮。","宝晋书尤逸，坡仙隐可招。","梅溪残月堕，芜没旧风标。"]},{"t":"陆郎中挽词 其二","f":"词","c":["从弟忝东床，相从二十霜。","人琴一何苦，冰玉两俱伤。","别久成今昔，归来失老苍。","稽阴终反葬，西望倍凄凉。"]},{"t":"陆郎中挽词 其一","f":"词","c":["壮岁联双捷，衰年困百罹。","肉身心佛子，霜发貌婴儿。","万事几樽酒，百年千首诗。","浮生成梦觉，吾道竟何之。"]},{"t":"陆宣城挽词","f":"词","c":["奕世承家学，诸公荐吏能。","政传花县美，心与练江澄。","易箦去何远，攀辕悲不胜。","伤哉嬴博葬，泪尽老延陵。"]},{"t":"陆提刑挽词 其一","f":"词","c":["数马谦恭甚，挥犀色笑温。","风流士龙裔，文采左丞孙。","晚幸成三径，身胡遽九原。","素钦仁者勇，大狱竟平反。"]},{"t":"陆提刑挽词 其二","f":"词","c":["早岁擅词场，夷途列雁行。","一麾分楚甸，双节照江乡。","莲社容寒晚，葭莩接老苍。","八旬俱已矣，回首倍凄凉。"]},{"t":"陈夫人挽词 其一","f":"词","c":["族姓甲休阳，夫人懿范彰。","奇男已南省，快婿更东床。","珍锡人加叹，佳城神所藏。","平生阴德在，馀庆尚难量。"]},{"t":"陈夫人挽词 其二","f":"词","c":["雅有幽閒操，来嫔清白家。","相夫全礼敬，见子致清华。","方享乘轩乐，俄兴陟屺嗟。","谁将彤史纪，大笔为雄誇。"]},{"t":"陈夫人挽词","f":"词","c":["作配知名士，周旋内则篇。","宜家兼四德，训子见三迁。","就养荣方逮，归宁病忽缠。","庆源流未已，佳兆得牛眠。"]},{"t":"陈文恭公挽词 其三","f":"词","c":["辅赞藏诸用，庸人自扰之。","惟公知好静，与物尽忘私。","德望仪群辟，威名憺远夷。","伤心白鸡梦，梁木有馀悲。"]},{"t":"陈文恭公挽词 其四","f":"词","c":["致主唐虞上，东山志不渝。","衮衣重入觐，胡骑敢长驱。","梦已商楹奠，朝犹汉殿趋。","哀荣极终始，何止渡江无。"]},{"t":"陈文恭公挽词 其二","f":"词","c":["德量汪汪万顷陂，直将去就佩安危。","干戈虽在相寻日，休沐宛如无事时。","奏罢未闻宫漏转，归来俄见哲人萎。","哀荣终始谁能及，百世旌忠颂德碑。"]},{"t":"陈文恭公挽词 其一","f":"词","c":["唐虞千载道重光，奕奕元臣任赞襄。","谢傅风流冠江左，晋公威誉比汾阳。","折冲曾不劳声色，辅政惟先振纪纲。","天意高高谁可问，坐令邦国叹云亡。"]},{"t":"陈文懿公挽词 其二","f":"词","c":["文最宜为诰，尤能简上心。","周旋銮掖久，惆怅玉堂深。","去国身仍远，还朝病已侵。","三山风引去，云海竟沉沉。"]},{"t":"陈文懿公挽词 其四","f":"词","c":["宅相惟公久，伊余忝后尘。","十年追桂籍，两禁踵词臣。","接武参吾舅，承颜奉老亲。","幸成三学士，何意失斯人。"]},{"t":"陈文懿公挽词 其五","f":"词","c":["一别屡经岁，归舟已及门。","方期情话悦，空讶语音存。","善行传千载，芜词愧九原。","伤心歌楚些，无地可招魂。"]},{"t":"陈文懿公挽词 其一","f":"词","c":["众口推文伯，何人识吏师。","义襟惟古有，心地只天知。","至死终无玷，平生本不欺。","在公亡可憾，犹恨哲人萎。"]},{"t":"陈文懿公挽词 其三","f":"词","c":["珍馆径归鄞，人犹望秉钧。","邮传千里讣，哀动五州民。","躄踊森贤嗣，攀号感路人。","公乎不亡矣，衮衮看簪绅。"]},{"t":"陈君举既亡汪文子携其所作春秋后传及送行诗来次韵","f":"词","c":["名盛望尤备，枝披实亦繁。","无由究贤业，犹幸立斯言。","书在经逾显，人亡道更尊。","九京如可作，与子共南辕。"]},{"t":"陈秘撰挽词 其一","f":"词","c":["陈氏多名德，兹来慕典刑。","宫端惊宿草，冷撰又泉扃。","自古有遗直，祇今谁独醒。","苍苍何可问，耆旧日彫零。"]},{"t":"陈秘撰挽词 其二","f":"词","c":["跬步不忘孝，掇皮皆是真。","移忠思致主，务实见临民。","三谏言犹炳，平生迹遽陈。","清风凛衰俗，自足荡秋旻。"]},{"t":"陈崇道挽词 其二","f":"词","c":["未第声先振，才官节已奇。","精诚与神合，隐行畏人知。","晚境终无玷，遗文尚可师。","功名赍志殁，回施称家儿。"]},{"t":"陈崇道挽词 其一","f":"词","c":["学造龟山蕴，诗传汝水馀。","于公足阴德，陶令竟闲居。","白业追莲社，丹经授寝虚。","平生了无恨，善类勿欷歔。"]},{"t":"具美堂","f":"词","c":["明光殿里早催班，亭午天街从驾还。","已听欢声传市井，更看喜气满湖山。","联镳远去閒寻胜，烂醉归来夜叩关。","但愿两宫千万寿，退公时得过云间。"]},{"t":"净明方丈","f":"词","c":["云深宿雨未忺晴，短艇还来叩晓扃。","山溜拥溪侵石磴，天风吹雾暗空庭。","茵铺野草滋新绿，玉立修篁洗旧青。","老我时时假僧榻，梦魂直向醉中醒。"]},{"t":"叔韶弟以退堂洪老诗来寄谢","f":"词","c":["不受人天供，甘心乐隐居。","坐穷千里目，笑拥一楼书。","攻愧老无用，退堂闲有馀。","相望可杭苇，何日访吾庐。"]},{"t":"周太博挽词","f":"词","c":["雨涨双溪水，风高五柳堂。","论交成莫逆，抚事祇堪伤。","访雪无回棹，面山空夕阳。","乱莺穿绿树，谁复为传觞。"]},{"t":"周左司挽词 其一","f":"词","c":["从政心无愧，敢言人所难。","精忠忧世切，清节照人寒。","交臂失持橐，乞身终考槃。","老成今已矣，西望涕汍澜。"]},{"t":"周左司挽词 其二","f":"词","c":["乙丑慈恩会，今几六十霜。","轺车来握节，相府记传觞。","诗薮怀高隐，邮筒见短章。","不堪千里隔，丹旐想飞扬。"]},{"t":"周路分挽词 其二","f":"词","c":["台岭论交契，天街惜别离。","飞书能几到，埋璧遽成悲。","旧识归樵句，愁看结局诗。","紫髯无复梦，空有泪交颐。"]},{"t":"周路分挽词 其一","f":"词","c":["蚤负功名志，从戎岂素心。","治军先肃靖，游艺亦精深。","湖海开豪气，云天廓义襟。","高门尚馀庆，兰玉正森森。"]},{"t":"周德远挽词","f":"词","c":["家世传儒业，乡邦耸义风。","将迎无倦色，交友尽名公。","太学飞声早，浮生转首空。","怡如堂下月，犹照紫荆丛。"]},{"t":"国仲观迁居尹隩访别","f":"词","c":["晚年来定一枝巢，到处盖头无把茅。","又欲浮家过尹隩，何殊乐道向莘郊。","君今去此难招隐，老更从谁可定交。","见说衡门临野水，秋深容我去推敲。"]},{"t":"国清寺","f":"词","c":["夹道青松引客来，五峰双涧拥楼台。","丰干饶舌留公案，隋帝遗书暗古煤。","最喜亲知来里社，真成春月上天台。","阴云扫尽寻幽去，佳处端疑为我开。"]},{"t":"夜坐","f":"词","c":["晚凉徐步出柴扃，万变浮云在窈冥。","浓似铁山擎缺月，薄于春絮透疏星。","正欣夜久沉天籁，尤喜空明郁帝青。","雨气未平龙欲动，电光前后射中庭。"]},{"t":"夜坐","f":"词","c":["重云烟雨日冥冥，柱础流津意未晴。","赖得溪风送云出，放开山月照人明。","纷纭世态长松影，荏苒时光流水声。","坐久萧然转琴轴，为君更作九皋鸣。"]},{"t":"夜坐烧香台","f":"词","c":["长昼苦炎热，夜分凉始生。","电中千嶂立，琴外一蛩鸣。","急雨催诗思，遥空答鼓声。","谁知一府地，得此意凄清。"]},{"t":"夜携家登南渡桥","f":"词","c":["几过长桥下，清宵得意行。","风高江水急，月上海潮生。","空迥寒逾峭，更深境过清。","扁舟难久驻，转柂问归程。"]},{"t":"宜人史氏挽词","f":"词","c":["阀阅冠三朝，尊公两珥貂。","夫贤能尽礼，家贵肯期骄。","教子门风振，澄神性地超。","悼亡无可憾，直笔付孙樵。"]},{"t":"宜人杨氏挽词 其二","f":"词","c":["梦入枌榆社，心游水竹湾。","丐归期拜寿，近侍望承颜。","一昨闻微恙，宁知竟大还。","佳城无路到，夫妇泪俱潸。"]},{"t":"宜人闻人氏挽词","f":"词","c":["四郡歌贤牧，鱼轩从隼旟。","深闺无里谒，色养谨安舆。","故里称家法，诸郎读父书。","美哉彤史笔，三诵为欷歔。"]},{"t":"尚书尤公挽词 其三","f":"词","c":["旧学方登用，公来领从臣。","末光依日月，听履上星辰。","共政将图旧，腾章屡乞身。","甘盘终罔显，雨露未沾新。"]},{"t":"尚书尤公挽词 其一","f":"词","c":["敏甚五行下，豪釐耻不知。","千人挥笔阵，万卷纳须弥。","有夏传追蠡，先秦拾断碑。","邺侯书插架，分付称家儿。"]},{"t":"尚书尤公挽词 其四","f":"词","c":["北面愿师承，东台拜老成。","忘年容末至，叙契若平生。","风月吟千首，雷霆寄一名。","送车无路到，寒涕为君倾。"]},{"t":"尚书汤公挽词 其一","f":"词","c":["先正真良弼，彤墀四拜麻。","决科承奕世，摛藻擅传家。","禁路优持橐，侯藩几建牙。","相门宜出相，恨不见堤沙。"]},{"t":"尚书汤公挽词 其二","f":"词","c":["奏邸崇先契，周旋古括州。","殿庭观唱第，海郡继承流。","方快飞腾上，俄闻汗漫游。","凤凰山下路，丹旆想悠悠。"]},{"t":"尚书张公挽词 其一","f":"词","c":["文靖饶风度，高皇记曲江。","贤孙真是似，才气号无双。","几见持英簜，终看拥碧幢。","诚斋主诗社，到此亦心降。"]},{"t":"尚书张公挽词 其二","f":"词","c":["抚字推循吏，论思领从班。","宏才名北阙，高兴属东山。","同岁叨崇笃，比邻足往还。","旧游成昨梦，衰涕不胜潸。"]},{"t":"放鹤送潘恭叔司理","f":"词","c":["冲霄六翮困蓬蒿，清唳时时发九皋。","鹄立固应能独出，鸡群未免叹徒劳。","相从顾我怜冰玉，欲去知君刷羽毛。","幸脱樊笼随所适，平平飞去不须高。"]},{"t":"林正惠公挽词 其四","f":"词","c":["百辟素归重，三朝俱受知。","风棱振台省，名字落戎夷。","召节叨同命，几廷踵旧规。","隧铭书不尽，归泣岘山碑。"]},{"t":"林正惠公挽词 其三","f":"词","c":["凛凛古循吏，堂堂真巨公。","死生忘度外，邪正烱胸中。","忧世心诚切，筹边事已空。","龟潭山下水，流庆与无穷。"]},{"t":"林正惠公挽词 其二","f":"词","c":["去国名逾重，还朝道益尊。","清虚怀骨鲠，严冷带春温。","公绰真无欲，臧孙尚立言。","骑箕虽永隔，精爽俨如存。"]},{"t":"林正惠公挽词 其一","f":"词","c":["爱直赵清献，忠文范景仁。","累朝推旧德，今日见斯人。","正色欲劘上，敢言宁顾身。","紫枢方大用，惜不究经纶。"]},{"t":"枢密谢公 其一","f":"词","c":["臣主一意合，风云平地生。","立朝专论谏，为国总枢衡。","行矣登三事，悲哉奠两楹。","辍瓜恩意重，终始备哀荣。"]},{"t":"枢密新府 其一","f":"词","c":["平生苦欲住山间，每恨家居不傍山。","游倦忽来参宥密，公馀却得对孱颜。","援琴万壑自同响，缓步一丘犹可攀。","信美终非吾久处，乞身惟待老乡关。"]},{"t":"枢密新府 其二","f":"词","c":["门号签书府，心存攻愧斋。","倚栏临曲沼，扶杖看悬崖。","槁叶鸣轻雨，残山拥半阶。","退公成吏隐，足以畅幽怀。"]},{"t":"泗州道中","f":"词","c":["宿雪助寒色，相看汴水滨。","轻车兀残梦，群马溅飞尘。","行役过周地，官仪泣汉民。","中原陆沈久，任责岂无人。"]},{"t":"环村踏雪 其二","f":"词","c":["笋舆冲雪过溪桥，流水方东未晚潮。","白里不知梅夺色，青边尤喜麦成苗。","烟深带雨参差下，空阔随风自在飘。","可是忍寒诗更切，故求野路踏琼瑶。"]},{"t":"环村踏雪 其一","f":"词","c":["一冬求雪雨还晴，剩喜春朝见玉霙。","不为偶同佳客到，谁能深入乱山行。","云窗雾阁知何限，玉树琼枝到处明。","更唤轻舟同稳泛，小溪何似剡溪清。"]},{"t":"织锦棋盘","f":"词","c":["锦城巧女费心机，织就一枰如许齐。","彷佛回文仍具体，纵横方罫若分畦。","烂柯未易供仙弈，画纸何须倩老妻。","如欲拈棋轻且称，当求白象与乌犀。"]},{"t":"范叔刚舍人示文正公象笏","f":"词","c":["千载威名文正公，忽瞻遗笏照双瞳。","敢从象齿窥清裁，屡批龙鳞奋大忠。","秉立定知端若植，至今犹想气如虹。","舍人接武登廊庙，宜宝甘棠振祖风。"]},{"t":"范致政挽词 其一","f":"词","c":["义侠久无迹，吾乡见此翁。","紫微欣税驾，飞将许同功。","银茜联恩渥，金兰蔼义风。","虽增嬴博恨，犹喜桂成丛。"]},{"t":"范致政挽词 其二","f":"词","c":["酒后升平曲，闲中安乐窝。","千金曾累致，一醉竟无何。","老骥志空在，孤鸾悲亦多。","相望才岁许，托体共山阿。"]},{"t":"茅夫人挽词","f":"词","c":["清心玉映许谁同，更有飘飘林下风。","政尔高情协宗老，故宜嘉遁乐庞公。","远谋蚤识身为重，晚境还知性亦空。","已拟张林碑妇德，合归彤史巨编中。"]},{"t":"虎丘","f":"词","c":["望望古招提，兹游恨已迟。","池深惊地裂，野旷觉天垂。","听法人千数，谈空松一枝。","从谁访遗迹，惟有石头知。"]},{"t":"虎冢","f":"词","c":["辛勤玉柙更珠襦，或见叉牙出骨须。","鸷兽一心能护法，敝帷千载尚全躯。","馀威凛凛空埋骨，遗像眈眈若负嵎。","及见当年梅子熟，自应惊倒老妖狐。"]},{"t":"表兄陈安行迁右司仲兄迁大理丞余迁太府丞寄诗为贺次韵 其一","f":"词","c":["东塾谈经岁月轻，外家生长复何营。","王生此舅若无有，杨恽一书安得成。","首寄新诗钦厚意，却思往事念平生。","当时更荷外祖母，幼惠尤怜盛氏甥。"]},{"t":"表兄陈安行迁右司仲兄迁大理丞余迁太府丞寄诗为贺次韵 其二","f":"词","c":["为亲敢说宦情轻，公退委蛇懒自营。","朝路一时偕寸进，适斋新句已先成。","圉师况复今同里，武子非惟爱外生。","旧日阿重今欲冠，此恩更欲到弥甥。"]},{"t":"郑司法挽词 其一","f":"词","c":["襟袍空无碍，精神老不衰。","家传司业学，句逼简斋诗。","荒瘠留阴德，平反有去思。","功名赍志没，回施称家儿。"]},{"t":"郑司法挽词 其二","f":"词","c":["倾盖欢如故，相从沧海隅。","方将理诗社，忽已閟泉途。","归路孤飞旐，交情一束刍。","梅霖将客泪，凄澹洒平芜。"]},{"t":"郑华文挽词 其三","f":"词","c":["兄弟忝同登，论交最有情。","颓波知劲节，彻底叹真清。","正尔寻姻好，胡然丧老成。","抱痾难执绋，挥涕望佳城。"]},{"t":"郑华文挽词 其二","f":"词","c":["籍甚柯山政，儿童识贵温。","欢谣闻魏阙，殊宠镇吴门。","就养家传子，休官泽及孙。","吾乡耆旧传，千载德弥尊。"]},{"t":"郑华文挽词 其一","f":"词","c":["蚤擅春秋学，贤关第一流。","少公清泽国，赞府著神州。","试邑人交荐，还朝誉更优。","如何急流退，不使上瀛洲。"]},{"t":"顷游龙井得一联王伯齐同儿辈游因足成之","f":"词","c":["路入风篁上翠微，老龙蟠井四山围。","水真绿净不可唾，鱼若空行无所依。","胜处虽多终莫及，旧游谁在事皆非。","祇今匏系何由到，徒羡联镳带月归。"]},{"t":"俞通判挽词 其二","f":"词","c":["象邑推三俊，灵光赖此贤。","老成俄已矣，远迩为潸然。","孝敬心何极，公平录尚传。","佳城隔风浪，忍赋薤歌篇。"]},{"t":"俞通判挽词 其一","f":"词","c":["强仕赋归去，频年亦漫行。","宦情虽淡泊，官事极精明。","赞画王公幕，监州亚父城。","佳儿守遗训，清白胜金籯。"]},{"t":"信国夫人秦氏挽词","f":"词","c":["夫人富贵出怀绷，择配和鸣得仲卿。","鸾诰蚤能封大国，鱼轩不及伴双旌。","肥家得法晚无倦，教子登科新有声。","难息南溪未成屋，凤凰山下启佳城。"]},{"t":"南山广莫轩","f":"词","c":["广莫乘风隘九州，乱山无数点平畴。","一千里外在吾目，三十年来无此游。","地下天高俱历历，鸢飞鱼跃两悠悠。","昌黎费尽南山句，旷望还能似此不。"]},{"t":"南江酒家","f":"词","c":["南江舟楫饱经行，桥外人家最可人。","剩种寒杉映修竹，快沽村酒趁鲜鳞。","潮痕落草橹声动，日脚衔山凉意新。","酷爱老樟横卧处，他时来此坐垂纶。"]},{"t":"姚江高风阁","f":"词","c":["不从文叔作三公，归著羊裘大泽中。","石濑钓台非故地，云山江水自高风。","烟迷宿草古遗恨，树拥危楼新奏功。","仙驭飘飖疑不远，翩然独鹤度寒空。"]},{"t":"姜总管挽词 其二","f":"词","c":["富盛俄遭变，艰难却起家。","田园新活计，诗礼旧生涯。","仙桂应传秀，庭兰更茁芽。","真归了无恨，超彻妙莲华。"]},{"t":"姜总管挽词 其一","f":"词","c":["及见开元盛，曾闻正始音。","雕虫徒壮岁，冠鹖岂初心。","论事风生席，疏恩带锡金。","精神空满腹，愁绝病沈沈。"]},{"t":"姜钟离挽词 其一","f":"词","c":["门户期兴起，交朋务琢磨。","反身求大学，决意取儒科。","赞府声尤著，邻封惠亦多。","伤心濠上路，无复听弦歌。"]},{"t":"姜钟离挽词 其二","f":"词","c":["别去期三载，伻来痛一书。","死生诚大矣，力量果何如。","平日真知我，遗言苦问予。","作铭虽不愧，回首倍欷歔。"]},{"t":"姜秘监挽词 其二","f":"词","c":["久闻政绩最淮淝，鄮岭循良亲见之。","梓里尚遗前日爱，棠阴还长旧年枝。","钓璜方兆非熊卜，曳杖俄兴梁木悲。","千里佳城空望断，他时归哭岘山碑。"]},{"t":"姜秘监挽词 其一","f":"词","c":["文笔无劳巧剪裁，一时妙斲冠兰台。","王杨仕宦曾相接，游夏渊源有自来。","治狱心知有阴德，立朝人叹有馀才。","功名回施与孙子，公亦何为不豫哉。"]},{"t":"娄忠简公挽词 其三","f":"词","c":["共政三年久，蜚英四海尊。","色词无假借，风裁靡嚣喧。","但欲持公道，宁容启幸门。","经纶终未究，犹有典刑存。"]},{"t":"娄忠简公挽词 其二","f":"词","c":["边事衅初开，惟公论不回。","深谋比娄敬，极力阻王恢。","儿戏何堪用，冰山忽已摧。","朝廷始更化，大老盍归来。"]},{"t":"娄忠简公挽词 其四","f":"词","c":["寮寀侍储闱，如公久任稀。","载欣商皓起，终惜汉疏归。","问字烦参订，谈经赖发挥。","一书真总要，星日重光辉。"]},{"t":"娄忠简公挽词 其五","f":"词","c":["得姓共东楼，同朝两故侯。","文编叨二序，诞日颂千秋。","老矣俱宜去，公乎不少留。","来书墨犹湿，展读泪空流。"]},{"t":"娄忠简公挽词 其一","f":"词","c":["壮岁志先定，耆年气不衰。","治高为县日，名重佐州时。","雅望登朝著，忠言彻帝墀。","亨途日千里，阔步不容迟。"]},{"t":"客目中次韵 其一","f":"词","c":["三年此月绮筵开，盛意勤拳不待催。","预约行人须已集，先欣数客肯俱来。","诗筒才到先赓韵，酒兴方浓莫算杯。","更欲秋深穷胜践，邹枚后乘可容陪。"]},{"t":"客目中次韵 其二","f":"词","c":["花若开时定自开，芳心深靓不容催。","主人又有新诗出，佳客应寻旧雨来。","楼上已闻香扑鼻，堂前尽放酒盈杯。","高烧银烛照花睡，更到更深亦愿陪。"]},{"t":"春游遇雨","f":"词","c":["公子喜青春，欢游弗厌频。","久晴都不问，好雨却成嗔。","桃杏红方入，禾苗绿未匀。","请君停杖履，俯念耦耕人。"]},{"t":"相州道中","f":"词","c":["千古兴亡一梦惊，就中物理似持衡。","茜花空染朝歌血，荒草犹祠羑里城。","但见反身知自咎，谁言修政欲相倾。","知音只有昌黎操，臣罪当诛主圣明。"]},{"t":"祝通判挽词 其二","f":"词","c":["花县弦歌化，莲城水竹居。","旧寮情义厚，近别信音疏。","不作三刀梦，空垂别驾车。","新阡何处是，东望倍欷歔。"]},{"t":"秋日怀国仲观","f":"词","c":["四明耸秀一溪流，曾记经行十里秋。","行李今从何处住，宦游自笑几时休。","儿时故旧今谁在，老去光阴不借留。","赢得东归访丘壑，约君同上钓鱼舟。"]},{"t":"秋意次林致甫宗丞韵","f":"词","c":["河汉秋来净，飞星一点过。","好风吹暑尽，疏雨送凉多。","纨扇收团月，桃笙捲细波。","自知恩到骨，攲枕梦无何。"]},{"t":"胡监岳挽词","f":"词","c":["赋就八叉手，文高三折肱。","青衫双鬓雪，黄卷短檠灯。","梦断采芹水，神凄下马陵。","诸郎追五桂，洗眼看飞腾。"]},{"t":"贺雪八盘岭上作","f":"词","c":["平时卧雪似袁安，谁肯凌晨犯苦寒。","百辟班中因族贺，八盘岭上得遥看。","层层观阙琼楼耸，纳纳乾坤玉宇宽。","怅望仙山何处是，欲从此地径骖鸾。"]},{"t":"赵司户挽词","f":"词","c":["奕奕佳公子，词场早策勋。","愿为新进士，终屈病参军。","旧事成清梦，高标想断云。","伤心桑落酒，无复到孤坟。"]},{"t":"赵左司挽词 其二","f":"词","c":["淮甸争钱币，夔城辩戍兵。","诏归南郡近，公去北门轻。","避宠若将浼，求闲竟不成。","亦齐无适莫，一笑老于行。"]},{"t":"赵左司挽词 其一","f":"词","c":["行谊高馀子，文章自一家。","岳神均客礼，敌国叹才华。","直节曾无苦，全瑜更不瑕。","儒流有遗恨，不见草黄麻。"]},{"t":"赵左司挽词 其三","f":"词","c":["许国终无挠，居家不愿馀。","深蒙明主眷，未觉故人疏。","高论三千牍，阴功四一书。","佳儿承积庆，端可大门闾。"]},{"t":"赵左司挽词 其四","f":"词","c":["乡贡蚤驰誉，郎潜方比肩。","求仙容我学，成佛叹君先。","天癸年将暮，金丹语未圆。","忽传长别偈，天阔散云烟。"]},{"t":"赵安国梅坡","f":"词","c":["隆暑倦行役，梅坡得暂閒。","卷帘南浦岸，终日对成山。","竹里清风远，棋边夕照还。","岁寒重卜醉，觅句暗香间。"]},{"t":"赵县丞挽词","f":"词","c":["玉立佳公子，哦松始戍瓜。","拳拳饬边琐，寸寸画江沙。","慷慨志忧国，清修僧在家。","送行诗尚湿，身世遽空华。"]},{"t":"赵待制挽词 其二","f":"词","c":["诗近刘宾客，手追欧率更。","双旌古良吏，万卷老书生。","世谛浮云薄，生缘晓梦惊。","吁嗟东向议，何日遂施行。"]},{"t":"赵待制挽词 其三","f":"词","c":["半世谁知己，登门意气倾。","交情忘父行，文会忝余盟。","持论先忠厚，谈经叹老成。","幽光谁为发，落笔泪纵横。"]},{"t":"赵待制挽词 其一","f":"词","c":["明主昼三接，清班岁九迁。","一居周柱史，径入汉甘泉。","批敕严东省，抡材上小天。","平生经国志，惜不冠貂蝉。"]},{"t":"赵资政园梅篆","f":"词","c":["小径回环里许长，寒梅森列间疏篁。","路如古茧萦缪篆，身似轻烟缭印香。","九折坂中经蜀险，八盘岭上趁朝忙。","归来游戏通幽处，笑看危途九太行。"]},{"t":"赵提荆挽词 其二","f":"词","c":["处事才游刃，论文辩粲花。","英姿凛熊豹，健华走龙蛇。","持橐身终外，垂车梦到家。","平泉花木在，愁绝旧生涯。"]},{"t":"赵提荆挽词 其三","f":"词","c":["客授早登龙，襟期一笑同。","门清心似水，论正气如虹。","近问书犹湿，重来迹遂空。","无因送丹旐，老泪洒西风。"]},{"t":"赵提荆挽词 其一","f":"词","c":["毓秀从天派，盱衡动至尊。","使星方炳耀，卿月遽侵昏。","已矣悲吴馆，谁欤护北门。","庆源流未艾，文献蔼诸孙。"]},{"t":"赵路铃挽词 其一","f":"词","c":["蚤岁游金阙，霞冠拜紫宸。","可堪天宝乱，及见会昌春。","宛宛王孙态，飘飘物外身。","灵光怆陈迹，遗老更何人。"]},{"t":"赵路铃挽词 其二","f":"词","c":["诸父论交久，忘年许与盟。","登山陪蹑屐，泛月共飞觥。","来往开三径，安闲羡一生。","山深凄薤露，愁忆醉歌声。"]},{"t":"送人之官池州","f":"词","c":["春空吹雨作馀寒，去去扁舟不可扳。","伊昔曾游三大水，到今独记九华山。","想君脉脉征途远，属我悠悠梦境閒。","回首江山固无恙，怀人倚待好诗还。"]},{"t":"送从子渊宰浦江","f":"词","c":["谁云宦路足岖嵚，送子之官独放心。","廉介有馀无矫亢，谦恭已甚自崇深。","安舆何用资三釜，庆问时能抵万金。","公退读书三子侍，县斋松竹已成林。"]},{"t":"送从子渊葬","f":"词","c":["晨起霜如雪，天寒水欲冰。","引舟拖急濑，扶杖历危层。","北阮苦多事，二疏俄丧朋。","山阿埋白璧，悲恸不能胜。"]},{"t":"送元积弟赴永嘉酒官 其一","f":"词","c":["宦游五载住中川，似与邦人有夙缘。","昔日江山知好在，旧游人物想依然。","吾衰无复逢梅福，子去惟应梦阿连。","或问故侯霜鬓未，为言潘令是齐年。"]},{"t":"送元积弟赴永嘉酒官 其二","f":"词","c":["我家清白世相传，工部真清更有年。","百口未曾营活计，一生惟喜种心田。","吾方奉母耕绵上，子更移封向酒泉。","兄弟凋零期自勉，只将家训作青毡。"]},{"t":"送元积弟赴淮东总属 其一","f":"词","c":["南徐来往饱经过，总饷宾寮入礼罗。","子去幸陪邹湛辈，君今还是伯休那。","金闺通籍时方可，铁瓮名城景最多。","我有净名遗记在，试从万井访维摩。"]},{"t":"送元积弟赴淮东总属 其二","f":"词","c":["十人兄弟五人存，心事方欣得细论。","可但衰迟怜远别，祇因喜惧有慈尊。","倚门何止期吾子，发策还知望好孙。","从此三年风雨夜，寂寥棋局与清樽。"]},{"t":"送内弟汪作德赴建德主簿","f":"词","c":["今日望春下，送春还送行。","簿书须著意，家世有馀清。","潇洒桐庐郡，文章陆士衡。","公馀定多暇，无废读书声。"]},{"t":"送内弟汪耐翁随侍因赴临川推官","f":"词","c":["之子长才盍要津，未知此别几经春。","且为湓浦过庭子，径作临川入幕宾。","生长外家身已老，周旋中表意尤亲。","从今家问须情实，莫事虚文学外人。"]},{"t":"送王仲言添倅海陵 其二","f":"词","c":["遂初陈迹遽凄凉，击叹青箱极荐杨。","谈笑于侬情易厚，典刑使我意差强。","重屏旧画论中主，古殿遗文话阿章。","旧事从今向谁得，尺书时许到淮乡。"]},{"t":"送王仲言添倅海陵 其一","f":"词","c":["万卷诗书老雪溪，颀然二子和埙篪。","绝怜伯氏久亡矣，犹幸夫君及见之。","来上鹓行人谓晚，往舒骥足自嫌迟。","他时还向云门否，布袜青鞋尚可期。"]},{"t":"送王伯奋守筠阳","f":"词","c":["三槐名德萃清门，七叶为州赖有君。","道院无忘山谷赋，郡斋当继颍滨文。","君应膝上怜文度，我向东床忆右军。","振起家声差易耳，便看奏最蹑青云。"]},{"t":"送乐清姚令行可","f":"词","c":["长官清政玉无瑕，卓鲁循良不足誇。","前席有期吾党喜，挽须无路邑人嗟。","才高雁荡千峰石，惠足河阳一县花。","欲信三年浑不扰，游山今日始携家。"]},{"t":"送吕周辅宗丞守崇庆 其一","f":"词","c":["从昔传家学，当今良史才。","声名冠西蜀，风节象东台。","朝迹收何速，归心挽不回。","一麾从此去，万里可能来。"]},{"t":"送吕周辅宗丞守崇庆 其二","f":"词","c":["旧矣唐安郡，龙潜府号新。","当年一绛帐，今日两朱轮。","民意来何暮，仁声煖似春。","剑南毋恋却，鳌禁要词人。"]},{"t":"送安行表兄葬次韵","f":"词","c":["深沈仙洞锁神清，万壑松声不似晴。","宿草它年空怅望，生刍今日寓精诚。","山川气象浑如旧，剑佩风姿俨若生。","犹记玉音称酷似，始知无忌乃其甥。"]},{"t":"送朱季公倅严陵","f":"词","c":["朱家族裔甲龙舒，循吏清名史特书。","止为啬夫恩所部，至今庙食盛乡闾。","舍人曾赋严公濑，季子方题仲举舆。","但向棠阴增蔽芾，桐乡今却在桐庐。"]},{"t":"送李伯和吏部提举浙东伯珍寺丞将漕夔门","f":"词","c":["奕奕君家好弟兄，皇华交映棣华明。","几年并列金闺彦，同日俱持玉节行。","万里往临夔子国，一江先到越王城。","会闻归取青毡旧，都似当年老贰卿。"]},{"t":"送杓孙随侍上虞","f":"词","c":["阿斗生来十五年，未曾一日去翁前。","闻诗勿废家庭问，习吏仍求城旦篇。","婚宦有涯真是幸，巾箱所蓄要相传。","荣罍虽小性非鲁，口授诗书加爱怜。"]},{"t":"送杨晦叔提举浙西并寄陈表道","f":"词","c":["两两郎星映使星，老人星彩对晶明。","褰帷共喜行畿甸，洗印仍欣就帝城。","五马况当恩始拜，三吴从此政尤清。","便看瑞庆来称寿，同听嵩呼万岁声。"]},{"t":"送汪庄仲赴江东仓幕彊仲荆门签判 其一","f":"词","c":["不见适斋老，于今三四秋。","弟兄登宦路，亲党驻行舟。","老病无诗思，衰怀重别愁。","外家门户盛，勉力绍箕裘。"]},{"t":"送汪庄仲赴江东仓幕彊仲荆门签判 其四","f":"词","c":["之子游何许，平州更玉州。","山川称胜绝，幕府信风流。","翠巘寒逾秀，金莲夜不收。","天涯念乡国，少上仲宣楼。"]},{"t":"送汪庄仲赴江东仓幕彊仲荆门签判 其五","f":"词","c":["见说荆门地，如门蔽楚荆。","旧时为内郡，今日号边城。","但守平平策，毋求赫赫名。","勉哉关决际，从此振家声。"]},{"t":"送汪庄仲赴江东仓幕彊仲荆门签判 其二","f":"词","c":["外氏蒙恩厚，文昌独我知。","居惭酷似舅，喜有宁馨儿。","遇事行方便，褆身谨护持。","公馀定多暇，黄卷有馀师。"]},{"t":"送汪庄仲赴江东仓幕彊仲荆门签判 其三","f":"词","c":["蚤岁过秋浦，贪程不入关。","君今参俭幕，时得上齐山。","肤使资关决，贤侯伴宴閒。","好音频寄我，赖此一开颜。"]},{"t":"送汪强仲还官所","f":"词","c":["又向丹丘去，安书易往还。","固应官事了，莫放旧书闲。","问讯雪巢老，寄怀巾子山。","经行皆梦境，自笑日苍颜。"]},{"t":"送苏伯昌大卿 其一","f":"词","c":["禁路岧峣欲问津，抗章便自乞閒身。","闵劳剧部皇情厚，寓直中奎宠数新。","飞挽正资经济手，典刑终念老成人。","赤松未许长为伴，归取青毡继颍滨。"]},{"t":"送苏伯昌大卿 其二","f":"词","c":["甬东曾幸拜苏天，外府官僚复备员。","前辈风流真在眼，名公谈笑辱忘年。","浙江相对一卮酒，婺港欲行双桨船。","门键马衔难作远，西风停立但茫然。"]},{"t":"送陈君举守桂阳","f":"词","c":["重寻漫壁认题名，十五年来一梦惊。","谁料今朝携客至，却成此地送君行。","桂阳卧治真谈笑，鲁史遗编赖发明。","文定南轩仙去后，湖湘又得一先生。"]},{"t":"送陈表道倅岳阳 其二","f":"词","c":["闻说巴陵好，楼高占古城。","湖光千顷白，山色一螺明。","赤壁沈沙戟，苍烟老树精。","好诗收拾取，寄我慰离情。"]},{"t":"送陈表道倅岳阳 其一","f":"词","c":["垂上青云去，如何乘贰车。","轻为千里别，时寄几行书。","剸剧才无滞，传家学有馀。","当涂足知己，应不费吹嘘。"]},{"t":"送叔韶弟赴官钱清","f":"词","c":["蕞尔钱清镇，兹行正为贫。","九夷犹可处，十室岂无人。","官守毋卑小，城居缓卜邻。","老夫平日事，所至若终身。"]},{"t":"送叔韶弟宰华亭","f":"词","c":["试邑云间事最多，直将心力细砻磨。","固知三泖五茸胜，其柰千疮百孔何。","敏手未须施霹雳，疲民正欲听弦歌。","规模稳作三年计，徐上青云鬓未皤。"]},{"t":"送季舅汪江州 其一","f":"词","c":["清直如公天自知，晚年百顺了无亏。","九成台下方还旆，五老峰前又拥麾。","题坐喜逢陈仲举，据床好继庾元规。","太平散吏无由到，倚听中和乐职诗。"]},{"t":"送季舅汪江州 其二","f":"词","c":["舅甥相与自垂髫，游宦归来鬓已凋。","坐上可无车武子，酒酣时赖盖宽饶。","喜公自此驱千骑，顾我从今守一瓢。","间与适斋同怅望，草堂樽酒幸清朝。"]},{"t":"送范文叔礼部守彭州","f":"词","c":["忧国鬓先雪，爱君心似丹。","旌麾虽自适，怀抱未全宽。","直道任三黜，故人怜一寒。","濛阳毋久驻，旋复簉鹓鸾。"]},{"t":"送春 其二","f":"词","c":["花披催蝶舞，柳暗受莺迁。","过眼忽新梦，回头谁少年。","溪云随笋供，山雨近梅天。","诗思正无赖，一声来杜鹃。"]},{"t":"送春 其一","f":"词","c":["飞花一片减风光，不待红稀意已伤。","今岁馀春能几许，浮生此日更须忙。","陇头有雨麦初秀，林下无人兰自芳。","夜倚疏棂诵佳句，好风如水月如霜。"]},{"t":"送胡巨济宰湘潭","f":"词","c":["君向潇湘忽语离，江城离思乱云飞。","传闻楚俗尤凋瘵，勿以秦人视瘠肥。","宰县要寻行志处，监州空有负丞讥。","此行得句须频寄，直到衡阳有雁归。"]},{"t":"送赵子固吏部帅合肥 其三","f":"词","c":["襟带长淮地望崇，勋名当继古英雄。","吴人止解依濡坞，晋将才能过八公。","可但绥怀边境静，直须经略朔庭空。","折冲不必居遐徼，颇牧尤当在禁中。"]},{"t":"送赵子固吏部帅合肥 其一","f":"词","c":["少年文价重神京，游宦还闻政有声。","南省但推韩吏部，北方犹问赵先生。","人传殿上三千牍，上喜胸中十万兵。","暂辍望郎分帅阃，淮南草木更知名。"]},{"t":"送赵至道节推","f":"词","c":["君来入幕恰三年，我幸投闲识此贤。","婉画时时因事见，素风凛凛信家传。","易林律本君须寄，月窟天根语未圆。","问讯难兄无恙否，相忘千里各瀛壖。"]},{"t":"送赵伯藏添倅永嘉 其二","f":"词","c":["分教分符恰五年，异乡几若故乡然。","归来几作池塘梦，送别欲随驺御仙。","目断甘林应饱熟，手栽栾实想芳鲜。","邦人若问老州牧，为说清霜绕鬓边。"]},{"t":"送赵南仲丞溧水","f":"词","c":["不用匆匆恨别离，版舆春昼綵衣随。","往题斯立蓝田壁，更访清真溧上诗。","公事毋庸蘖牙角，邻封真是和埙篪。","日哦新句频相寄，明月清风慰所思。"]},{"t":"送赵振文主簿","f":"词","c":["去去江西不作难，片帆双桨荡秋澜。","已知官业非时样，尤喜情亲耐岁寒。","志大自然羞附骥，官卑何用叹栖鸾。","少卿膝上加文度，更比年时刮眼看。"]},{"t":"送赵德老观文东归 其一","f":"词","c":["趣还宗老侍经筵，宿望吁谟信岿然。","引疾屡烦颁汉制，赋归先已买吴船。","去年趋召叨同传，今日求闲愧著鞭。","未得相随出关去，羡公徒御若登仙。"]},{"t":"送赵德老观文东归 其二","f":"词","c":["往还不过酒三行，成败同观棋一枰。","东海敢言成二老，西湖自足度馀生。","朅来便觉废兹事，归去定须寻旧盟。","锦里锦坊秋色里，梦魂先已到江城。"]},{"t":"送赵德老端明帅蜀","f":"词","c":["身名俱泰老尚书，叱驭宁辞万里途。","两地恩荣真赫奕，四川父老定欢呼。","乖崖袍带今重见，清献琴龟我更无。","频向筹边楼上望，归来方略上新图。"]},{"t":"送倪正父侍郎使虏","f":"词","c":["经帷亲见犯天颜，口伐何劳抗可汗。","故国应悲周黍稷，遗黎犹识汉衣冠。","殊邻谍报终难测，累岁要盟恐易寒。","驰至金城上方略，始知颇牧在金銮。"]},{"t":"送倪正父尚书守南徐 其一","f":"词","c":["君如春柳我如松，晚岁重逢意愈通。","日日公馀搜理窟，时时史暇乐谈丛。","友朋罕有心相照，兄弟惟应姓不同。","此别未知何日见，掺袪无语对西风。"]},{"t":"送倪正父尚书守南徐 其三","f":"词","c":["几回去国向吴兴，出处虽高事不平。","兹以优恩临北固，不妨禁直寓西清。","羡君决去行何速，愧我求归计未成。","浙水东西又千里，壮怀堂上未忘情。"]},{"t":"送倪正父尚书守南徐 其二","f":"词","c":["满腔忠膜与嘉谟，空洞它无一物馀。","有语莫非忧国志，欲行犹上荐贤书。","已欣勇退成清节，更喜高眠即故庐。","廊庙须公经济手，不应敛惠向南徐。"]},{"t":"送秦仲防通判 其一","f":"词","c":["清德曾瞻启庆碑，孙曾清更畏人知。","祇缘一介弗轻取，坐使斯民不忍欺。","濑水家传御书卦，宣城手写送行诗。","典刑尚继金銮旧，马氏一门谁白眉。"]},{"t":"送秦仲防通判 其二","f":"词","c":["题舆再到海东涯，嗜学深于入幕时。","一字未通终不置，五行俱下尚嫌迟。","情亲端有卜邻意，别后空劳望月思。","老我无因可重见，祝君来此拥旌麾。"]},{"t":"送淳尉海陵并寄示潚 其二","f":"词","c":["处己幸寡过，居官勿愿馀。","动成经岁别，剩寄几行书。","公退仍多学，心清任索居。","但知行所职，通塞听何如。"]},{"t":"送淳尉海陵并寄示潚 其一","f":"词","c":["二子俱从宦，重亲足自怡。","汝能行幼学，吾岂恨轻离。","平日自知己，真心更与谁。","临文有遗忘，此是忆儿时。"]},{"t":"送曾南仲寺丞守永嘉","f":"词","c":["六和久坐趣归鞭，却送旌麾水竹边。","无说可裨新令尹，有诗重送老同年。","城隅绿竹今安否，庭下朱栾定俨然。","回首东州真梦境，羡君此去若登仙。"]},{"t":"适斋挂冠次韵 其一","f":"词","c":["致仕吾非不待年，礼经自合许求田。","祇图径取衣冠挂，不愿更寻香火缘。","富贵鼎来先瞥地，是非衮处独翩然。","鄮峰相对两真隐，共仰元台与大天。"]},{"t":"适斋挂冠次韵 其二","f":"词","c":["世事相牵无了期，平生待足是何时。","抛官不作九阍梦，纳禄尚馀三径资。","紫绶金章宁复恋，黄冠野服自相宜。","耳根赢得长清净，理乱从今不用知。"]},{"t":"重阳","f":"词","c":["佳处逢佳节，宁辞望眼劳。","有楼皆眺远，无日不登高。","野栗炊新秫，寒萸泛浊醪。","黄花何太晚，篱落上萧骚。"]},{"t":"重阳寄雪窗从叔","f":"词","c":["秋意未教篱菊知，不妨乌帽著风吹。","绝怜对酒君归矣，更欲登高谁共之。","风雨满城千里梦，茱萸缀席一年期。","君非俗物败意者，莫为催租便不诗。"]},{"t":"重阳淳生日时年四十九矣","f":"词","c":["汝生四十九年春，犹记双亲喜得孙。","当慕知非过能寡，敢言学易道弥尊。","喜吾父子为知己，赖尔诗书遂满门。","但得团栾长似此，年年萸菊醉清樽。"]},{"t":"倅厅云水亭","f":"词","c":["山绕澄江江绕城，水云径接海冥冥。","万家曲折在吾目，一郡登临属此亭。","今日诗题随处有，几番醉眼望中醒。","风流郑老知何在，回首苍茫岛屿青。"]},{"t":"唐舍人挽词 其二","f":"词","c":["夷路方驰辔，甘泉喜问津。","庙廊平日志，露电百年身。","搯掌虽多恨，为箕自有人。","发棠阴德在，阳报质苍旻。"]},{"t":"唤仙阁 其三","f":"词","c":["犯暑来登览，松风为洒然。","龙泉澄古井，虹影卧中川。","万簇寒林秀，四山秋色鲜。","诗翁不可见，况敢唤飞仙。"]},{"t":"徐少卿挽词 其一","f":"词","c":["圣主一言寤，长淮千耦耕。","山川皆在目，草木尚知名。","盍被腰金宠，徒为揽辔行。","诸郎袭馀庆，定自不惭卿。"]},{"t":"徐少卿挽词 其二","f":"词","c":["所至多遗爱，丹丘最有声。","奉常千载久，攀恋一城倾。","已恨数离别，宁知隔死生。","湖边旧门巷，一到一心惊。"]},{"t":"徐季节挽词","f":"词","c":["公府推徐稚，山阳荐仲车。","盛时遗此老，没世竟穷庐。","行道嗟无命，传家幸有书。","鲁山终不识，抚卷倍欷歔。"]},{"t":"徐府君挽词","f":"词","c":["孺子人如玉，功名不在身。","死生齐物外，孝友笃天伦。","已有传家子，曾充观国宾。","他年芳五桂，伤不见灵椿。"]},{"t":"恭人胡氏挽词","f":"词","c":["懿行表闺房，情亲共衋伤。","绣衣来宅相，彤管著铭章。","蘋涧谁供祀，藁砧空悼亡。","芝兰俱秀发，所恨失元方。"]},{"t":"恭人强氏挽词","f":"词","c":["祠部源流远，来嫔曲阜孙。","事夫终妇道，训子大吾门。","颁诰恩光渥，升堂笑语温。","相期送丹旐，马鬣近周原。"]},{"t":"恭人董氏挽词","f":"词","c":["敬馌尊夫子，升堂乳阿姑。","乡评推至行，家庆展新图。","半世悲鸾舞，高年乐凤雏。","蜜章应未艾，卿月映阶符。"]},{"t":"挈从子涤归乌戍外家","f":"词","c":["五年不泛浙西船，今日重来倍黯然。","苇席不重寒刺被，菱歌孤唱月摇川。","咿哑回橹凫鸥狎，来往轻帆风雨便。","点检湖山固无恙，鸰原遗恨到黄泉。"]},{"t":"桂花方开约客次韵","f":"词","c":["久疑岩桂尽迟开，留待生朝伴举杯。","老去欲寻千日醉，客来同引百花醅。","况临高阁枝枝秀，好判闲身日日陪。","家酿尽倾君不惜，莫教瓶罄耻为罍。"]},{"t":"海潮图","f":"词","c":["钱塘佳月照青霄，壮观仍看半夜潮。","每恨形容无健笔，谁知收拾在生绡。","荡摇直恐三山没，咫尺真成万里遥。","金阙岧峣天尺五，海王自合日来朝。"]},{"t":"病目初愈张子家有诗次韵","f":"词","c":["年来视物隔褷䙰，祇有昏花似退之。","强起归鸿聊自放，妙穿悬虱恐难为。","相亲黄奶交亲绝，见代青姑事寖危。","写照苦添云蔽日，不应更诮虎头痴。"]},{"t":"病足戏效乐天体","f":"词","c":["课得退连茹，药逢新太医。","居闲幸馀暇，养病任多时。","步屧虽非便，调琴足自怡。","晓来风雨急，高卧到晨炊。"]},{"t":"真率会次韵","f":"词","c":["喜奉潘舆得退身，乌衣相会总情亲。","樽前正好醉千日，林下何妨见两人。","闲暇止应开口笑，谈谐尤称掇皮真。","夜归更作惊人语，舅氏从来笔有神。"]},{"t":"绣川道中","f":"词","c":["伏波莫作贾胡留，雨意垂垂未肯休。","不惮征衫有微湿，只愁平地又横流。","行人自厌冲泥苦，野老方当得意秋。","倦仆如何致千里，登天徒笑传鸣鸠。"]},{"t":"翁府君挽词","f":"词","c":["肮脏翁夫子，高才噤不施。","床头痴叔易，梦里阿连诗。","德丧嗟何及，天胡弗慭遗。","清风终未泯，吹拆谢庭芝。"]},{"t":"莫子执挽词","f":"词","c":["乐有父兄贤，谈经绛帐前。","桂林孤素志，芹泮老遗编。","小阮情何切，童乌业未传。","槔閒最崇笃，口口话齐年。"]},{"t":"莫将仕挽词","f":"词","c":["自叹清才久陆沉，晚从内典用工深。","谛观烱烱死生际，宁复纷纷利禄心。","载酒今谁问奇字，遗经古亦胜黄金。","十年契阔遽如许，老泪临风自不禁。"]},{"t":"莫铜陵挽词","f":"词","c":["经学高馀子，躬行慕古人。","儒风三叶秀，和气一门春。","台岭渐摩久，铜官抚字均。","庠东亡二老，凝望倍沾巾。"]},{"t":"袁府君挽词 其二","f":"词","c":["坦坦幽人履，恂恂长者言。","忧时见颜色，乐道竟丘园。","隐行推同气，高贤萃一门。","四明耆旧传，他日数诸袁。"]},{"t":"袁府君挽词 其一","f":"词","c":["家学传三世，几间无二书。","力行真勇猛，进取故舒徐。","前辈多遗墨，先人祇故庐。","后来窥瓮牖，志士为欷歔。"]},{"t":"袁通判挽词 其二","f":"词","c":["盛德不容赞，多言可柰何。","大圭元不琢，古井竟无波。","前辈苦凋谢，后生谁琢磨。","同庚适斋老，托体共山阿。"]},{"t":"袁通判挽词 其三","f":"词","c":["仅有一区宅，曾无二顷田。","相过惟载酒，至老不言钱。","几得拜床下，何堪哭道边。","门人多著籍，下马向新阡。"]},{"t":"诸瑩拜扫晚归长汀","f":"词","c":["雨意早垂垂，寒云晚更低。","空中时散点，道上不成泥。","绿柳桃相映，黄花麦与齐。","迂回馀百里，喜见旧松堤。"]},{"t":"资圣寺","f":"词","c":["野溪清浅度危桥，径策枯筇上紫霄。","晓雾暗蒸山寺雨，松风深隐海门潮。","浮杯水涨人何在，洗钵池清意已消。","又上乐亭基上望，云山万里更逍遥。"]},{"t":"钱江阴挽词 其二","f":"词","c":["客授向东欧，君为郡督邮。","岂惟寮契笃，更喜吏才优。","每叹频年别，俄惊一梦休。","虞山渺何许，泪落不能收。"]},{"t":"钱江阴挽词 其一","f":"词","c":["庾岭梅花暖，贤侯惠爱深。","精神虽满腹，抚字亦劳心。","九转竟难遇，二毛何遽侵。","伤哉东逝水，无复大江阴。"]},{"t":"钱殿撰挽词 其一","f":"词","c":["隽誉蜚庠校，孤忠动冕旒。","救荒心欲折，忧国鬓先秋。","惠满长江水，风清八咏楼。","禁途交一臂，人物等闲休。"]},{"t":"钱殿撰挽词 其二","f":"词","c":["枌社归来晚，翛然得故吾。","哦诗频刻烛，点易细研朱。","有泪悲连璧，无阶奠束刍。","名门馀庆远，丹穴看奇雏。"]},{"t":"顾养直挽词 其一","f":"词","c":["万顷东湖下，曾门起大家。","子孙昌世业，文字作生涯。","堂后萱犹树，庭中桂欲华。","惜哉时不待，谁忍送悲笳。"]},{"t":"顾养直挽词 其二","f":"词","c":["旧向君家去，宜斋屡举觞。","人哀诵诸顾，里不见他杨。","身世惊春暮，湖山怆夕阳。","园林未成趣，鸥鹭亦凄凉。"]},{"t":"商侍郎挽词 其一","f":"词","c":["矫矫真御史，风生白笔端。","出持肤使节，始著侍臣冠。","给饟鬓先雪，筹边心为寒。","天乎惊玉折，不及上金銮。"]},{"t":"商侍郎挽词 其二","f":"词","c":["所至仁声著，甘棠几去思。","敬姜嗟哭子，伯道痛无儿。","郎省伤连璧，文闱见刻辞。","边民纷堕泪，忍读岘山碑。"]},{"t":"宿育王山涵秋","f":"词","c":["清秋来此宿涵秋，雨后山泉自在流。","夜暗寒声锵玉佩，灯明清影粲珠旒。","枕流正自怜孙楚，洗耳何须效许由。","我亦暂来专一壑，倚栏耽玩不知休。"]},{"t":"宿登山","f":"词","c":["竹舆来访小梅山，山在空濛紫翠间。","岚雾满林朝漠漠，溪声和雨夜潺潺。","峰头丹井随潮信，松下禅房旧祖关。","谁是无生谁不死，晨钟未响梦先还。"]},{"t":"寄叔韶弟","f":"词","c":["阿连试邑有成规，谁谓云间不可为。","能使镬汤偏衮处，直如官府太平时。","容容非欲后多福，赫赫何如去见思。","子路当年曾请益，更须无倦以终之。"]},{"t":"寄管叔仪通判并同官","f":"词","c":["执别僧房日未斜，别离愁绪满天涯。","清宵已落柔桑叶，小雨顿开荞麦花。","醉里不知身是客，酒阑无奈客思家。","凭谁寄语三夫子，归路还须好句誇。"]},{"t":"寄题正卿通判可高亭","f":"词","c":["樟坡直上可高亭，未见高亭祇见名。","想像岂能胜一览，登高安得快双明。","大龙湫下听雷吼，白石岩头看日生。","咫尺好山随杖屦，自应老笔擅诗声。"]},{"t":"寄题延平范氏六桂堂","f":"词","c":["高门儒效许谁同，秀气于今照演峰。","家学一椿连五桂，地灵两剑化双龙。","三人衣钵清名接，累世簪缨庆事重。","彼茁孙枝更林立，不须万户羡侯封。"]},{"t":"寄题江西刘氏勤有斋","f":"词","c":["朴斲敷菑皆用勤，况吾儒者务多闻。","万书插架非关我，一卷入心方属君。","为学从来无止法，立身宁祇富多文。","自怜习气今犹在，尚欲焚膏到夜分。"]},{"t":"寄题吴绍古县尉经德堂","f":"词","c":["问舍玉真下，读书经德中。","心期知共远，臭味许谁同。","吹笛夜凉月，舞雩春暮风。","直须涵泳熟，毋负象山翁。"]},{"t":"寄题汪端明坟庵真如轩 其二","f":"词","c":["万个筼筜一草庐，伤心埋璧十年馀。","革声谁听尚书履，金榜空悬少保书。","无复遗音追正始，尚传新作过黄初。","真成一代风流尽，欢息浮生信六如。"]},{"t":"寄题蜀李氏义概堂","f":"词","c":["养气非为侠，轻财弗市恩。","仁声高月旦，义概彻天阍。","称美推贤嗣，扬名有顺孙。","活人几百万，何止驷容门。"]},{"t":"旌表门闾安人陈氏挽词 其二","f":"词","c":["族姓朱陈盛，夫人事愈明。","老姑俱上寿，难弟各清名。","节行辉彤管，门闾照赤城。","宝邻方有托，何忍送铭旌。"]},{"t":"旌表门闾安人陈氏挽词 其一","f":"词","c":["妇德高千古，乡评彻九重。","柏舟终自誓，石窌启新封。","孙子传清白，闺门慕肃雍。","死生无憾处，了不愧三从。"]},{"t":"晚自拟滁亭转烟雨楼听角","f":"词","c":["两寺疏钟夹岸闻，荒烟无数乱前村。","山衔落日云生彩，溪溜孤舟水不痕。","虫羽凄凄鸣绿暗，星晖隐隐照黄昏。","欲归重到层楼上，更为梅花一断魂。"]},{"t":"曹工部挽词 其二","f":"词","c":["宦达推公早，丁年备皂衣。","几为铜虎去，终向石桥归。","齐国世臣少，贞元朝士稀。","松风谈笑地，回首倍歔欷。"]},{"t":"曹工部挽词 其一","f":"词","c":["箕颍文章士，仪同社稷功。","惟公承庆裔，有意振家风。","祠禄真崇道，郎潜叹老冯。","伤心循吏手，赍志九原中。"]},{"t":"梁仲苍挽词 其一","f":"词","c":["延赏高三让，殊科擅一鸣。","元宾文未极，长吉记先成。","妙语遗膏馥，玄谈悟死生。","行人痛埋璧，父子若为情。"]},{"t":"梁仲苍挽词 其二","f":"词","c":["人物如君少，相期上石渠。","博文该四部，笃学富三馀。","泪尽知无及，交深未觉疏。","何时酹坟草，细读茂陵书。"]},{"t":"梁运使挽词","f":"词","c":["风月诗千首，烟霞宅一区。","三年著朝迹，一节偾亨途。","南海瞻遗堞，西门破老巫。","才高不尽用，无地寄长吁。"]},{"t":"梁审计挽词 其二","f":"词","c":["寿夭固难问，吁嗟不忍言。","婴啼摧玉树，衰泪洒芳萱。","事契深群从，英才怆九原。","悲吟惭楚些，无地与招魂。"]},{"t":"梁审计挽词 其一","f":"词","c":["壮岁崭头角，夷涂试著鞭。","群公争倒屣，诸老亦忘年。","论议倾朝誉，功名短世缘。","神伤贤伯仲，风雨夜无眠。"]},{"t":"淳发漕荐喜而成诗并勉杓","f":"词","c":["戊辰贡举忝余知，曾碍孙儿到省闱。","欣汝今秋重预荐，喜吾即日可言归。","门阑有庆人争贺，父子同登世所希。","痴望十人俱上第，坐令昼锦倍光辉。"]},{"t":"淳谒告归省复还海陵","f":"词","c":["吾子远归省，重闱俱粲然。","难留毛义檄，又送子真仙。","西笑仍千里，东归约二年。","词场期自力，收取旧青毡。"]},{"t":"清高阁观雪次韵","f":"词","c":["冲雪上层阁，真成清且高。","主人风节峻，坐客笑谈豪。","泛剡访安道，赋梅思水曹。","好因窗映夜，痛饮读离骚。"]},{"t":"盛夫人挽词","f":"词","c":["婉昵闺中秀，清高林下风。","相夫能尽礼，教子使移忠。","边郡官无旷，都城养得终。","壸彝今具在，流庆复何穷。"]},{"t":"硕人居氏挽词","f":"词","c":["顷侍尚书坐，曾闻阃助贤。","晤言成勇退，里谒戒私专。","梦断松江路，神伤薤露篇。","悼亡千里泪，叠嶂想新阡。"]},{"t":"隐潭","f":"词","c":["灵潭深入白云堆，带雨春云为我开。","乳石半空浑欲堕，瀑泉千尺正中来。","两军酣战鼓鼙急，一雨生寒霹雳催。","中有卧龙君勿狎，有时平地起风雷。"]},{"t":"雪中迎驾","f":"词","c":["都人久不望威颜，惊喜鸣鞘风雪间。","万井欢声迎晓仗，九天和气下人寰。","龙楼笑启瑶池宴，鹓序欣趋玉笋班。","道上峰头皆见日，绝胜衔烛照昆山。"]},{"t":"雪窦道中","f":"词","c":["城居久矣厌尘劳，来访名山写郁陶。","客路行随流水远，征人与坐白云高。","千林舞翠吹蓬鬓，二麦摇青照纻袍。","努力共登天尺五，要看飞雪喷云涛。"]},{"t":"鹿夫人挽词 其一","f":"词","c":["内外言无间，初终志不移。","白头供妇职，彤管著贤规。","庆衍珠三树，芳先桂一枝。","凤岑归去路，含笑不应悲。"]},{"t":"鹿夫人挽词 其二","f":"词","c":["庆霈疏封日，姑慈不忍违。","人方侈君赐，我独避恩辉。","孝笃神应劳，风高家愈肥。","新传快女婿，亦复挂冠归。"]},{"t":"喜雨次甄云卿监簿韵","f":"词","c":["四郊苗槁勃然兴，顿觉欢声满郡城。","行且刈云成岁事，敢因喜雨记亭名。","昔如鱼在釜中活，今见龙从地上行。","忧国愿丰同此乐，读君佳句欲风生。"]},{"t":"喜雨次韵并呈郡守吴居父 其一","f":"词","c":["一旱祷而雨，此心天与通。","为霖三日足，起舞万家同。","破块朝方爽，翻盆夜正中。","随车真响应，巫觋又何功。"]},{"t":"喜雪","f":"词","c":["晓风吹起雪漫漫，来兆丰年喜有端。","玉树琼枝无限好，雪窗高阁不胜寒。","直疑天上梅花落，莫作人间柳絮看。","我欲乘风游汗漫，倚栏空自羡飞翰。"]},{"t":"婺女极目亭","f":"词","c":["危楼雄据郡城东，扫尽秋云快碧空。","目力不容山隔断，诗情长与酒无穷。","先分楼下双溪水，高挹人间万里风。","兴逸不知真近远，五弦声里送归鸿。"]},{"t":"富览亭","f":"词","c":["城郭占佳胜，眼高贞白鼍。","霜天开浩荡，云屋涌嵯峨。","四面山总好，东窗江最多。","脚跟盘巨石，吞吐任风波。"]},{"t":"寒食","f":"词","c":["辅政无功日歉然，佳时攽赉屡传宣。","已蒙授粲仍分茗，既荷贻牟更击鲜。","酒号流香盛宝榼，烛然新火散青烟。","孙儿不识君恩重，但觅东宫则剧钱。"]},{"t":"彭宜义挽词 其二","f":"词","c":["籍甚清湘守，脩名所在闻。","宦途资畏友，家训仰严君。","归路飞丹旐，长空惨白云。","生刍不成奠，挥涕想江濆。"]},{"t":"彭宜义挽词 其一","f":"词","c":["种德不在大，至诚天所亲。","但能存一念，何用活千人。","经笥儒风远，香山句法新。","功名付儿辈，不必在吾身。"]},{"t":"曾无逸郎中名燕居曰和三续社有诗次韵","f":"词","c":["通地通天祇个中，千岐虽别大都同。","两家偶尔流传盛，一贯临之内外融。","欲境扫开心在我，浮云散尽月当空。","感而通者从来话，不感须知自有通。"]},{"t":"曾侍郎挽词 其一","f":"词","c":["文献南丰裔，源流曲阜公。","岩岩双法从，凛凛旧家风。","金玉方交映，人琴忽并空。","平生心地直，流庆尚无穷。"]},{"t":"曾侍郎挽词 其二","f":"词","c":["紫陌寻春日，惟公最少年。","鳣堂惭隗始，熊轼愧卢前。","寄我书犹湿，思君迹遽仙。","同登今有几，挥泪抚遗编。"]},{"t":"朝退","f":"词","c":["谢事不得去，趋朝愈更难。","谁怜八旬老，日冒五更寒。","指冻怯持笏，腰酸强踞鞍。","细思谁缚汝，只合挂衣冠。"]},{"t":"游大梅山梅仙岩","f":"词","c":["为忆西京梅子真，人言羽化匪沉沦。","海濒古岙已无迹，山外高峰宁有神。","鲠论至今光汉传，清风犹足荡秋旻。","何须更说神仙事，终老市门良可人。"]},{"t":"游西山次范丞韵","f":"词","c":["东风吹我上西冈，更觉僧房白昼长。","草色已翻新岁碧，梅花祇是去年香。","好山围绕屏三面，野竹萧森玉数行。","千里同游逢范叔，绨袍他日未相忘。"]},{"t":"游径山","f":"词","c":["起看海日晓团团，更挹神灯照夜阑。","百万杉松双径杳，三千楼阁五峰寒。","蛰龙何在渺难问，古井于今竟不眢。","但觅灵泉归洗眼，谁能故把细书看。"]},{"t":"游洞霄宫","f":"词","c":["宿雨顽云拨不开，紫霄佳处访楼台。","青山九锁固奇甚，古洞一深如此哉。","拔地千林俱秀润，擎天一柱最崔嵬。","出山爽气尚相属，数里清溪送我回。"]},{"t":"游香山次王正言韵","f":"词","c":["四山过雨翠光流，境胜心閒自点头。","野鸟叫春多格磔，晚风吹鬓故飕飗。","三年几作旧山梦，一笑喜成今日游。","独叹寒泉本无意，强随机械走溪沟。"]},{"t":"游隐清 其二","f":"词","c":["瀑泉奔放石坡陀，回首清游岁几何。","脚力不如前日健，诗盟还喜故人多。","滕王阁上无韩子，还景楼中欠老坡。","不谓鄙言成宿谶，偶因晚涖得波波。"]},{"t":"游隐清 其一","f":"词","c":["簿领丛中偷得閒，轻舆相与出乡关。","乱流先已登孤屿，采蕨还来上北山。","藤绕龟身增赑屃，水涵虹影照孱颜。","老农拥道迎人笑，今日使君来破悭。"]},{"t":"游隐清 其三","f":"词","c":["穷冬吏鞅解纷缠，重入兹山忆少年。","千里幸同丰岁乐，三生曾结郡人缘。","几番山色望空外，今日水声来耳边。","坐上何须听丝竹，与君啸咏和风前。"]},{"t":"游惠山","f":"词","c":["石径萦回入翠林，廿年故步喜重寻。","千山直上云扉启，万木阴中古殿深。","泉水泓澄风拂拂，洞门幽杳昼沈沈。","调琴瀹茗清无限，倦客忘归到夕阴。"]},{"t":"湖上次袁起岩安抚韵","f":"词","c":["同年紫陌再寻春，力主斯盟赖尹京。","山外斜阳湖外雪，夜来阴霭晓来晴。","平波滟滟新添绿，冻木欣欣欲向荣。","此日此身清洁甚，软红何苦太忙生。"]},{"t":"湖亭观竞渡","f":"词","c":["涵虚歌舞拥邦君，两两龙舟来往频。","闰月风光三月景，二分烟水八分人。","锦标赢得千人笑，画鼓敲残一半春。","薄暮游船分散去，尚馀箫鼓绕湖滨。"]},{"t":"登蕺山","f":"词","c":["晚步蕺山上，休辞脚力穷。","八松不碍眼，万里欲乘风。","逸兴浮沧海，高歌彻太空。","羲之不可见，犹得想胸中。"]},{"t":"程文简公挽词 其三","f":"词","c":["设卦探羲画，随山究禹谟。","仰天真见象，画地可成图。","健笔凌前辈，残膏浃万夫。","登门嗟最晚，犹得觇宏摹。"]},{"t":"程文简公挽词 其二","f":"词","c":["太上崇耆旧，龙鳞手可攀。","胡为遁荒野，竟复老商山。","汉阁颁纶渥，瀛壖拥旆还。","灵光遂陈迹，西望涕空潸。"]},{"t":"程文简公挽词 其一","f":"词","c":["论著大哉尧，英声早已昭。","横飞钦远业，特立仰高标。","言议超千载，风猷耸四朝。","惜乎经世学，不及珥金貂。"]},{"t":"腊月二十五日大人生朝","f":"词","c":["去年沙岸倚归舟，今日驱车古涿州。","綵服难陪莱子戏，巴词应付雪儿讴。","客途行及五千里，寿宴须开十二楼。","南望飞云天样远，太行山外久凝眸。"]},{"t":"蒋慈溪挽词 其二","f":"词","c":["下笔欲生风，磨砻日有功。","推敲诗益鍊，骈俪语尤工。","经问南雷叟，家传十八公。","词人谁可继，文阵滑稽雄。"]},{"t":"蒋慈溪挽词 其一","f":"词","c":["伊昔丹丘去，相逢意气倾。","楼前巾子秀，山下育泉清。","敬梓情逾厚，交梨论益明。","凄凉千古意，潮落又潮生。"]},{"t":"蒋德尚棋会展日次韵","f":"词","c":["棋社经年能几回，身闲深幸屡参陪。","一旬又见朋簪集，三径还因听履开。","休苦索居徒面壁，何如相遇且衔杯。","虽由药裹宽初约，不碍重寻旧雨来。"]},{"t":"谢太守送雪次韵","f":"词","c":["一冬祇见晓霜寒，未得飞霙万里看。","多谢黄堂赠圭璧，欲从乳窦倚栏干。","檐高安有冰成柱，坐久空馀水在盘。","岁晚愿呈三白瑞，要观积玉满林端。"]},{"t":"谢王粹中惠白鹤山麟川观斑竹杖并竹舆","f":"词","c":["麟川仙馆翠琅玕，荷子携来白鹤山。","未效葛陂龙种化，绝胜湘浦泪痕斑。","裁为拄杖一寻许，巧作轻舆四尺悭。","儿子门生俱努力，病夫欲过虎溪还。"]},{"t":"谢陆伯业通判示淮西小藁","f":"词","c":["四海诗名老放翁，遗编俱在迹成空。","忽从淮右传诗卷，近比剑南真父风。","暂向壶头追马援，何当甫里访龟蒙。","江山为助多佳句，莫惜南来寄断鸿。"]},{"t":"谢剡中沈元龙惠诗","f":"词","c":["东阳何事到东州，百语曾无一语酬。","深羡松筠无改叶，自言蒲柳已先秋。","千金既觉成虚掷，双璧还惊又暗投。","别后未知何日见，但将吾道付沧洲。"]},{"t":"谢黄汝济教授惠建茶并惠山泉","f":"词","c":["几年不泛浙西船，每忆林间访惠泉。","雅好谁如广文老，亲携直到病夫前。","细倾琼液清如旧，更瀹云芽味始全。","或问此为真品否，其中自有石如拳。"]},{"t":"谢景英送郑景元篇末见属次韵","f":"词","c":["张罗清似翟公门，门外都无野雀喧。","可但风流追鲍谢，直教高论到羲轩。","绝怜父子为知己，时把文章得细论。","个里是非何足较，乍贤乍佞一王尊。"]},{"t":"谢蒋行之送菊","f":"词","c":["秋老情怀尽自宽，眼前只欠菊花团。","分来三径双株秀，先得重阳两日看。","玉软金轻无限态，风高露冷不胜寒。","幽人相对成清伴，正尔落英供夕餐。"]},{"t":"谢雷季仲枢密惠社饼","f":"词","c":["宠分饼卷荷深情，割肉烹鲜不厌精。","潭府始知严社祭，衰门又得诧侯鲭。","洗杯用荐逡巡酒，下箸如餐谷董羹。","回首枌榆未能去，欲随秋燕问归程。"]},{"t":"谢僧道全惠诗并菖蒲","f":"词","c":["楚楚芳荪诗样清，翠苗低护小峥嵘。","一泓功借幽根润，六月能令凉意生。","雁荡浑如梦边事，龙湫顿觉眼中明。","閒窗坐对思无限，何日随君绕涧行。"]},{"t":"谢滕宰彦可惠诗","f":"词","c":["与君相遇海东头，明月如何忽暗投。","自愧重来千岁鹤，永怀静对五湖鸥。","新编不觉成三复，妙思诚堪比四愁。","还肯来游鄮山否，与君携手上东楼。"]},{"t":"谢颜乐閒篆离骚","f":"词","c":["乐閒下笔素推高，攻愧耽书老更饕。","顾我好看秦小篆，烦君为作楚离骚。","晚年应悟成歪匾，痛饮犹堪写郁陶。","喜剧但知藏十袭，琼瑶无以报投桃。"]},{"t":"鲁少卿挽词 其二","f":"词","c":["前辈风流泯，灵光独岿然。","指囷推甲族，跪履记丁年。","有子伤埋璧，惟翁亦蜕蝉。","功名虽已矣，千载尚遗编。"]},{"t":"鲁少卿挽词 其一","f":"词","c":["棣萼仪鸳缀，翛然两鬓斑。","时清嗟岁晚，游倦得身闲。","人在羲皇上，经传伯仲间。","桂枝芳未已，何止倍燕山。"]},{"t":"携家再游姚江","f":"词","c":["又作泛舟行，浮家一叶轻。","潮生江外晚，月比夜来明。","云尽天容彻，风高水气清。","五湖乘兴去，何苦慕功名。"]},{"t":"粮料院葵向亭","f":"词","c":["结屋苍崖昼不哗，崚嶒乱石绕帘牙。","涛江渺莽三千顷，烟瓦参差百万家。","雉堞环山馀暮雪，龙楼耸阙焕朝霞。","登临可是望都省，但有葵心向日华。"]},{"t":"群从泛湖次叔韶弟韵","f":"词","c":["倚遍瀛洲十二栏，老蟾推出烂银盘。","绝怜千顷波澜阔，更觉满身风露寒。","境胜能令诗兴逸，夜深自喜酒肠宽。","离离挂影清如许，莫惜终宵作意看。"]},{"t":"肆赦小雨","f":"词","c":["端门宣赦乐欢然，膏泽还应降九天。","始觉耳边鸣摵摵，渐看笏上溜涓涓。","我班金阙鸡竿侧，君侍玉皇香案前。","雨立固知同陛楯，一言犹幸赖优旃。"]},{"t":"锦镜","f":"词","c":["两溪赴壑若奔虬，此地端能截众流。","三版放开千丈雪，一奁清彻四山秋。","几年空自存公案，今日重新指路头。","珍重老师成胜事，清名当与此山留。"]},{"t":"鲍潮州挽词 其二","f":"词","c":["客授壬辰岁，巍科盛永嘉。","芹宫屡挥麈，竹院几烹茶。","假守深交谊，清谈及道家。","犹怀郡斋晚，群雀噪檐蛇。"]},{"t":"鲍潮州挽词 其一","f":"词","c":["三试皆前列，一官何后时。","低佪广文舍，龃龉使君麾。","遇事有如烛，卫生宁及葵。","旧游成隔世，流涕读新碑。"]},{"t":"端明殿学士王公挽词 其一","f":"词","c":["片言寤主上亨途，几向专城佩左鱼。","羊陆遐冲虽坐折，高文宿愤竟谁摅。","平时屡草千言奏，垂绝犹腾八难书。","汉殿履声今已矣，两州遗老倍欷歔。"]},{"t":"端明殿学士王公挽词 其二","f":"词","c":["短檠铁研用功深，万卷蟠胸不辍吟。","故国遁身来济岱，壮年发藻向儒林。","爱民利物平生事，忧国忘家一片心。","史馆顷年陪润色，挽公无路涕盈襟。"]},{"t":"端明殿学士张公挽词 其一","f":"词","c":["天分已高明，乐哉贤父兄。","勋名希葛亮，问学本诸程。","襟满英雄泪，琴亡手足情。","相从九泉下，何处觅三英。"]},{"t":"端明殿学士张公挽词 其三","f":"词","c":["英略古无对，外庸今最良。","众方期共政，人已叹云亡。","不听尚书履，犹怀太守章。","康庐星忽堕，丹旐袅清湘。"]},{"t":"端明殿学士张公挽词 其四","f":"词","c":["昔幸参朝列，于公更有连。","规模包世界，风义薄云天。","送别诗犹在，贻书墨尚鲜。","伟人无复见，惟务宝青毡。"]},{"t":"端明殿学士张公挽词 其二","f":"词","c":["籍甚张京兆，精神满腹中。","才高解牛刃，手敏运斤风。","河浒恩波远，廛间狡穴空。","章台旧时柳，无复映金狨。"]},{"t":"端明殿学士汪公挽词 其三","f":"词","c":["道学不尽试，功名祇绪馀。","立朝惟正色，荐士有遗书。","百赎嗟无及，九京谁与居。","莫酬推毂意，衰涕湿巾裾。"]},{"t":"端明殿学士汪公挽词 其一","f":"词","c":["制阃诗书帅，公朝侍从臣。","身能全进退，人可得疏亲。","曳履声犹在，持衡迹遂陈。","从今几百载，更复见斯人。"]},{"t":"端明殿学士汪公挽词 其二","f":"词","c":["蚤岁声名大，婆娑始遇时。","难兄屏隔坐，令子桂芳枝。","人望还为用，天胡不慭遗。","成蹊堪喻大，堕泪不须碑。"]},{"t":"缪伯恭挽词","f":"词","c":["我实由汪出，垂髫托外门。","非惟拜先德，犹及见新婚。","谨厚推乡曲，恩慈笃弟昆。","善人今已矣，馀庆在儿孙。"]},{"t":"臧温叟挽词","f":"词","c":["白首行逾恭，乡评敬此翁。","心开上池水，气袭舞雩风。","礼貌诸公厚，声华一瞬空。","臧孙知有后，三世著阴功。"]},{"t":"樊运使挽词 其三","f":"词","c":["科目公馀事，南宫第一人。","七闽新使节，三署旧儒臣。","倦拜方辞馈，哀良莫赎身。","家声知有继，仙桂两枝春。"]},{"t":"樊运使挽词 其一","f":"词","c":["妙龄便有老成风，孝友丹心天与通。","师友渊源得西洛，文章声价冠南宫。","固知夫子才难用，犹喜先生道不穷。","他日凤泉山下路，几人下马拜茔中。"]},{"t":"樊运使挽词 其二","f":"词","c":["樊侯勋德佐中兴，百世儿孙尚典刑。","阖境民苏御史雨，列城人仰使君星。","宪台严冷独峨豸，道院清闲谁掣铃。","谣颂洋洋在人耳，不须乐石更刊铭。"]},{"t":"樊运使挽词 其四","f":"词","c":["横浦云亡后，斯文付此贤。","命其随道丧，学又绝心传。","河洛湮来派，西州忆旧缘。","伤心耆老尽，挥泪对霜天。"]},{"t":"潘大卿挽词","f":"词","c":["直上青云不作难，壮年何事挂衣冠。","功名已矣乖时望，风节翘然见岁寒。","鸿去冥冥矰不到，蝶飞栩栩梦惊残。","伤心耆老今无有，留得遗编向后看。"]},{"t":"题天竺圭老复庵","f":"词","c":["路从天竺更微南，衲子邀余过复庵。","八法照人瞻睿藻，一峰当户拥晴岚。","奇爻初动玩羲画，万物并观师老聃。","六用不成均此理，楞严容我为同参。"]},{"t":"题少潜兄得闲 其二","f":"词","c":["平日君多暇，如今我亦闲。","人归真得地，吏隐胜居山。","烟浪一千顷，茅檐三四间。","天寒倚修竹，空翠湿攲鬟。"]},{"t":"题少潜兄得闲 其一","f":"词","c":["亭下水吞空，轻舟处处通。","闲情谁得似，逸兴更何穷。","诗社率相过，醉乡时一中。","我家元不远，只在小桥东。"]},{"t":"题尤延之给事所藏葛仙翁徙居图","f":"词","c":["莫言家具少于车，药裹衣囊自有馀。","老妇亲携三稚子，仙翁独玩一篇书。","羊牛相与趋新筑，鸡犬无因恋故庐。","到处山头有丹井，不知如此几迁居。"]},{"t":"题陆放翁诗卷","f":"词","c":["妙画初惊渴骥奔，新诗熟读叹微言。","四明知我岂相属，一水思君谁与论。","茶灶笔床怀甫里，青鞋布袜想云门。","何当一棹访深雪，夜语同倾老瓦盆。"]},{"t":"题林氏香严庵","f":"词","c":["缓步寻佳处，林深路欲迷。","偃松披数亩，立竹漱三溪。","瀹茗凭山槛，呼灯照石梯。","轻舆空翠湿，投暝喜幽栖。"]},{"t":"题施武子所藏醉白堂记","f":"词","c":["堂名醉白尚存不，词翰辉光射两眸。","天下曾除苏氏学，禁中却有太清楼。","旧碑于世已难见，真迹惟君乃得收。","感叹不堪衰泪落，林虑山下水空流。"]},{"t":"题桃源王少卿占山亭","f":"词","c":["纳纳乾坤一草亭，西山尽见若秋屏。","霜馀远水呈天碧，雨过遥空现帝青。","逸叟真成陶令隐，高怀长似屈原醒。","肯堂固赖贤孙子，精爽犹疑尚有灵。"]},{"t":"题郭恕先雪霁江行图","f":"词","c":["妙绝丹青郭恕先，幻成雪霁大江船。","沿流更饱轻帆举，上水仍劳百丈牵。","捩柂长年浑欲动，褰帷佳客若将仙。","侍亲曾泛沧浪月，犹记兰成射策年。"]},{"t":"题惠崇著色四时景物","f":"词","c":["旧说惠崇真画师，生绡四幅见天机。","鹭翻桃岸韶光妩，鹅漾莲塘暑气微。","风劲宾鸿霜始肃，寒欺花鸭雪初飞。","分明知是丹青卷，仍欲沙头唤渡归。"]},{"t":"题韩氏所藏元祐选尚诏草","f":"词","c":["禁脔当年选尚初，难兄辞宠意何如。","裕陵遗旨知难改，元祐湛恩信有馀。","今日犹存卯君笔，向来谁造粉昆书。","韩门世宝宜无坠，史有遗文尚取诸。"]},{"t":"颜侍郎挽词 其二","f":"词","c":["禄养嗟无及，朝朝饭一僧。","移忠躬蹇蹇，锡类日烝烝。","赋政优吴郡，知贤仰阜陵。","清忠与公恕，馀庆启昆仍。"]},{"t":"颜侍郎挽词 其一","f":"词","c":["宴坐勿庵上，睎颜亦是颜。","平心真似水，立说信如山。","屡拥皇华节，盍登清禁班。","始终无玷阙，风裁许谁攀。"]},{"t":"颜侍郎挽词 其三","f":"词","c":["赘倅丹丘日，眼看康济泉。","同朝叨奖予，侍坐得周旋。","妙画多传宝，遗文合细编。","典刑今已矣，西望涕潸然。"]},{"t":"廨舍小轩","f":"词","c":["衮衮群山尾，横窗更此岑。","尘埃遮物外，风物宛山阴。","作吏何妨隐，寻山不用深。","居然一丘壑，便足快登临。"]},{"t":"潚再往剡中念之尤切作诗宽之","f":"词","c":["剡县不为远，丞官勿谓卑。","鼓盆知爱重，去国倍行迟。","堂上森三老，房中秀一儿。","加餐了官事，莫赋悼亡诗。"]},{"t":"次韵十诗 燕居","f":"词","c":["大老今居东海滨，燕居晚岁更申申。","外生但喜长依教，一笑相从莫问贫。","闲里只将诗作活，酒边犹有笔如神。","乞言授几俱休论，且作羲皇以上人。"]},{"t":"赠别卢甥申之归吴门","f":"词","c":["千里何妨命驾来，晤言未厌已西驰。","子休重赋琼瑰赠，我亦懒歌亲戚离。","好向清江论乐府，更从叶子说新诗。","乐閒引纸五十尺，为篆离骚继李斯。"]},{"t":"赠宝藏老道源","f":"词","c":["骨相昂藏涧底松，平生禅窟尽从容。","几年大隐清晖阁，今日来瞻独秀峰。","打破画瓶无挂碍，大开饭店喜迎逢。","今朝且逐征途去，何日重来听晓钟。"]},{"t":"赠蜀二史","f":"词","c":["老我挂冠惭复弹，羡君登第遽休官。","幸哉有子事尤美，专以为亲人更难。","旧说三贤皆特操，今看二士倍荣观。","同归犹及襄阳老，一舸清风廿四滩。"]},{"t":"赠僧文可往黄州建东坡寺","f":"词","c":["一坡久矣郡城东，居士来游地望崇。","问舍求田烦作计，拈槌竖拂看谈空。","共分庞老沈江宝，要奉儋州秃鬓翁。","去作开山第一代，灯灯相续到无穷。"]},{"t":"孺人陈氏挽词 其二","f":"词","c":["令子齐年好，相从识壸彝。","萧生结绶日，孟母卜邻时。","未下升堂拜，俄闻陟屺悲。","天涯致刍束，泪落薤歌辞。"]},{"t":"孺人陈氏挽词","f":"词","c":["追忆宫端旧典刑，三贞况复是难兄。","岂惟门户生光彩，直使朝廷列姓名。","烟海乘桴谁可夺，天风反火报尤明。","虽云弟娣相从去，自有英灵凛若生。"]},{"t":"孺人陈氏挽词 其一","f":"词","c":["教子推陶母，相望百代前。","诗书经口授，名节诵家传。","艺苑高鸿笔，忠言彻细毡。","源流知有自，何止父兄贤。"]},{"t":"孺人林氏挽词","f":"词","c":["家世甘泉旧，幽闺有令名。","贤明教陶侃，勤苦佐渊明。","蘋涧今何处，鸠桑空复情。","谁知悼亡意，挥涕望佳城。"]},{"t":"孺人钱氏挽词","f":"词","c":["家世戟如林，来嫔蔼德音。","功容俱可度，疾疹遽相侵。","已矣空蘋涧，谁欤助藁砧。","佳儿随玉折，尤切悼亡心。"]},{"t":"戴县丞挽词 其一","f":"词","c":["小戴久仙去，何堪更哭君。","旧游惊昨梦，陈迹怆遗文。","晚暮期相与，死生俄遽分。","铭成愧潜德，挥涕望新坟。"]},{"t":"戴县丞挽词 其二","f":"词","c":["高士终为簿，岂惟勾小稽。","鸾凰虽在棘，桃李自成蹊。","官府资关决，儒流仰品题。","定知馀庆远，遗爱满双溪。"]},{"t":"戴县丞挽词","f":"词","c":["蚤岁乡书荐弟兄，羡君再举上青冥。","蓝田方欲新漫壁，处士宁知却应星。","忍向伯高将束帛，谁从小戴授遗经。","佳城得卜真前定，忍看一翁衰泪零。"]},{"t":"戴迪功挽词 其二","f":"词","c":["好学数仍奇，躬行家遂肥。","时将诗自乐，晚悟世俱非。","教子惟黄卷，高门看绿衣。","阿连悲未泯，无泪为君挥。"]},{"t":"戴迪功挽词 其一","f":"词","c":["犹记天街会，同为乳窦游。","姻家频会聚，亲意愈绸缪。","吉德宜多寿，奇痾竟不瘳。","无由见安道，汎雪怅回舟。"]},{"t":"魏郎中挽词","f":"词","c":["相公钟鼎蔽诗声，鲤也闻诗蚤得名。","高隐碧溪心更远，今游湘浦句尤清。","握兰未足酬吾志，揽辔宁知老此行。","今日哭君谁最切，山房门下老门生。"]},{"t":"魏监丞挽词","f":"词","c":["元老馀风烈，优游挹美官。","朝行喜银艾，邻好许金兰。","医谩肱三折，生惟指一弹。","难兄秋夜感，风雨旧盟寒。"]},{"t":"一月三捷诗","f":"词","c":["勇甚鹰扬将，身从虎穴探。","六师心不二，一月捷凡三。","戎卒时非久，边庭战已酣。","神戈穷逐北，露布屡驰南。","貔旅弥思奋，狼心敢肆贪。","七旬有苗格，较德可无惭。"]},{"t":"习马长杨诗","f":"词","c":["强汉承平后，兢兢武不忘。","整师临五柞，习马向长杨。","冀野来骐骥，天闲出骕骦。","骧腾射熊馆，驰骤华山阳。","辇路千蹄稳，瑶池八骏良。","上方勤阅武，愿赋翰林章。"]},{"t":"飞泉漱鸣玉诗","f":"词","c":["翠巘幽深处，飞泉触石鸣。","跳珠不胜乱，漱玉有馀清。","水落千寻险，风传万壑声。","玲珑铿璧韵，激溅破琼英。","汉水思遗佩，沧浪想濯缨。","何须韩吏部，联句赋琮琤。"]},{"t":"天寒割蜜房诗","f":"词","c":["场圃功初毕，天寒乐岁穰。","山居收蜜课，檐外割蜂房。","弱羽依晴日，纤腰怯晓霜。","铅刀开户牖，棘匕荐甘香。","作室何时再，趋衙未用忙。","百花辛苦处，今日为君尝。"]},{"t":"炙背俯晴轩诗","f":"词","c":["炙背情方适，融霜日正暾。","何妨凭曲几，相与俯晴轩。","爱景欣亭午，闲身得负暄。","映檐成白醉，挟纩谢奇温。","岂止宽寒色，犹思奉至尊。","桃花满肌骨，佳句忆王孙。"]},{"t":"物色访严光诗","f":"词","c":["肥遁推严子，招贤仰汉光。","营求思旧学，物色访群方。","聘问期终得，形容尚未忘。","羊裘方审识，蒲乘遂搜扬。","不羡云台绘，还归钓濑傍。","高风今尚在，江水与俱长。"]},{"t":"复见官军诗","f":"词","c":["元帅平京邑，欢声夹道闻。","不图当此日，复得见官军。","将钺来何莫，壶浆意已勤。","重瞻貔虎士，尽扫犬羊群。","王旅方驰电，民心极望云。","长安十万户，拭目待吾君。"]},{"t":"昼寝正酣以二十韵诗来亟为次韵","f":"词","c":["老氏正求知我希，吾今老矣更何之。","极知仕宦皆由命，纵有功名已过时。","览镜形容宁复我，还乡交友定从谁。","慈亲多幸方难老，家舅尤欣未觉衰。","教诲至今仍似旧，襟期暗合自相知。","新诗必使篇篇和，胜地还容处处随。","昼永剧谈俱喜听，夜深清坐更忘疲。","素钦行己初无玷，愿学持心不自欺。","紫橐清班叨预列，黄金横带忝同垂。","六旬顾我犹加懒，八秩如公尚自持。","但仰三尊知共庆，孰云十拗敢轻嗤。","无情到此方为达，省病从它不用治。","世事只将同蝶梦，人生几得见鸡皮。","观书自适非求解，杖策徐行莫厌迟。","俭素何妨贫胜富，优游真是乐忘饥。","虽然调乐无千指，尽喜当歌有十眉。","报谒要须亲自到，赴筵直以散为期。","醉翁雅意非谋醉，棋社清欢岂为棋。","白发只宜甘散诞，红尘任彼自奔驰。","安舆来往长陪侍，此意终身誓不移。"]},{"t":"残月如新月诗","f":"词","c":["近晦月犹在，萧骚夜向晨。","已残几欲尽，忽见恍如新。","老桂沈清影，馀辉扣半轮。","纤纤两头玉，皎皎一钩银。","明似哉生际，光疑太逼真。","妆楼谁起早，深拜误佳人。"]},{"t":"背水阵诗","f":"词","c":["十里当勍敌，临机事寖危。","蓖山兵已遣，背水阵尤奇。","前泽书诚有，行权我独知。","正须投死地，何用恤群疑。","拔帜终如约，传餐亦应期。","孙吴非纸上，方略要从宜。"]},{"t":"送吴参议","f":"词","c":["才气勇无前，人推季子贤。","侯藩联剖竹，制幕晚依莲。","势利从身外，风流到酒边。","四明欣会遇，两载得周旋。","为记题名石，仍吟达观篇。","留行何及矣，执别但茫然。","我已甘投老，君方欲引年。","未知重见日，目断五湖船。"]},{"t":"陪沈虞卿使君游钱园","f":"词","c":["休沐无官事，公庭且放衙。","城中寻胜地，道上引高牙。","潭府临芳径，东岩玩物华。","山林真夐绝，栋宇谢豪奢。","陶令亲栽菊，秦侯晚种瓜。","裴公馀绿野，六一醉琅玡。","幽阪森三友，飞桥粲百花。","树深藏曲折，谷险路谽谺。","道院罗星斗，禅房供释迦。","鳌峰思御气，画舸想乘槎。","佳处城环雉，吟边路绕蛇。","登山携翠袖，喝道屏银檛。","井市花相映，湖陂柳半遮。","高歌惊野鸟，叠鼓乱鸣蛙。","陛级青珉滑，秋千綵旆斜。","丛篁穿嫩笋，芳草绽新葩。","静憩方开宴，徐行更试茶。","仙醪斟玛瑙，玉指奏琵琶。","清绝嚣尘远，苍茫望眼赊。","诗情弥海峤，饮兴渺天涯。","贤尹民同乐，名郎子克家。","才高修月户，笔妙补天娲。","挥麈风流胜，凭栏笑语誇。","追风惭款段，倚玉愧蒹葭。","逸韵迷春蝶，清欢接暮鸦。","舞茵收地锦，画烛照笼纱。","耋稚欣相告，舆台靖不哗。","微风朝趁马，好雨夜随车。","土脉兴原隰，霖膏润甲芽。","相将劝耕去，和气满桑麻。"]},{"t":"黄知橘柚来诗","f":"词","c":["一舸放长江，遥林底处黄。","自知来橘柚，先已照沧浪。","绿叶凝烟密，金苞射日光。","相迎苍县雨，暗识洞庭霜。","味诧江陵种，庭垂禹庙荒。","何如船上看，数里更飞香。"]},{"t":"新辟门径或谓太窄","f":"词","c":["门外顿空旷，双眸豁太虚。","谁欤列佳树，正尔对吾庐。","蚤岁曾修业，衰年得定居。","买邻贤伯仲，衣锦旧门闾。","未办三閒屋，先栽数席蔬。","欢娱戏莱服，晨夕奉潘舆。","驷马容虽狭，斋郎住有馀。","床金知已尽，瓶粟岂无储。","细草沿阶嫩，新篁得雨初。","窃希仁者静，未觉故人疏。","昼永翻名画，更长理旧书。","何妨抱琴醉，尽好带经锄。","耋稚同甘苦，儿孙共卷舒。","眼花多掩卷，鬓雪不堪梳。","少饮毋求醉，徐行可当车。","此生千万足，祇愿老樵渔。"]},{"t":"置酒沛宫诗","f":"词","c":["汉祖功成后，时因过沛宫。","还乡上心喜，置酒故人同。","高会延遗老，酣歌和众童。","穷欢新笑乐，起舞旧英雄。","慷慨悲游子，轩昂赋大风。","永为汤沐邑，何用筑新丰。"]},{"t":"冀北马群空诗","f":"词","c":["冀北虽多马，知惟伯乐工。","祇因良种去，便觉举群空。","过视千蹄众，先收八骏雄。","谩闻馀布野，无复见追风。","骐骥方奔逸，驽骀岂混同。","傥非承一顾，鸣意孰能通。"]},{"t":"鲲化为鹏诗","f":"词","c":["鲲大几千里，扬鬐气日增。","一时俄化羽，万古记为鹏。","鳞族畴能比，龙门不足登。","天池将转徙，云翼快飞腾。","怪矣齐谐志，壮哉庄叟称。","鸢飞与鱼跃，曾不事誇矜。"]},{"t":"醉翁操 七月上浣游裴园","f":"楚辞体","c":["茫茫，苍苍。","青山，绕千顷。","波光，新秋露风荷吹香。","悠飏心地翛然，生清凉。","古岸摇垂杨，时有白鹭飞来双。","隐君如在，鹤与翱翔。","老仙何处，尚有流风未忘。","琴与君兮宫商，酒与君兮杯觞。","清欢殊未央，西山忽斜阳。","欲去且徜徉，更将霜鬓临沧浪。"]},{"t":"八月十四日携家泛月次韵 其二","f":"词","c":["九秋风月正分平，盛满金晶分外明。","老子此行端不恶，夜深几得圣之清。"]},{"t":"十月旦尚煖用夹公服二月初吉雪寒甚服单","f":"词","c":["尚暖先添夹，方寒却用单。","不惟春料峭，况值雪飞翻。","但欲朝仪肃，难求己分安。","衣囊如欲懒，归去老江干。"]},{"t":"又次王恭叔韵 其一","f":"词","c":["仲冬方寒荔挺出，仲夏方炎靡草死。","若将朝菌比大椿，相去何啻千万里。","金芝仙草不可见，长生之草略相似。","少时曾识青青色，今日得之乃真是。","天工矜悯轻丧生，故出珍苗普相示。","若言神仙可学致，自是未得养生理。"]},{"t":"又次王恭叔韵 其二","f":"词","c":["人为天地最灵物，野卉无情犹若此。","石间薜荔水昌阳，卷柏生崖并葛藟。","是皆草中号长久，未见悬空解葩蕊。","柯叶不改耐岁寒，土著青松那可拟。","不须丹砂访葛洪，毋用仙方传李耳。","未知此种谁为传，乌有先生子虚子。"]},{"t":"又次韵","f":"词","c":["投老归称前进士，时与田夫相汝尔。","渊明赋归何敢望，曼容自免差可拟。","门前爵罗真可设，老圃灌畦聊自比。","恕斋空洞最相亲，笑谈颇觉清无滓。","时时过我共衔杯，望望不来予为企。","丈夫未遇困泥涂，谁识鸾停兼鹄峙。","方期从容结诗社，相与浮湛向闾里。","一朝别我欲远游，欲入桃源深洞里。","为言半隐欲偕行，二子风流真俪美。","向来早有四方志，行尽东南到边鄙。","只今名利遂两忘，争心无复于朝市。","祇有哦诗兴未阑，连得新诗照尘几。","调高韵险不易和，白雪阳春惊俚耳。","年登六十鬓未斑，乘兴一行若可喜。","宗盟莫逆素相忘，并辔笑谈无彼此。","湖海豪气尽收敛，以恕名斋几一唯。","匆匆掺袪不得留，卮酒未乾人欲起。","寄声半隐不容言，空有语离书满纸。","归时赓和必盈箱，写尽山川诗作史。","送子才归深闭门，莫问是非并誉毁。","但期远归亦升堂，西湖仍访老知章。"]},{"t":"又送从子㴶","f":"词","c":["二孙吾所爱，别去殊关情。","阿剡将赏延，伴子性亦灵。","烦子善诱之，他日使有成。","公馀松竹林，共勉洛诵声。"]},{"t":"又题杨妃上马图","f":"词","c":["金鞍欲上故徐徐，想见华清被宠初。","后日延秋门下路，不应有暇作踟蹰。"]},{"t":"三日不得过都泗堰","f":"词","c":["南朝何公栖禹穴，嘉遁悠然志高洁。","一朝送人都泗埭，归叹此途于此绝。","我亦何为走尘埃，数年不记几往来。","船横三日不得度，愧想高风安在哉。"]},{"t":"久不作诗喜仲兄迁邻居因成长句","f":"词","c":["宦游各天涯，皇州今雁行。","官居半里所，相过复相望。","西邻得老屋，往来连户窗。","水竹占幽胜，风雨对一床。","十年短檠灯，今夜分馀光。","儿曹亦可乐，洛诵声洋洋。","天边有白云，随风正飞扬。","相期奉旨甘，莱衣戏亲傍。","轩冕皆傥来，此意可暂忘。","诗成喜可知，且复釂此觞。"]},{"t":"大龙湫","f":"词","c":["北上太行东禹穴，雁荡山中最奇绝。","龙湫一派天下无，万口赞扬同一舌。","行行路入两山间，踏碎苔痕屐将折。","山穷路断脚力尽，始见银河落双阙。","矩罗宴坐看不厌，骚人弄词困搜抉。","谢公千载有遗恨，李杜复生吟不彻。","我游石门称胜地，未信此湫真卓越。","一来气象大不侔，石屏倚天惊鬼设。","飞泉直自天际来，来处益高声益烈。","从他倒泻三峡流，到此谁能定优劣。","雁山佳趣得要领，一日尽游神恶亵。","骊龙高卧唤不应，自愧笔端无电掣。","轮囷萧索湍不怒，非雾非烟亦非雪。","我闻涷雨初霁时，喷击生风散空阔。","更期雨后再来看，净洗一生烦恼热。"]},{"t":"大梅山","f":"词","c":["此山名大梅，驱车入山麓。","试问山中人，山名竟谁属。","禅家开道场，为说梅子熟。","仙家指为岩，曾此隐梅福。","或云古有梅，其大蔽山谷。","至今二梅梁，灵响皆其族。","他山抗惊湍，禹祠横殿屋。","三者尚谁凭，禅师有遗躅。","馀皆不可辨，安得究图录。","但爱山又山，乔林间脩竹。"]},{"t":"小溪道中","f":"词","c":["晚出城西门，循墙过南境。","夏桥日沉辉，沈店月成影。","纳纳川路遥，聒聒水声冷。","攲枕拥衾裯，乐此寒夜永。"]},{"t":"山行归来喜栽新竹","f":"词","c":["平生好看竹，每见觉相与。","小大或疏密，一一皆媚妩。","恨无地可种，所至造竹所。","近方辟门径，得地寻丈许。","乞邻栽百个，参差正当户。","天公有老眼，惠以三日雨。","山行不厌泥，但喜竹无苦。","归来报平安，翠叶多楚楚。","不妨来子猷，奚必希蒋诩。","何当绕扶疏，岁寒与君侣。"]},{"t":"巾山","f":"词","c":["两鳌赑屃随西行，势欲吸尽西江清。","是谁缭以千丈城，欲去不去岂不灵。","化为青山镇东溟，首冠窣堵双峥嵘。","安舆从东喜逢迎，笑指鳌背同来登。","春残雨足绿阴成，山鸟相和声咿嘤。","自从半山经小亭，仰望巨石扶轩楹。","千山万山拥翠屏，阴霾扫静纤云兴。","翠微下有长江横，衮衮不尽千古情。","广轩俯瞰万瓦平，佳处历历堪指名。","雪蓬蹙云连曲肱，蜂房蚁垤栖残僧。","扶栏更上三两层，一览物象无遗形。","徙倚未厌茗椀倾，长啸两腋清风生。","亲颜甚怡轮为停，我亦色笑喜不胜。","愿我双亲俱遐龄，方瞳鍊颜华发星，如此两峰相对青。"]},{"t":"书全无用语录","f":"词","c":["全公无用，无用之用。","生前已自无用，死后葛藤何用。","虽然如是，善用者必自有用，不善用者不如勿用。","试问大众，如何则为善用。","有时拈起一枝草作丈六金身，有时把丈六金身却作一枝草用。"]},{"t":"云岩","f":"词","c":["但见云生谷，初无石似岩。","得名非旧观，买地作精蓝。","境胜环修竹，门深拥翠杉。","禅林自家处，莫问后三三。"]},{"t":"以太湖石响板为文季寿","f":"词","c":["太湖中心洞庭山，千岩万壑高孱颜。","风涛舂撞自太古，漱成乐石如雕剜。","玲珑中空穷变态，奇奇怪怪罗沧湾。","良工巧手琢威凤，片云承足同飞翻。","叩之五声八音足，疑有仙风摇佩环。","月卿蜚声塞宇宙，文如九苞瑞世间。","祇今在治真若凤，朝阳一鸣闻九关。","先从鹓阁掌帝制，径上鸾台领朝班。","德既不衰石不泐，祝公遐寿如彭篯。"]},{"t":"以兴安石阮底寄颜乐閒","f":"词","c":["兴安乐石响于桐，作阮犹堪继仲容。","茂苑乐閒真好事，为君添起晋玲珑。"]},{"t":"六月十六夜观月翌早纪所见成长谣","f":"词","c":["海云涌立双铁山，明月正在山中间。","初疑渼陂蓝田出水面，又似长风吹度玉门关。","须臾云过月愈上，太虚点缀从飞翻。","白衣苍狗不足究，千变万态俱可观。","忽焉横卧如苍龙，骊珠颔下光团团。","山河清影见历历，桂枝扶疏若可攀。","夜深醉倒鸡鸣起，光景不类居尘寰。","长庚晔然朝曦发，望舒犹挂西林端。","我欲呼吸晶华驻朱颜，左有金丹右玉丹。","昔闻两曜在天如磨蚁，日行日止一度悭。","太阴行速朔必会，金饼旋复成弓弯。","八卦万物尽关系，历古不已真跳丸。","急景惝恍难控抟，但见霞彩生斓斑。","老我已复卦气阑，学道无成空自叹。","不如安坐委天顺，一听运化更循环。"]},{"t":"分韵送卢国华福建提刑得华字","f":"词","c":["卢侯场屋声，天马腾渥洼。","残膏沾后人，奇芬吐天葩。","来踏九陌尘，去种河阳花。","向来再去国，盛山建高牙。","平生长者誉，静笃语不哗。","古井绝微波，璞玉无纤瑕。","使星照蜀道，惠爱流三巴。","吏奸赖刮磨，民瘼烦搔爬。","田里诵卢公，儿童知国华。","白首尚郎潜，坐曹事如麻。","翩翩拥轺车，去去向合沙。","朝行惜君去，举酒相邀遮。","共登狮子峰，巨石临唅呀。","却来澄湖边，野梅访萌芽。","老柳扫黄叶，枯荷矗寒茄。","棋枰战文楸，醉帽攲乌纱。","伊昔送君行，相去万里赊。","荷君远寄书，得得来东嘉。","一见又成别，感念成咨嗟。","羡君径褰帷，往戍不待瓜。","先寻上水船，何殊泛仙槎。","作粥喜奉姊，上冢仍过家。","此计正未疏，所恨成天涯。","尚几或留行，船鼓毋庸挝。"]},{"t":"分韵送孙从之司业使湖南得千字","f":"词","c":["夫君静而敏，人十己则千。","读破万卷书，操笔思涌泉。","古事与今事，一一探本源。","蚤蜚场屋声，作吏志益坚。","朅来上清班，汉庭谁在先。","雍容行秘书，史馆躬椠铅。","片言寤明主，立使登谏垣。","拳拳忧国心，倾倒十三篇。","司成天下选，归志已浩然。","赤日送妻子，襆被寻溪船。","诸生慕阳城，欲挽不得专。","竟持湖南节，征袂何翩翩。","忆昨忝同登，于今三十年。","朝行喜相会，终恨非官联。","请益殊未餍，匆匆启离筵。","始以长官来，今以绣衣还。","书生素安分，岂问却与前。","第惟公辈流，自应留日边。","德星聚南楚，予环当茹连。","事体有关系，临岐欲无言。"]},{"t":"少及兄真率会","f":"词","c":["昼锦坊中作真率，群从相过无俗物。","主人就树折杨梅，醉倒薰风凉拂拂。","小舟傍城登雉堞，坐看白鸟苍烟没。","须臾撑出洞天去，杰阁三层高突兀。","樽前赋诗贵神速，十分钝似辽天鹘。","从他银漏促残更，要见林閒红日出。"]},{"t":"月夜汎舟姚江","f":"词","c":["秋暑不可能，几思泛中川。","晚来兴有适，溪船偶及门。","凉月才上弦，平潮可黄昏。","倚楫纵所如，卧看龙泉山。","长虹跨空阔，过之凛生寒。","坐稳兴益佳，夜气方漫漫。","草虫鸣东西，飞乌相与还。","仰头数明星，垂手摇碧澜。","坐客惜此景，不及携清樽。","无酒要不恶，徜徉足幽欢。","幽欢有何好，叩舷澹无言。"]},{"t":"木蕴之国博迁居 其一","f":"词","c":["寄斋今日又迁居，门巷相过五尺馀。","王子何妨借人屋，渊明不必爱吾庐。","大千眼里无非寄，三十乘中皆是书。","祀灶卜邻无用尔，祇今天上有锋车。"]},{"t":"王夫人挽词 其二","f":"词","c":["荆国风流远，幽闺女教循。","鸰原惊逝水，鹤发倍沾巾。","厚夜招香魄，英词列翠珉。","祇愁书字拙，贻笑卫夫人。"]},{"t":"王夷仲夫人挽词","f":"词","c":["彤史无人续，谁能识壸彝。","蘋蘩奉先祖，诗礼付佳儿。","未见鱼轩乐，俄兴鸾镜悲。","藁砧方得路，肠断悼亡诗。"]},{"t":"王成之给事囿山堂","f":"词","c":["烟雨望丽阳，前山罗紫翠。","照水挹南明，不与巾子对。","朅来登囿山，一览万山会。","莲城山固多，此地要为最。","主人意轩豁，物境供旷快。","山椒涌华屋，迥立风埃外。","一物无遁形，所在见纤介。","清霜肃天壤，佳树隔阛阓。","俯仰随取舍，左右从盼睐。","门墙寻故步，杖屦许从迈。","恍然至绝顶，更觉宇宙大。","樽酒屡劝酬，棋枰更胜败。","秋高月色皎，浮云了无碍。","不俟攀仙掌，徒手吸溪濑。","兹堂极崇敞，意若欠深邃。","先植易生木，徐待松柏兑。","望远仍可喜，意满聊自晦。","无使山下人，或得窥外内。","但恐趣赐环，树艺或不逮。","先生味斯言，一笑相领解。","吾将饬园丁，随处添翳荟。","他时绕扶疏，吾庐益可爱。"]},{"t":"王侍御寿诗","f":"词","c":["史君威名闻四方，南床凛凛凝秋霜。","史君和气到瓯越，幕府初开夜飞雪。","颇闻此雪仍岁无，定知来随御史车。","黄堂洗印未多日，庆朝况此当悬弧。","明年丰登日可数，父老儿童争起舞。","迟明贺版拥谯门，试拾欢谣作诗语。","史君风度神仙人，相门出相宁非真。","妙龄两科谈笑得，晚趋严召依风云。","台端敢言奸听耸，至今谠论时传诵。","踏遍巫山十二峰，却寻春草池塘梦。","人传史君威棱棱，我知威爱元兼行。","苍髯如戟面如铁，惠养自有循良称。","高牙入境纷进谒，宾属庭趋公磬折。","民生共喜爱日温，吏行独畏春冰裂。","向来夔州妙筹边，夷蛮落胆皇灵宣。","还朝奏课居第一，夜半帝席为之前。","东嘉今为股肱郡，小试望之三辅近。","会循故事入三公，致君要使登尧舜。","东风未动春先回，梅花照眼歌筵开。","吏民合词颂难老，一笑千里传银杯。","佳儿恂恂授衣钵，玉树芝兰俱秀发。","江南世胄比长淮，更看云来萃簪笏。","平生知己今上天，敢复坐叹寒无毡。","巴言未足赞公寿，载诵峻极崧高篇。"]},{"t":"王叔达以尉彭泽潜玉洞述见示","f":"词","c":["书岩已奇甚，潜玉尤伟哉。","李君漫盘谷，元子空峿台。","神不得自秘，天应为君开。","渊明如得此，应不赋归来。"]},{"t":"王忠文公挽词 其一","f":"词","c":["夙负敢言气，输忠不爱身。","刘蕡仍遇主，绮季更忧民。","治行真循吏，风棱古诤臣。","荐绅千载恨，不得究经纶。"]},{"t":"王原庆新迁居南堂以古风求写恕斋二大字并石刻次韵","f":"词","c":["三槐诸孙有奇士，才高特未遇时尔。","作诗尤能备众体，短章大篇仍杂拟。","解纷使掉三寸舌，随陆苏张何足比。","雕鹗犹未离风尘，蛟螭尚尔蟠泥滓。","平生曳裾向侯门，豪杰闻风竞瞻企。","只今交游亦凋落，凛凛一身嗟独峙。","槐阴满庭渺何在，久寓瀛壖成故里。","濒湖小楼太孤露，何殊玉川洛城里。","迩来深入作郊居，高屋好山成二美。","未能拔剑斩楼兰，几欲袖椎摧晋鄙。","便将拂袖武陵溪，谁能著脚长安市。","西门性急佩柔韦，柳子气高戕曲几。","衡宇全似归柴桑，茅茨大胜居儋耳。","我诗非工字尤拙，荷子爱忘刚见喜。","夜来纵笔写恕斋，自笑黔驴技止此。","更求古刻访少作，颇记醉中曾诺唯。","旧书纷沓费搜寻，鱼钥未开尘事起。","呼童卷送三数轴，仅可障风同故纸。","新诗鼎来亟予和，颠字敢追张长史。","不须更投苦海中，一笑以还随弃毁。","径须携酒登南堂，朗咏白驹三四章。"]},{"t":"王敏肃公挽词 其一","f":"词","c":["□□□□□，□□□□□。","□□□□□，□□□宣公。","全蜀增天险，长淮折犬戎。","经纶今已矣，贯日有馀忠。"]},{"t":"王遂安挽词 其二","f":"词","c":["学问自冰翁，词章耸巨公。","不惭循吏传，真有古人风。","扪虱书犹在，飞凫迹遽空。","人琴悲子敬，三读怆深衷。"]},{"t":"长生草","f":"词","c":["我方髫龀时，已复见兹草。","仲舅尉江阳，奉亲颜色好。","窗门挂经冬，蛛丝罩轻缟。","意为霜雪残，白花乃明杲。","世间三友外，此有岁寒操。","年至十七八，童心如木槁。","随时到柯山，逢人细访考。","买之野人手，何须访蓬岛。","尝为伯氏寿，作诗颂难老。","经今五十年，得自江南道。","老我日就衰，岁月岂长保。","一笑哦子诗，犹将伴梨枣。"]},{"t":"风琴","f":"词","c":["渊明有琴本无弦，白傅偏喜听人弹。","不如空中风度曲，随风往来声断续。","非宫非商从君听，不中律吕无亏成。","大如角韵来孤城，细似蚓窍苍蝇声。","华亭夜鹤圆吭清，颤动长引寒蝉鸣。","或疑凤咮叫霄汉，又恐仙佩云中行。","使其似曲无别调，安得自在声泠泠。","蛙喧尚谓胜鼓吹，牛鸣犹以黄钟称。","丝不如竹亦漫语，赖此七窍俱珑玲。","幽人院静新凉生，八风不问来纵横。","短簟六尺午睡足，彷佛神来传广陵。"]},{"t":"仙都独峰","f":"词","c":["汉家武彻求神仙，方士扼掔多夸言。","蓬莱隔海不可到，属车方羊上桥山。","传闻黄帝久仙去，胡为有石高巑岏。","游谈不经理欲屈，谩言此地藏衣冠。","缙云自是仙窟宅，万壑千岩比如栉。","突然一石摩青云，造化应劳巨灵擘。","仙风吹堕碧莲花，玉井半空人不识。","望之不计几千尺，八柱擎天此其一。","伯夷制行高且孤，万世犹能立懦夫。","英魂凛凛今不死，化作此石山之隅。","横斜辙迹依然在，我亦何能穷古初。"]},{"t":"代书寄内弟耐翁总干","f":"词","c":["我昔生外家，半世犹相依。","至今连墙居，日日相闻知。","诸表如群从，休戚真同之。","耐翁生而秀，爱惜从儿时。","文采既俊发，吏才人共推。","低徊久选调，每每为叹咨。","兹行佐王人，未到声已蜚。","邮置屡得书，论事语益奇。","使长首推荐，婉画多所资。","近观会稽编，分析及毫釐。","益知足心计，荐书遍诸司。","正欲助才选，非敢请以私。","惜君年欲侵，正以远大期。","得书再三读，惘然增愕眙。","非所望于子，所言何背驰。","江湖两路间，弄兵分潢池。","羽檄以时至，庙堂日三思。","调度供军需，发兵匝四垂。","吾事诚可虑，彼亦安能为。","岂曰白头贼，指日当诛夷。","使子任贼冲，尚望羽扇挥。","如何隔千里，遽求奉檄归。","长沙屹巨镇，洞庭渺无涯。","鄂渚屯重兵，上游藉兵威。","当思深远谋，胡为先自萎。","此言及同寮，必为人所窥。","归以语闺门，徒惊妾与妻。","无端使禀议，在此何为辞。","望子置私忧，志立官无卑。","张巡起县令，力抗百万师。","逆徒哽喉牙，蔽遮赖涣濉。","韦宽守玉璧，臧质全盱眙。","丈夫立节义，有才尤当施。","杀身以成仁，致命须见危。","读书不念此，万卷终何裨。","但当安义命，前定无参差。","勉哉尽所职，造物不汝遗。","况复受国恩，当与相维持。","今子仕高沙，偶然脱危机。","正须加义方，岂应使同斯。","向也未得禄，遑遑不自支。","既入红莲幕，图进亦其宜。","今日宁为民，此乃无聊词。","归来事若定，又思登王畿。","胸中空扰扰，祸福不在兹。","倘能悟愚言，便可知昨非。","著枕必安寝，食淡甘如饴。","老悖非强聒，鄙见不可移。","少安当毋躁，通籍看金闺。"]},{"t":"代毛崇夫贺妇翁黄圮老生朝","f":"词","c":["东都竞风节，清裁称巨贤。","焱驰不自定，相与扶其颠。","独立黄徵君，道周性具全。","辟举既不就，言论亦无传。","当时论笃士，比之孔与颜。","陈蕃为三公，自愧不敢先。","丈人岂苗裔，德高静而专。","不清复不浊，量陂渺无边。","学问粹然正，师友承渊源。","词章玉无瑕，作者当摩肩。","向来登王畿，悟主在一言。","校雠天禄阁，朱黄手自研。","郎潜不啻足，肯羡岁九迁。","清朝奖廉退，擢居西府员。","膴仕皆坐致，高怀越拘挛。","出乘使者车，径归卧林泉。","出处无戚欣，鼻间栩栩然。","谢公恐未免，召驲行著鞭。","松山介闽浙，淑气常蜿蜒。","隆冬正凝冱，爱日回春妍。","悬弧庆生申，飘若区中仙。","仙风自难老，何须记椿年。","贱子托枌榆，扫门如宿缘。","叨在玉润选，得窥乐广天。","川涂阻拜寿，舂容陈大篇。","孺子倘可教，愿受书一编。"]},{"t":"代仲舅尚书赋江山得助楼","f":"词","c":["江山信美非吾土，王粲登楼意凄楚。","丽谯井干高则高，未免绮罗相滓污。","君家华屋照城隅，丹壁重重不知数。","谁令作此三层楼，雪脊干霄千尺所。","几番贻书来索诗，只许归田为君赋。","快哉今日真得归，无复黄尘涴巾屦。","试凭栏干俯人世，城郭村畦可枚数。","四山云物任卷舒，大江波涛恣吞吐。","晓看红日上沧溟，夜见冰蟾转天宇。","四明山水秀东南，祇恨青山不肯入城府。","我家朗朗屋百间，欲创一楼兄未许。","羡君轮奂日日新，鼛鼓一声纷郢斧。","眼明见此高突兀，骚人当得江山助。","我久欲归未得间，门巷相望才尺五。","赋诗幸不负前盟，但惭笔底无风雨。","从今造门不复问主人，醉倒楼上君莫嗔。"]},{"t":"代求子绍上魏邸寿诗","f":"词","c":["皇家基业天与隆，金枝玉叶槃石宗。","我皇圣德摩苍穹，朱邸森列庆所钟。","仲氏吹篪何雍雍，云梦八九罗心胸。","群经读遍巾箱中，笔端豪气舒长虹。","殿前玉佩声冬珑，天人眉宇辉宸枫。","大名起魏茅士封，黄幡豹尾双镇雄。","宣城名郡烦凭熊，政绩越过黄与龚。","楼前叠嶂横云空，佳句不减玄晖工。","贤王易镇甬水东，阳春有脚皆仁风。","百蛮面内文轨同，坐清聚蚁驱屯蜂。","碧海万里楼船通，天子神圣非臣功。","薰风入弦槐阴浓，新荷泛绿榴花红。","晓来佳气飞青葱，惊诧野老田家翁。","箫鼓动地光融融，堂上帝子方雍容。","清旦燕贺簪笏丛，负弩小吏随登龙。","由来降灵自神崧，难老何用齐乔松。","年年箕翼寿两宫，捧觞戏彩俱无穷。"]},{"t":"代魏丞相为钱参政寿","f":"词","c":["天台杰立沧海东，古今名士长相从。","神游八极司马子，掷金作赋孙兴公。","松窗先生千载士，文价道骨相与同。","芙蓉为裳兰为佩，一笑坐断千山峰。","向来羽扇挥群雄，貔貅给使如奴僮。","淮南草木识姓字，烽燧一扫边庭空。","勋名巍峨谢不有，天子神圣非臣功。","黄扉安坐断国论，精神自折千里冲。","东山之志意不改，归来碧落称仙翁。","调元老手自燮理，鬖鬖绿发双方瞳。","苍生颙望谢公起，中兴事业须宗工。","新冬五日记谷旦，霜馀和气回春风。","门墙老生系郡绂，欲借寿斝斟吴松。","祝公寿考与家世，山河带砺俱无穷。"]},{"t":"卢夫人挽词","f":"词","c":["名族著岗头，幽闺女教修。","良人惊梦蝶，众子慕桑鸠。","物化了难问，壸彝谁为收。","于公有佳兆，衮衮看公侯。"]},{"t":"卢甥申之自吴门寄颜乐间画笺","f":"词","c":["年来吴门笺，色泽胜西蜀。","春膏最宜书，叶叶瑩栗玉。","贤甥更好奇，惠我小画幅。","开缄粲殷红，展玩光溢目。","巧随砑光花，傅色湿丹绿。","桃杏春共妩，兰桂秋始肃。","赵昌工折枝，露华清可掬。","妙手真似之，臧去不忍触。","苟非欧虞辈，谁敢当简牍。","又闻乐间君，古篆颇绝俗。","并求数纸书，寄我慰幽独。"]},{"t":"史少师赐第赏芍药分韵得木字","f":"词","c":["帝城有仙山，双径森万玉。","洞户入深窈，突兀见华屋。","相君领众客，红药想芬馥。","霜刀妙裁剪，烟脂点冰縠。","枝弱不胜花，翠叶共斜矗。","向来争春风，桃李愧粗俗。","百卉纷何在，庭树拥新绿。","此花丈人行，俨立见幽独。","相君戴花笑，和气俱可掬。","人言此花胜，相君意倾属。","谁知心广大，何物不蒙福。","岂以庭中花，而肯弃凡木。","君看择胜具，所在可追逐。","自言居闲时，情话会亲族。","一花有可观，烂赏费银烛。","此心何拣择，寓意本无欲。","以此宰天下，以此镇藩服。","儿童与走卒，人人歌相国。","有能达此观，春风四时足。"]},{"t":"史文惠王挽词","f":"词","c":["八行源流远，三师庆系遥。","枢庭先附凤，相国荐簪貂。","感会逢千载，荣华冠四朝。","甘盘称旧学，绮季簉储寮。","历数终归舜，羹墙欲见尧。","圣图滋广大，孝治极光昭。","善类茅连茹，英才楚刈翘。","经纶任钧轴，询访及刍荛。","未急宣攘狄，先求禹格苗。","吁谟裨庙算，长策御天骄。","衮阙心勤补，羹和手自调。","临机杜如晦，处事李文饶。","越俗怀恩纪，闽人服教条。","群公推治行，所至起民谣。","晚岁车垂薛，皇慈第赐萧。","精镠杯引寿，宝玉带横腰。","潭府辉宸翰，频年走使轺。","中书输尚父，封户溢票姚。","教子躬师道，传家作世标。","绅緌成继踵，铅椠到垂髫。","持论书还著，谈经烛屡烧。","官虽居鼎鼐，乐不改箪瓢。","门外车长满，樽前客载招。","人间等游戏，物表自消摇。","几见承三接，重来侍九韶。","桑榆方借暖，蒲柳叹先凋。","洮颒俄凭几，衣冠忽葬桥。","信能依日月，端合配宗祧。","贱子惭愚懵，平时荷。"]},{"t":"史清翁次前韵觅酒以金川玉友一枕瓶西安酒一斗送之次韵","f":"词","c":["社中日相从，此意岂不真。","其初定要约，深期往来频。","今年苦多故，孤负四郊春。","清和到新秋，其间足良辰。","而我独抱痾，未能会嘉宾。","近又得玉友，风味尤可人。","思与君痛饮，欲招复逡巡。","忽焉得新酒，亟遣径入唇。","别有酒一斗，并使君意伸。","我虽不敢尝，为洗胸中尘。"]},{"t":"史敷文挽词 其三","f":"词","c":["少小相从久，自惭雌甲辰。","交情日加厚，姻好晚逾亲。","别去惊葭律，归来见棘人。","西庄行乐地，望断为沾巾。"]},{"t":"它山堰","f":"词","c":["它山堰头足奇观，百万雷霆声不断。","谁把并州快剪刀，平剪波澜成两段。","四明山深水源远，众壑会溪长漫汗。","滔天狂潦不少留，泻入长江势奔窜。","贤哉唐家王长官，欲图永利输长算。","想得惨澹经营时，下上山川应饱看。","西偏千岭相属联，惟有兹山拥东岸。","遂于此地筑横埭，截取众流心自断。","斟酌利害不全取，高下参差仅强半。","水大十分七入江，徐挹三分供溉灌。","支流瀰瀰穿郡城，脉络贯通平且缓。","旱时反此水亦足，坐使千年忘旱暵。","无穷庙祀报元功，像设森严人敢玩。","梅梁夭矫有冥助，大患于今尚能捍。","前辈所作多神灵，日月真成赤心贯。","后人小智或更易，费尽工夫随破散。","河堙盍浚谋不集，堤断河倾流甚悍。","富民缩手人受殃，仰望古人重兴叹。","老木号风波湛碧，画屏俯仰丹青焕。","更须积雨看惊湍，濡足褰裳何足惮。","去家不远时一游，短艇垂纶流可乱。","八月傥有仙槎来，便欲乘之溯天汉。"]},{"t":"玉版鲊次陆子元郎中韵","f":"词","c":["鲟黄不减鲸与鳣，逆风鼓鬣喷腥涎。","渔人不顾浪如山，谈笑坐致扁舟前。","一钩香饵不得去，何用大网相萦缠。","挥刀纷纭脔肉骨，巨口噞喁诚可怜。","珍鲊万瓮不论钱，头颅万里赪行肩。","星郎日参玉版禅，颇厌蔬食供盘筵。","尚书亲作孟宗寄，坐觉匕箸生春妍。","却笑多事张茂先，光怪异说空千年。"]},{"t":"玉霄亭玩雪","f":"词","c":["群斋高晏雪浮空，同上山城第一重。","今日无非银色界，此亭真是玉霄峰。","云迷野路舞轻鹤，风急瓦沟嘘老龙。","便欲相将游汗漫，剡溪何必访遗踪。"]},{"t":"白醉","f":"词","c":["处世难独醒，时作映檐醉。","年少足裘马，安知老夫味。","天梳与日帽，且免供酒事。","谪居幸三适，得此更惭愧。","向来六逍遥，特书见清异。","君家老希夷，相求谅同气。","曲身成直身，朝寒俄失记。","醉中知其天，不饮乃同意。","书生暂奇温，难语纯绵丽。"]},{"t":"石门洞","f":"词","c":["扁舟百里莲城回，青山中断立两崖。","清都虎豹隐不见，但见阊阖排云开。","峰回失喜大飞瀑，声震万壑惊春雷。","掀髯目极九霄外，玉虹千丈飞空来。","一冬青女靳天雪，不知聚此山之隈。","传闻神龙卧其上，宝藏击碎真琼瑰。","胸中先自无尘埃，到此更觉心崔嵬。","天风为我噀空翠，春水泻入骚人怀。","谪仙曾来写胜句，刘郎又为开天台。","我惭笔无挽牛力，醉墨满壁谁为裁。","或言龙湫更奇绝，雁山高处深云埋。","我方携筇往寻访，未知比此何如哉。"]},{"t":"石时亨饱山阁","f":"词","c":["层层得好山，是处足饱看。","君真乐山者，心地尤平宽。","生长山水县，惯见青巑岏。","筑室欲饫赏，凭虚著危栏。","天亦遂君意，俾君老其间。","场屋早得名，晚始就一官。","官又不得进，甘心乐瓢箪。","官少家食多，知更几暑寒。","朝见山岚高，暮喜山云还。","山气日夕佳，秀色几可餐。","晴雨各变态，雪月更万端。","于山真属餍，清明流肺肝。","膏粱与刍豢，与世殊咸酸。","久矣谢世纷，屏息专内观。","鬓无一茎白，八十颜如丹。","所得不既多，愈饱天不悭。","此阁本不华，何处无此山。","苟为名利驱，人境无相关。","吾乡山苦远，可望不可攀。","东楼快登眺，耸翠罗烟鬟。","年来勇欲归，匏系未许閒。","君索饱山诗，南明恍在前。","十年两访君，共醉苜蓿盘。","向时多名流，与君平生欢。","祇今几人在，一见良独难。","叔度镇金陵，道衡处瀛壖。","旧游如晨星，相望可长叹。","归梦绕故丘，非晚再挂冠。","何当泛剡溪，往从子于盘。"]},{"t":"龙潭丈室一笋穿入露满其上因赋之","f":"词","c":["一笋入屋照座寒，凌晨仍有清露漙。","益信露珠自根起，正如真水朝泥丸。","厦屋不应为汝穿，不肯屈节斜倚栏。","干霄拂云已在望，且复自保青琅玕。"]},{"t":"仲舅尚书生朝","f":"词","c":["去年生朝燕稽山，馆舍朗朗屋百閒。","红裙合乐饮彻旦，坐上众客皆酡颜。","今年生朝半归路，竹舆萧萧晓冲雨。","回头风景非去年，当时宾客今何处。","仕已喜愠曾何分，适斋未减楚子文。","鼻閒栩栩固自若，世情物态徒纷纷。","平生知足志闲退，归老乡关了无悔。","但欲年年醉西风，坐阅人閒百千岁。","人閒万事日不同，尚书人望方颙颙。","明年举酒拜公寿，安知不在槐庭中。"]},{"t":"再题行看子","f":"词","c":["先引护栏毬子骢，九马近远俱相从。","黑驹騧黄骓素骝，亦有笏面仍银鬃。","夏国一种青于蓝，五明错靴皆如龙。","或骖或引恣驰骤，坐觉隐耳声珑珑。","人间安得有此辈，一一必自天闲中。","不惟骨相异凡马，圉人贵介多雍容。","三花剪鬣自官样，空鞍更以香罗幪。","中间二者盖天马，齿虽已老气尚雄。","不知几出横门道，双立柳下青阴浓。","抬缰捽颔刷背膂，旋梳鬃尾摇清风。","人人生意马欲动，态度曲尽各不同。","韩生去我几百年，藻色尚湿青与红。","不知何时堕鸡林，万里远在东海东。","贾人携来得寓目，一见绝叹丹青工。","千金可买真不惜，忽复携去何匆匆。","亟令临写得形似，如此神骏那得逢。","开元内外马盈亿，色别为群从登封。","韩生所貌定杰出，七尺为騋八尺駥。","向来莺边系金狨，归乘款段头已童。","伏枥宁能志千里，却笑区区据鞍矍铄翁。"]},{"t":"刘望之国录惠示文卷次韵为谢","f":"词","c":["吾闻三峡江，湍流下无底。","吾闻岷峨山，耸秀且千里。","坤维气淑灵，所产多名士。","高文既铿然，特立亦卓尔。","久慕黄中刘，近有贡公喜。","亟从蜀士问，人物定谁比。","少年负奇节，论事如翻水。","万里见张胡，义激非气使。","贤关遂为寮，八尺见英伟。","诸君皆敛避，相与推德齿。","惠我舂容篇，句法参子美。","再诵平生言，作者真近似。","战国信徒劳，秦贪不知止。","汉唐取与守，反覆皆造理。","藩镇论加详，河朔纷鼎峙。","词源既渊深，浩博渺无涘。","从今使诸生，教育均蒙被。","论议归正平，辞章扫浮靡。","古人去已远，时毋分彼此。","君其挽之回，续弦须凤髓。"]},{"t":"同年郑贵温寺丞直华文阁致仕次韵为贺 其一","f":"词","c":["先生久矣爱吾庐，绝胜扬雄宅一区。","剩有珠宫来海石，不妨茅屋绕畦蔬。","来书已许寻前诺，同社方将约并驱。","更欲相邀预真率，车公岂可坐间无。"]},{"t":"同官登敕局小楼观雪","f":"词","c":["去年岁丰登，雨晹应时须。","所欠惟一雪，祈禳遍精庐。","晚亦粗飘瞥，六花舞空虚。","云气不待族，风伯随驱除。","浅春寒尚深，忽见云模糊。","撒盐压衡茅，晨兴粟生肤。","随班上原庙，恍若登蓬壶。","岧峣宫殿深，朱扉黄金铺。","百神卫灵居，半天散琼琚。","又疑守护严，宝网络明珠。","参差鹓鹭行，簪笏皆沾濡。","退归冷局中，窗间竹扶疏。","为思此绝景，往往终年无。","不应惮凌寒，闭门守红炉。","为君登危楼，深杯泛驼酥。","崔嵬瞻吴山，莽苍望西湖。","琼枝宿饥鹰，玉街走韩卢。","酒兴万里远，容我歌且呼。","坐欲斲五言，所愧李与苏。","君与工属联，灞桥去骑驴。"]},{"t":"同倪正甫尚书游西湖","f":"词","c":["旧说西湖比西子，君言西湖似贤士。","于嗟契阔十五年，一日相逢祇如此。","南山北山两高峰，春波滟滟摩青铜。","未能荡桨穷胜处，倚栏一望开心胸。","老我挂冠隐田里，岂知再见烟连水。","小须夏日醉满荷，脱屣东归甘已矣。"]},{"t":"宇文枢密借示范宽春山图妙绝一时以诗送还","f":"词","c":["范生本以宽得名，不学关仝与李成。","笔端自出一机杼，理通神会真其能。","横披小轴屡到眼，颇亦时能辨真赝。","未见弘大如公藏，茂树乔山春烂漫。","此图不是江南山，寒空青嶂疑商颜。","高高下下几佳处，庄家时有茅三间。","桥梁楼观各有趣，一夫驱驴何处去。","安得随入杳霭间，布袜青鞋踏空雾。","近山忽断见遥碧，天涯一望无中极。","胸中丘壑谁测知，铁屋石人惊笔力。","鹅溪六幅高堂空，终日对坐心神融。","看罢为我捲还客，自此归余境梦中。"]},{"t":"戌溪道中","f":"词","c":["寒潮高于埭，黄流濯西河。","人牛力俱壮，相与冲流过。","潮落势叵禦，转棹依丘阿。","暮霭起平楚，阴云翳寒莎。","夜分潮复上，橹声相轧摩。","大江渺无津，不知身在何。","馀生一虚舟，兀然听风波。","吾亲白云下，况尔方卧痾。","远游非吾事，归矣毋蹉跎。"]},{"t":"戏答益老寄方竹杖","f":"词","c":["家家竹杖只圆光，此竹如何得许方。","削得团栾无可笑，蓦然夺去亦何妨。","咄哉，得力处不在这个。"]},{"t":"戏题圭老借庵 其一","f":"词","c":["莫道庵子是借底，只你也是借将来。","劝君莫作来生债，尽底还他亦快哉。"]},{"t":"戏题圭老借庵 其二","f":"词","c":["不知当初问谁借，至今久假而不归。","毕竟还了方是了，却须还我未生时。"]},{"t":"戏赠怡云平老","f":"词","c":["深山中拔出闲身，闹市里寻得静处。","相逢了白话三通，那个是末后一句。","不因闻所闻而来，不为见所见而去。","岭上白云君自怡，何时许得同龛住。"]},{"t":"朱季公寄诗有怀真率之集次韵","f":"词","c":["伊昔羊尹临丹阳，真率之名初滥觞。","香山尚齿当会昌，卧云不羡坐岩廊。","七人各列官与乡，年德俱高世所臧。","丙午同甲遥相望，清谈生风想琅琅。","耆英人物尤轩昂，赋诗远追白侍郎。","文富归休寿而康，衣冠十二何锵锵。","吾乡五老如雁行，至今月评尚推扬。","家舅仕宦接王杨，眉寿遂及渭水姜。","我如伤禽趁鸾凰，忽惊骑箕归银潢。","向来雅约犹宝藏，菜羹草具烹彘肪。","四皓中间有夏黄，蔼蔼义风誇句章。","年来抱痾久在床，同社阔别如河梁。","君尝远宦踰沅湘，又向封川憩甘棠。","瘴雨蛮烟暗桄榔，何时归安朝士坊。","忽传新诗几生光，敛衽正色而寒芒。","诗境几成破天荒，徐为续貂未须忙。","静揣归期应未央，归纵未衰亦老苍。","莫年甘与子同裳，何事相望天一方。"]},{"t":"次卢国华提刑所寄韵","f":"词","c":["持节归来上粉闱，祇今一节又何之。","乐天好句追长庆，元亮高风挹义熙。","我恨别多仍会少，君虽去速岂来迟。","闽山荔子熏晴昼，莫惜登临剩赋诗。"]},{"t":"次许深甫寄陈颐刚韵 其二","f":"词","c":["前朝折戟尚沙沈，志士私忧意向深。","谋国未须先问陈，平戎要且务攻心。","衣冠旧老知谁在，禾黍遗宫尚可寻。","骑省再新人有望，一言坐复故疆侵。"]}]};